/* 平成30年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h30.committeeSessions.push(...[{"id":"h30-20181109-4","meetingId":"h30-c-settlement","date":"2018年11月9日","dateIso":"2018-11-09","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時２７分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を153件整理しています。","topics":[{"id":"topic-01","title":"◯鈴木（博）委員長 ただいまより、決算特別委員会を開きます。 それでは、平成２９年度品川区一般会計歳入歳出決算","agenda":"◯鈴木（博）委員長 ただいまより、決算特別委員会を開きます。 それでは、平成２９年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"芹澤委員","kind":"質問","question":"私からは、あとは１６９ページのベンチャー創業支援事業関わって、五反田バレーのことをお伺いしたいと思います。東京都の方針を受けて、１１月１日以降の先天性風しん症候群対策事業の変更について、改めてご説明願います。","respondent":"鷹箸保健予防課長","answer":"風しん抗体検査の対象変更についてのお尋ねです。妊婦の抗体価に関わらず、同居者は全て対象とするというふうに、対象を拡大いたしました。","id":"exchange-001"},{"speaker":"芹澤委員","kind":"質問・要望","question":"対象を拡大されるということで、ぜひともこの方針で進めてほしいと求めました。各方面に働きかけていただきたいという質問があったかと思いますが、その後どうなったのか、進捗についてご説明をお願いいたします。","respondent":"鷹箸保健予防課長","answer":"大井競馬場に関してですが、ちょうど来週、１１月１２日から開催される次の開催日のときから年内を通じて掲示が決まりました。おおむね１日に二、三回、１回当たり２０から３０秒、電光掲示板で大きく掲示していただくことが決まりました。","id":"exchange-002"},{"speaker":"芹澤委員","kind":"提案","question":"こちらも引き続き、対策等の啓発を行ってほしいと求めました。区の職員の方々への感染症抗体検査の実施と、抗体価の低い方への予防接種の勧奨の提案に対するご検討と、その進捗状況のご報告をお願いいたしますとの意見を述べました。","respondent":"鷹箸保健予防課長","answer":"職員に関しての啓発および風しん抗体価の確認についてですが、２段階の方針を考えておりまして、既に動き出しております。妊婦に対応する可能性がある職員、おととい１１月７日付で、既に動き出しています。","id":"exchange-003"},{"speaker":"芹澤委員","kind":"確認","question":"その上で、品川区の見解を伺いたいのですが、スタートアップ企業というのは当然、株式会社でありますから、大きくなることを目的としております。五反田に残っていてほしいと考えていらっしゃるのか、そもそも大きくなってもオフィスを移転しないでほしいという考えでのご支援をされるのか。","respondent":"山崎商業・ものづくり課長","answer":"五反田バレーの法人化につきましては、当初５社でスタートしまして、現在では相当の数の企業が参加しています。こうしたものを含めて、しっかり地域に根づいていただくような形の誘引策を、区としてもハブ機能をつくってまいりたいと考えているところです。","id":"exchange-004"},{"speaker":"芹澤委員","kind":"確認","question":"もう一回確認なのですが、そうすると、大きくなっていくというのを前提とした上で、五反田内で新しいオフィスを借りていただく、五反田に残っていただくという認識でよろしいか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"数が多く集まるということには、何らかの意味なり付加価値というものがあってこそ、集まっていただいてとどまっていただくということにつながります。ネットワークづくりですとか、物理的にとどまっていただく、そういったことも含めて展開してまいりたいと考えているところです。","id":"exchange-005"},{"speaker":"芹澤委員","kind":"確認","question":"先ほど取り上げた協定を確認させていただいたところ、企業や行政の枠を超えたネットワークづくりというのを支援するという記載があります。３カ月過ぎている状態だと思いますが、具体的にどういう支援を品川区で行っていくのかという、今持っているビジョンなどがあればお示しください。","respondent":"山崎商業・ものづくり課長","answer":"そうした連携の強化ということを、法人側と連携しながら、例えば非常にエンジニアなどの人手不足の状況があります。こうした企業の皆さんの求人支援を何らかの形で考えるとか、いろいろ法人側とも打ち合わせをさせていただいているという状況です。","id":"exchange-006"},{"speaker":"芹澤委員","kind":"意見","question":"できるかどうかあれなのですが、実際にバスのロータリーを封鎖して、年に何度かイベント等があったかと思います。それとも、そういった支援があるとうれしいというお声もいただいていますが、それに対してのご見解を説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"今年、その中では五反田バレー関係のブースも、商店街のイベントの中で出していただいたりということで、一定その連携の芽は出ているです。協定書は７月に締結して、協定書に定めた方向性に基づいて…","id":"exchange-007"},{"speaker":"芹澤委員","kind":"質問・要望","question":"この１年という期間をぜひ更新していただいて、五反田を起業の挑戦の聖地として捉えていただけるようなブランドづくりをしてほしいと求めました。こちらは要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問","question":"１６１ページ、１６６ページ、猫の不妊・去勢手術費助成についてもお伺いいたします。各種がん検診についてお伺いいたします。","respondent":"川島健康課長","answer":"１０月の乳がん月間に合わせまして、セルフチェック用のポスターを１カ月間、約８０カ所に掲示させていただきました。乳がんではないのですが、がんの抗がん剤治療に関するミニ講演会を開催するなど、そういった展示の啓発イベントを開催しています。","id":"exchange-009"},{"speaker":"新妻委員","kind":"提案","question":"これは私が提案をさせていただきまして、このようなものが乳がん月間に合わせて１カ月、掲示をされました。そしてピンクリボン月間に合わせて、そのような活動を継続してほしいと求めましたが、いかがか尋ねました。","respondent":"川島健康課長","answer":"それから新たに乳がんの啓発のグッズも変えたいと考えておりまして、自己触診するやり方が書いてあるようなものに変えたいと考えているところですので、新しい取組みというのは順次進めていきたいと考えています。","id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"約３万５,０００人が来場するＥＣＯフェスティバルの中で、ＥＣＯフェスティバルだからこその取組みを要望いたしますが、いかがでしょうか。現状がどうかということもお伺いいたします。","respondent":"小林環境課長","answer":"取り入れられるかどうかを含めて検討を進め、また、ＥＣＯフェスティバルの取組みを区民の方に多く周知することが必要かと考えています。日常生活につながる啓発に取り組んでいきたいと考えています。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"区主催・共催のイベント等の開催時に使われるプラスチック容器がありますので、全庁的な取り組みも、ぜひ要望をします。このフードドライブをメインの会場に近いほうで行い、事前周知にも力を入れてほしいと求めましたが、いかがか尋ねました。","respondent":"小林環境課長","answer":"３万５,０００人と、周知を行ったわりには、少し少なかったのかなと我々も認識しています。場所もわかりづらいというご意見もいただいたところですので、今後、効率的な周知とあわせ、実施場所についても検討していきたいと考えています。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問・要望","question":"そこで、来年も引き続き開催できますよう、ぜひ品川区の支援をお願いしたいと思いますが、いかがでしょうか。文化プログラムの一環となるような取組みを要望いたしますが、いかがでしょうか、お伺いいたします。","respondent":"立川文化観光課長","answer":"八潮地域におきまして、さまざまな団体のご協力をいただき、実施できたと考えているところです。開催会場に最も近いまちと認識しておりますので、どういった連携ができるかというのは、今後いろいろ協議・検討していきたいと考えているところです。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問・要望","question":"１６７ページの中小企業支援費より、１６５ページの就業支援費より、就業体験事業について伺いたいと思います。そこで、どう変わったのか、この変更について商店街への周知徹底を求めますけれども、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"年度の開始の時期、区としましても各商店街の会長などにお越しいただいて、説明会を開催しているという状況です。さらにきめ細かい周知を、課としても職員一同で対応してまいりたいと考えているところです。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"次に、生鮮三品支援事業について伺いたいと思います。パンフレットの作成から５年がたちますけれども、新たなパンフレットの作成を求めますけれども、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"個店支援のメニューの流れの中で位置づけをして、ここにも生鮮三品のお店も含む２００店舗の魅力ある個店の発掘に努めてきたです。これは中小企業の事業承継支援の中で、今年度からなのですけれども、設備投資に関しての支援ということで。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"いろいろ事業は紹介していただいたのですけれども、私が伺ったのは、パンフレット作成から５年がたっているわけです。なので、新たな生鮮三品の調査や発掘、新たなパンフレットの作成を求めたのですけれども、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"そういう意味では、現状のいろいろ個店をＰＲする事業は、続けてやっております。生鮮三品の事業者のＰＲも含めて取組みをしておりますので、そういった考えのもと、今後も継続してやってまいりたいと考えているところです。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"現状の中でやられているということですが、ここに特化して注目した事業を、ぜひ進めていただきたいと要望したいと思います。２０代、３０代の雇用環境、また中小企業の採用も引き続き厳しいのに、なぜ中止としたのか、理由を伺います。","respondent":"山崎商業・ものづくり課長","answer":"若者等の就業支援事業、就業体験ということで、平成２５年度から２９年度まで５年間にわたり実施したものです。そもそもこの事業を実施するきっかけになりましたのは、平成２５年当時、各企業が非常に若者の採用が厳しい時代があったです。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"中小企業にとっても、若者を１人採用するというのは重要な決断です。職場を体験し正規雇用への道をつくっていくこの事業を、ぜひ復活してほしいと求めましたが、いかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"先ほどのいろいろな経済環境、雇用環境の変化に対応して、さまざま事業を見直し、構築する流れの中の判断です。固有のケースがありますので、そちらは引き続きやらせていただく、この分野も一生懸命対応してまいりたいという考えです。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"これが中止となったのは絶対に許せないと思います。景気の動向は置いておいても、こうした支援は引き続き、若者にとっても女性にとっても必要だと思いますので、復活を強く求めたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"いながわ委員","kind":"質問","question":"７３日で１万４,８９５名と書いてあるのですが、この診療数が妥当なのかどうなのか、お知らせください。１日２００名ぐらいが受診されているということなのですが、それをどうお考えになっているのかということを説明を求めました。","respondent":"川島健康課長","answer":"応急診療所というのは限られた人員で診療するということ、あくまでも応急的な診療であるというところが定義というか、我々の認識です。受診率の向上策、今年６月から胃がんの内視鏡検診を開始したところですが、こちらも好評をいただいていると聞いております。","id":"exchange-020"},{"speaker":"いながわ委員","kind":"質問・要望","question":"どういう感じのところに集中しているかは別にしても、電話をかけて受診となると、全然出てくれないということを地域の方から伺っております。活用できるような形にしていただきたいのですが、そういうのはどうお考えなのか、お知らせください。","respondent":"川島健康課長","answer":"それから、本当に急を要する場合というのは救急車を呼んでいただくという、それぞれの役割が違うというところもご認識いただければと考えています。そうはいっても、今まで安全面の関係でなかなか設置が難しかったということですので…","id":"exchange-021"},{"speaker":"藤原委員","kind":"質問","question":"初めに、昨日に引き続き、妊婦加算についてお伺いしますが、この制度は今年の４月に、診療報酬の改定の際に新たに設けられました。これはおかしいという思いで質問するのですが、まず、その辺についていかがか尋ねました。","respondent":"仁平品川保健センター所長","answer":"４月の診療報酬改定によりまして、この是非について区として見解を示すというのは難しいので、差し控えさせていただきたいと思います。１１月に入ってからなのですが、チラシの設置等の依頼が来ておりますので、その辺を対応していきたいと考えているところです。","id":"exchange-022"},{"speaker":"藤原委員","kind":"質問","question":"妊婦というだけで加算されてしまうのですから、これはおかしいです。いかがか尋ねました。","respondent":"仁平品川保健センター所長","answer":"妊娠期におけます健康診査関係の助成とかそういうところで、区として対応できる部分で負担の軽減等を引き続き行ってまいりたいと考えております。加算の部分の助成につきましては、現在のところといいますか、考えはございません。","id":"exchange-023"},{"speaker":"藤原委員","kind":"質問","question":"でも、１万９,８００円の１０％というと１,９８０円で、すぐ頭の中に出てしまうではないですか。いろいろな施策が必要になってくると思うのですけれども、今から考えておかないといけないと思うのですが、この辺についてはいかがか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"全体の産業振興政策の基本は、いろいろ景気のお話がありましたが、そうした変化にきちんと区としては対応していくです。そういうことで、しっかり努めてまいりたいというのが基本的な考えです。","id":"exchange-024"},{"speaker":"藤原委員","kind":"質問","question":"来年の景気動向という意味において伺っているので、企画か財政もご意見あると思うのですけれども、大きい意味で経済というのを、今どういうふうに予想し、どうつかんで、どういうふうにしていこうかという思いが、今の時点であれば教えていただけますか。","respondent":"品川財政課長","answer":"今後の景気状況というところで、いろいろと見込んでいくのは非常に難しい点があると思います。特に、中小企業と区内景気等について、この辺は重点的に動向を見ながら今後の状況を見ていき、必要に応じて対策を講じていきたいと考えています。","id":"exchange-025"},{"speaker":"吉田委員","kind":"質問・要望","question":"もしその辺で見解があれば、後で伺いたいと思います。プラスチックの発生抑制制度、根本的な発生抑制につながるような制度の検討はおありでしょうか、伺いたいと思います。","respondent":"小林環境課長","answer":"まずはこういった海洋プラスチックごみというのは、区１つで進められるようなものではなくて、世界的な取組みの中の１つと捉えているところです。プラスチックを使わない容器の導入等を進めている最中ですが、区民に対して…","id":"exchange-026"},{"speaker":"吉田委員","kind":"提案","question":"それよりも、雨水を下水に流さないで、ためて使うことの意義がわかるように強調すべきだと思いますが、ご見解を伺います。少なくとも環境課にも置くべきだし、地域センターにも置くべきと考えますが、いかがか尋ねました。","respondent":"持田河川下水道課長","answer":"このチラシの文言もいろいろ所管でも検討してございまして、今、チラシの内容につきましても変えていこうかなと考えています。チラシの設置場所を、そういった形でいろいろと庁内でも連携しながら、助成制度については引き続き広めていきたいと考えています。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問・要望","question":"入場者は前の年が２,６２４人だったのが、２,１９７人ということで、その要因はどのようにお考えでしょうか。その成果をどのようにお考えでしょうか、伺います。","respondent":"山崎商業・ものづくり課長","answer":"例えば会場設営の委託料を予定していたところ、きゅりあんで、小ホールを使う予定のイベントをイベントホールに変えたとかということによって。区としましては、消費生活活動も地域貢献活動の一つだということで…","id":"exchange-028"},{"speaker":"吉田委員","kind":"質問","question":"でも、入場者数が微減というか、全体が２,０００人台の中で、５００人程度減っていて、成果としてはどうなのかなと思います。今まで２つあった消費生活展と社会貢献活動展を一緒に合同でやって、１日の開催となった経緯について伺いたいと思います。","respondent":"遠藤協働・国際担当課長","answer":"今年度は来年の２月２３日に予定しておりますけれども、１つは団体の活動の紹介ということになるのですが、コーディネートみたいなところがあります。結論といたしまして、今回は１日で、いろいろと団体のブースを工夫したりしながらやっていきましょうという結論に落ちついたで…","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問","question":"今のご答弁だと、実行委員会が決めたということでよろしいのでしょうか。何で１日になったのかということを実行委員会の中で質問して、「予算が少なくなったことの関係ですか」と聞いたら、もう一回お願いします。","respondent":"遠藤協働・国際担当課長","answer":"予算については、昨年の平成２９年度の決算額を上回る額をこちらに確保していただいているところですので、決して縮小という方向ではございません。１日開催が実行委員会で決まったということなのですが、その返事が、１日になったと伺っております。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"その参加している人たちのやる気をそぐようなことがないように、丁寧な説明と参加者の意見交換をきちんとやっていってほしいと求めました。これは要望でとどめます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"そして１６６ページ、１６８ページ、商店街国際化推進事業についてお伺いをいたします。ほかの品川区の地域でも、こうした事例は報告されているのでしょうか、お伺いいたします。","respondent":"小林環境課長","answer":"最近になって、その状況に応じて、原因把握については引き続き努めてまいりたいと考えています。他の事例ですが、ムクドリというところだけではございませんが、そういったご相談につきましては、今年は５件ほどいただいているところです。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問","question":"そうしたところで禁煙のサポートというのが必要だと考えております。今回２１人しか集まっていないというところなので、この定員に達しない理由や原因というのはどのように考えているのでしょうか、お伺いいたします。","respondent":"川島健康課長","answer":"実は本年度は、既に５１人申し込みがあったです。そもそも治療する医師自身が知らなかったというところで、医師自身へのご案内を今年、強化してやってみたというところが現実です。","id":"exchange-033"},{"speaker":"筒井委員","kind":"質問・要望","question":"そうなのですか。もうちょっと集まってほしいということを思っておりますけれども、引き続き周知をお願いしたいのと、いかがお考えか尋ねました。","respondent":"川島健康課長","answer":"はこちらをいろいろなところで配ったりとか、啓発に活用していくというところが１つ。それから、たばこをやめることによっての健康への効果等も含めて、啓発というのはしっかりやっていくと考えています。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問","question":"品川区としては、この調査報告書などを受けて、今後具体的にどのようにインバウンド対策というのをやっていくお考えなのでしょうか。その国籍の人に対応した方策も必要だと思いますけれども、その点、いかがお考えか尋ねました。","respondent":"山崎商業・ものづくり課長、立川文化観光課長","answer":"平成２８年度に商店街支援の中で、さまざま検討しまして、まとめて報告をさせていただきました。オリンピックなどの状況もありますので、そうした基本的な取り込みを、区としましてもやってまいりたいということを考えているところです。 多いのは、中国、韓国、台湾です。","id":"exchange-035"},{"speaker":"横山委員","kind":"質問","question":"１６７ページから１７０ページまでの創業支援事業全体についてと、１７０ページ、１５６ページの母子健康診査費についてお伺いをいたします。こころの健康づくり事業についてお伺いいたします。","respondent":"榎本荏原保健センター所長","answer":"心理職の者が対応しておりまして、その中におきましても、そうした疾患のご相談も少しずつ増えてきているところです。全体の相談件数が１,１００人ぐらいの中で、６％ぐらいの方がそういったご相談が入ってきている状況です。","id":"exchange-036"},{"speaker":"横山委員","kind":"提案","question":"その次の質問なのですけれども、大学との協働の推進のところでお伺いしましたけれども、品川ビジネスクラブ助成金のところについてお伺いをします。神奈川県では大学発・政策提案制度ですとか、３大学による、まちをフィールドにした約半年間のプログラムを実施していますとの意見を述べました。","respondent":"間部大井保健センター所長、山崎商業・ものづくり課長、米田総務課長","answer":"治療としては、カウンセリングとかデイケアとか入院治療とか、さまざまそのお子様に合った対応をしているです。… 区内の継続率は３割、３０％です。そちらのコンテストには過去、賞などをとられているということで、さらにそうした連携を強化してまいりたいと考えている… 現状の大学連携推進協議会の中では、１つのアイデアかもしれませんが、少し先に向けた課題なのかなと。ただ…","id":"exchange-037"},{"speaker":"つる委員","kind":"質問・要望","question":"健康プランに関連してですが、この１１月１日からしながわ健康ポイント事業がスタートいたしました。いろいろなものにポイントがつくとありますけれども、その辺を来年度に向けて積極的に検討いただきたいのですが、簡潔にお考えを説明を求めました。","respondent":"川島健康課長","answer":"こちらは正直なところ、募集の説明会等でも、もっと頑張って多くの方に参加いただけるようにする余地はあるのかなと考えております。広く区の中のいろいろな健康づくりに資する事業をこちらに加えていくことが、区の中での広がりを持たせるために非常に重要であると考えておりま…","id":"exchange-038"},{"speaker":"つる委員","kind":"質問・要望","question":"消費者対策として、今年の予算特別委員会でも触れさせていただきましたが、エシカル消費の推進について伺いたいと思います。この間、繰り返し訴えておりますけれども、品川区としての取組み状況を説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"消費者センターでは、通常の区民向け消費者講座、あるいはエシカル消費として環境に配慮した消費行動ということで、食品ロスの削減などにつきまして周知をするということで取り組んでいるところです。","id":"exchange-039"},{"speaker":"つる委員","kind":"質問・要望","question":"その方からお話を伺って、非常に感銘を受けて、その人たちがどういう思いでそれに取り組んでいるかというところなのです。デザインの力をプラスして、価値を創造できるような取組みを支援できないかという質問なのですが、お考えがあれば説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"今、１つの企業活動をデザインするというデザイン志向といいますか、そうした考え方は非常に浸透してきていると受けとめております。今後の１つのビジネスモデルのあり方としましては、デザインといったものも活用するような…","id":"exchange-040"},{"speaker":"つる委員","kind":"質問・要望","question":"先ほどのエシカルも、今の課題も、また引き続きいろいろな形で伺っていきたいと思います。まずビニール袋を配ってどうなったかという効果と、ドギーバッグの活用について、またご意見ほしいと求めました。","respondent":"小林環境課長","answer":"どうしても持ち帰ることが必要であって、またエコバッグを持っていない方に対して、最低限お配りしたというところが現状かと思っているところです。食品ロス削減に向けては、さまざまな視点から取り組むべき課題と認識しておりますので…","id":"exchange-041"},{"speaker":"つる委員","kind":"質問","question":"けれども、入れなければごみになってしまう。やはり食べて栄養になるというほうが当然いいわけですから、しっかり口に入れてもらって、引き続き積極的な検討をお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"おくの委員","kind":"質問","question":"成果報告書の１５８ページ、保健指導費の中の難病対策費に関連した事項についてお伺いします。そこでお伺いします。","respondent":"松山障害者福祉課長","answer":"眼球使用困難症という病気に対しましてどういった支援ができるのかということで、職員が、きちんとかかりつけ医に病状の確認に行ってまいりました。その上で、どういったサービスが可能なのかというのを、ご本人と一緒にまた検討してまいりたいと考えています。","id":"exchange-043"},{"speaker":"おくの委員","kind":"質問","question":"それは、これからまたいろいろ具体策を検討されていくという理解でよろしいか尋ねました。","respondent":"松山障害者福祉課長","answer":"委員のご指摘のとおり、具体的にどういったサービスができるのかということは検討していきたいと考えています。","id":"exchange-044"},{"speaker":"おくの委員","kind":"質問・要望","question":"週に２回だけですから、食事もままならない。この２つをお聞きしたいと思います。","respondent":"寺嶋高齢者福祉課長、鷹箸保健予防課長","answer":"詳細についてはお答えが難しいのですけれども、それから主治医の意見書を加味して、第二次判定というものが行われるという仕組みになっております。１つ考えられるのは、区分変更の申請というのがありますので、区分変更ということで。 これまできちっと検討してきたかということで、難病として検討されたかという質問としてお答えしますが、現在。この４つの条件がありますけれども、現在までのところ、委員ご指摘の疾患について検討の俎上に載ったというところは…","id":"exchange-045"},{"speaker":"おくの委員","kind":"質問・要望","question":"最初にご答弁いただいたように、これからやってほしいと求めました。強く要求して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"木村委員","kind":"意見","question":"２０歳からの健康診査と、その下にある健康診査というものはどう違うのか、ご説明を願いたいと思いますとの意見を述べました。","respondent":"川島健康課長","answer":"２０歳からの健康診査につきましては、２０歳から３９歳までの区民が対象となります。健康診査のほうは、主に生活保護を受けている方の健診ということで、２つの制度は違いがあるです。","id":"exchange-047"},{"speaker":"木村委員","kind":"質問","question":"２０歳からの健康診査と、健康診査の違いはそういうことでありますけれども、そして歯科健診というものだと、５,３５４人ですか。多分、歯は一生のもので大変大事だという思いからであろうと思いますけれども、いかがか尋ねました。","respondent":"川島健康課長","answer":"委員のおっしゃるとおり、歯は大変大事であるということですが、体のほうの健康診査も重要であると考えています。","id":"exchange-048"},{"speaker":"木村委員","kind":"意見","question":"だから２０歳まで下げました」という説明というものは、区民に対してしっかりとできているのかどうか。歯は一生物ということで、その違いというか、また区民によく説明ができているかどうかということをお聞かせほしいと求めました。","respondent":"川島健康課長","answer":"２０歳からの健康診査ということになりますので、広報しながわやホームページも使って、今後も区民の方にはお知らせに努めていきたいと考えています。３５歳という４つのカテゴリーを、平成２９年度より新たに健診に加えて実施しているということで…","id":"exchange-049"},{"speaker":"木村委員","kind":"質問","question":"誰もがかかる可能性がある病気ですから、専門機関への相談や医療機関を受診することで、重症になることを防ぐことができるそうであります。ストレスの発散もしておったように自分は感じておりますけれども、現在の思春期の児童の場合はどのようにストレスを発散しているのか尋ねました。","respondent":"榎本荏原保健センター所長","answer":"そういったところで、少しネット依存という問題も起こっておりますけれども、いろんな解消の仕方ということがあるかと思います。","id":"exchange-050"},{"speaker":"木村委員","kind":"質問","question":"８５人と書かれていますけれども、心の病でありますから、本区で起きた心の病気と思われる事故はどれぐらい発生しているのでしょうか。説明を求めました。","respondent":"鷹箸保健予防課長","answer":"大体ここ１０年間で、品川区で年間７０名ぐらいの方が自殺で亡くなっています。この数というのは、昔と変わりまして、大体、交通事故死の１０倍の数になっているということが最近の問題になっております。","id":"exchange-051"},{"speaker":"木村委員","kind":"質問","question":"いずれにしても、薬物ではない何らかの対処法というものが必要と思われますけれども、どのような治療法が必要になってくるか尋ねました。","respondent":"鷹箸保健予防課長","answer":"区で進めているのは、早く専門の相談機関につなげるということを、私どもとしては推奨しております。それに関してのパンフレットもつくって周知しております。","id":"exchange-052"},{"speaker":"本多委員","kind":"質問","question":"１５３ページ、各種助成金、公衆浴場、１５６ページ、公衆便所費について質問いたします。最初に、各種助成金、公衆浴場設備等整備補助３３件について状況をお知らせください。","respondent":"川島健康課長","answer":"いわゆる銭湯が、さまざま設備機器の交換・修理等をした場合に、区で補助を出しているというものです。これは、過去に補助率が３分の１だったものを２分の１にかさ上げしてきて、公衆浴場の方たちからは言われていると私たちも感じているところです。","id":"exchange-053"},{"speaker":"本多委員","kind":"質問","question":"新たな浴場のあり方に活かすとともに、公衆衛生の場という基本的な役割に加えて、人々が心通わす交流の場としていってほしい」。この点についてどう捉えるか説明を求めました。","respondent":"川島健康課長","answer":"監査の指摘については、区内、かなりのスピードで減少しているということを捉えておっしゃっているところだと認識しております。今までの設備改修の補助以外に、また違った観点から何か支援ができないかということで、新たな事業をいろいろ起こしてきたです。","id":"exchange-054"},{"speaker":"本多委員","kind":"質問・要望","question":"１０月２０日に東京都生活文化局は、どうしたら来ていただけるか考えたいということで、来ていただいている状況などが紹介されていました。横山委員から、子ども家庭支援などの部署の事業とタイアップしながら、銭湯の持続可能性につながるような視点についてはどうお考えか尋ねました。","respondent":"川島健康課長","answer":"１点、都との連携につきましては、それから都の支援策を紹介するといった取組みを進めております。それが、他課との連携といった新たな視点を含めまして、新しい支援策を見つけていく中のヒントになるのではないかと考えているところです。","id":"exchange-055"},{"speaker":"本多委員","kind":"質問・要望","question":"事業者とも定期的な協議の場を設けていただきたいと要望いたします。防災トイレについては、災害や有事のときに便器を壊して使うとか、そういった使い方の部分ですとか、管理者について説明を求めました。","respondent":"溝口公園課長","answer":"今のところ特に考えておりませんが、さまざまネーミングライツ等を考えていく中で、引き続き検討していきたいと考えているところです。そういったものがあるということを啓発しながら、どういう形で災害時に使うのかというところについては検討していきたいと考えているところで…","id":"exchange-056"},{"speaker":"本多委員","kind":"質問・要望","question":"それで、トイレの個別案件で２カ所、質問をいたします。工事中で使えないですから仕方がないのですが、この後の水辺での船着き場工事等の整備に向けて、このトイレがどうなるのか説明を求めました。","respondent":"持田河川下水道課長、溝口公園課長","answer":"その際には、トイレを再度、現状と同様、また、だれでもトイレも加えた形でのトイレを設置する予定にしています。地域のご理解・ご協力をいただきながら、こういった事業も進めてまいりたいと考えています。 これにつきましてはおもてなしトイレ事業の中で、オリンピック・パラリンピック開催に向けて洋式化していくというふうに考えております。中を全て改装して、より利用者が利用しやすい洋式化…","id":"exchange-057"},{"speaker":"本多委員","kind":"質問","question":"大崎橋のほうのトイレなのですが、防災桟橋が完成すると同時にできるということでしょうか。もう一度、説明を求めました。","respondent":"持田河川下水道課長","answer":"桟橋本体は今年度の事業という形で進めてありますが、予定ですが、来年度から入っていきたいと思ってあります。平成３１年１２月というのを目途に事業を進めてありますので、全体の状況としては平成３１年１２月というものを目途に事業を進めているところです。","id":"exchange-058"},{"speaker":"本多委員","kind":"質問","question":"最後に１つ質問をさせてください。平成２９年度は４万８,０００カ所ということだったのですが、実績がどうだったのか、それと成果について説明を求めました。","respondent":"鈴木生活衛生課長","answer":"２年前に現地の蚊の多い場所を調査したところを、順番に回って薬を投与することで、蚊の発生を防ぐという事業に取り組んでおります。今年度もそのまま継続しているところでございまして、その途中途中で、蚊の発生抑制を続けているところです。","id":"exchange-059"},{"speaker":"あくつ委員","kind":"質問・要望","question":"第２回定例会の一般質問で、品川区独自のがん対策推進計画の策定を求めましたところ、区長からご答弁を賜りました。所管にも念のために確認したいと思いますが、いかがか尋ねました。","respondent":"川島健康課長","answer":"がん対策推進計画策定につきましては、健康プランの中間見直しと同時にというところがご心配のところだとは思うのですけれども、こちらはがん対策に特化した計画をしっかりつくっていくというふうに考えてあります。","id":"exchange-060"},{"speaker":"あくつ委員","kind":"質問","question":"改めて伺いますけれども、なぜがん対策が必要なのか、がん対策推進計画が必要だとお考えになりますか尋ねました。","respondent":"川島健康課長","answer":"それから、計画というものが、総合的に計画的に物事を進めていくということでは非常に重要だということで認識しています。国で５つ定めているのですけれども、その受診率を上げていくというためにも、がん対策推進計画というのは役に立つのではないかと考えています。","id":"exchange-061"},{"speaker":"あくつ委員","kind":"質問","question":"３位の肺炎を大きく引き離して、３０％、約３割の方はがんで亡くなっているということがあります。少し意地悪な質問をしますけれど、何でがんになるかご存じか尋ねました。","respondent":"川島健康課長","answer":"細胞の老化によるものだと認識しています。","id":"exchange-062"},{"speaker":"あくつ委員","kind":"質問・要望","question":"東大病院の中川恵一さんという、大変有名な放射線科の先生の講演に伺いまして、いろんな誤解が日本人にはあるという話を伺いました。今、がんの講座等をやられているということですが、その意図について教えてほしいと求めました。","respondent":"榎本荏原保健センター所長","answer":"がんに関しましては、先ほど健康課長が申し上げました検診の必要性ということと、予防のための知識の普及という部分が非常に大切だと考えています。２人に１人ががんになるという状況も踏まえまして、今年度はがんの予防と治療と仕事の両立支援ということで…","id":"exchange-063"},{"speaker":"あくつ委員","kind":"質問・要望","question":"やはり総合的なものを品川区で立てていただきたいと思うのですが、２３区では９区ほど、私も全部読みました。今は影も形もないと思いますけれども、何かお考えがあれば説明を求めました。","respondent":"川島健康課長","answer":"今、委員がおっしゃったとおり、まだ影も形もないというところで、これから、どのような検討組織を立ち上げて、どのような形で検討していくかというところを決めていくという段階ですが、ご心配のないように、しっかりしたものをつくりたいというところを答弁します。","id":"exchange-064"},{"speaker":"あくつ委員","kind":"質問・要望","question":"がんになっても住み続けられる品川区というものは、マストというか、これはぜひしっかりと据えてほしいと求めました。がん対策のために命をささげているような、本当に効果的ながん対策の計画をつくってほしいと求めましたが、いかがか尋ねました。","respondent":"川島健康課長","answer":"おっしゃるとおり、コンサルに丸投げするということはしないように、しっかり品川区ならではのがん対策推進計画を策定していきたいと考えています。","id":"exchange-065"},{"speaker":"あくつ委員","kind":"質問・要望","question":"持続可能性などという名前にしたのですか」と言ったら、１９７０年代にいろんな研究をしたら、そういうところから始まったと聞いております。そういうものが見えないというところなので、そういうところの見える化をぜひお願いしたいと思いますが、いかがか尋ねました。","respondent":"小林環境課長、工藤品川区清掃事務所長","answer":"そういったところを今後、検討しております施設等の中で、どういった形で表現していくか。特にわかりやすい表現と周知について、引き続きしっかり検討してまいりたいと考えています。 私ども、八潮にあります中間処理施設から、埼玉県の工場に送っております。今後、また取組みも一層推進されると考えておりますので、しっかりとその辺を考えて検討してまいりたいと考えています。","id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１６２ページ、清掃総務費、ごみ減量に関して伺いますので、よろしくお願いします。参加者と検討内容、今、一番力を入れているところは一体何なのか教えていただきたいのと、あと、自殺予防の相談体制についても説明を求めました。","respondent":"鷹箸保健予防課長","answer":"その件に関して、例えば保健センターの保健士などが個別にどういった支援ができるかといったようなことを話し合ったりということで。計画を策定するという予定で、今、関係機関も情報共有を深めて進めているところです。","id":"exchange-067"},{"speaker":"飯沼委員","kind":"提案","question":"平成２９年度の予算特別委員会のときに、啓発のパンフレットを紹介して、ぜひつくっていただきたいと提案しました。専門家の総力を挙げて、ぜひつくってほしいのですが、いかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"平成２７年度から取り組んでいる中のハンカチ形のリーフレット、教育委員会とも連携してつくっておりまして、誰でもいいから周りの大人に相談しよう。教育委員会との連携については、なお一層取り組んでいきたいと考えております。","id":"exchange-068"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それで、やはり予算もつけてしっかりとやっていただきたいと思うのですが、いかがでしょうか。共産党は予算要望の中で、ごみの３Ｒを進めて製造者責任を明確にしていくこと、また、ごみゼロ宣言をして、ごみ減量の強化をしてほしい。","respondent":"鷹箸保健予防課長、工藤品川区清掃事務所長","answer":"自殺に関しての総合的な相談窓口を設置すること、来年度、自殺対策の品川区としての計画をつくる過程の中でしっかり検討してまいりたいと存じます。 区内全体、家庭を含む総量の４７％ぐらいあるということで、ほぼ２分の１が事業ごみです。それぞれ事業者の中で、ごみ発生の抑制とリサイクルに取り組んでいただいているというのが現状です。","id":"exchange-069"},{"speaker":"飯沼委員","kind":"提案","question":"時間がなくなったのですが、身近なところのごみ減量を進めるという意味で、具体的な提案をします。これは、助成金をつくることで進めてほしいと求めましたが、いかがか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"自販機につきましては、いろいろと各所管でそれぞれ契約しているです。これにつきましては、今後どのような形でそういったことができるのかというところを研究してまいりたいと考えています。","id":"exchange-070"},{"speaker":"大沢委員","kind":"質問","question":"１６２ページの清掃総務費と、１６７ページの中小企業対策費をお伺いします。１６２ページからですけれども、ここには２１３名ということで、ご披露ください。","respondent":"工藤品川区清掃事務所長","answer":"収集という部分で光を当ててご説明いたしますと、交通安全とか作業上の安全の研修というものに力を入れてやっておるところです。特別区の中でも職層研修というのがありますので、主任、また技能長、統括技能長等に昇任した際には、そのような研修を受けているです。","id":"exchange-071"},{"speaker":"大沢委員","kind":"質問","question":"８時になりますと、８時以降に皆さん、そのあたりはどのようにやっているのか説明を求めました。","respondent":"工藤品川区清掃事務所長","answer":"先ほどご説明いたしました、日々そのような形で、日々の研修の中でやっているというものです。","id":"exchange-072"},{"speaker":"大沢委員","kind":"質問","question":"その方たちと、地域とのつながりを、どのような形で今されているのか。どのような形で地域とのつながり、ふれあい清掃などありますけれども、どのような形づくりをされているのか説明を求めました。","respondent":"工藤品川区清掃事務所長","answer":"地域の方に積極的に声かけをするというのが１つです。スケルトン車を使って清掃体験をしていただいたりといった形で、地域の中に根差した仕事、そしてまた環境学習をやっているです。","id":"exchange-073"},{"speaker":"大沢委員","kind":"意見","question":"全て品川区内が美しく保てるのも、あの方たちが雨の日も風の日も収集していただいて、あの方たちがやっていただくがためにまちがきれいになるという。もう少し、もっともっと職員の方たちに焦点を当てた取組みが必要だと思うのですけれども、どう考えますかとの意見を述べました。","respondent":"工藤品川区清掃事務所長","answer":"私ども、さまざまな、収集運搬業務もありますし、また排出指導といって、なかなか目に見えないような仕事もやっております。今後は、今の委員のご意見を参考にしながら、いろいろと検討してまいりたいと考えております。","id":"exchange-074"},{"speaker":"大沢委員","kind":"質問・要望","question":"世界にアピールするべき１つの事業だと思いますので、ぜひともしっかりとアピールしてほしいと求めましたので、よろしくお願いいたします。「小」の中に入ってしまっているのだと思うのですけれど、零細がやはり区の屋台骨としては大事だと思うのですけれども、そこを説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"中小企業の、言葉では「小さい」ということで、小規模事業所ということでもちろん捉えております。区では、８５.５％が２０名以下の小規模事業所ということが特性になっておりますので、そうしたことを踏まえて理解しています。","id":"exchange-075"},{"speaker":"大沢委員","kind":"意見","question":"８０％以上が小規模事業所ということですけれど、これは１０月ということで、年末商戦にぶつかるわけです。その辺について、区の担当課長としてどういうふうにそういう事態に対して向かっていくのか、お考えをお願いしますとの意見を述べました。","respondent":"山崎商業・ものづくり課長","answer":"消費税につきましては、２０１４年に５％から８％に変更されたということで、経緯・経過がありました。こうしたことにつきまして、区としましても丁寧に周知し、ご理解を賜るようなことが必要かと思っているところです。","id":"exchange-076"},{"speaker":"大沢委員","kind":"質問・要望","question":"税率が上がると影響を非常に大きく受けますので、その辺のところは十分にご斟酌をいただきながら政策を進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"},{"speaker":"松永委員","kind":"質問","question":"私からは、成果報告書の１５６ページの公衆便所費について、１６３ページの収集運搬作業費について、１６４ページの動物死体処理費について伺います。２つ目は、１６３ページの収集運搬作業の内容について伺います。","respondent":"溝口公園課長、工藤品川区清掃事務所長","answer":"まずはおもてなしトイレということで事業を進めておる中では、全ての公衆便所について洋式化していくということで考えているところです。来年、再来年を含めて… 比率としては、前年比で１００.７％です。警察に通報したりと、そのような対応をとっておりますが、ここ数年はそういった状況はございません。","id":"exchange-078"},{"speaker":"松永委員","kind":"確認","question":"もう一つ、今度はごみのほうなのですけれども、若干、微増という形なのですが、２３区のごみの処理は少し厳しくなっていると伺っております。そこで、本区については、こうしたことを行っている学校はあるのか、確認させてください。","respondent":"溝口公園課長、工藤品川区清掃事務所長、大関教育総合支援センター長","answer":"基本的には、これまでも、だれでもトイレ、または身障者対応トイレといったものを、３６カ所中１０カ所、整備しております。洋式化にあわせて… 委員ご指摘の埋め立て処分場の件につきましては、やはりさらなる削減が求められていると考えています。そのような分別の部分を… 学校教育の中でも社会科の授業の中で、教科書にもやはりごみの分別などは出てまいりますので、子どもたちにしっかり指導しています。","id":"exchange-079"},{"speaker":"松永委員","kind":"質問","question":"そこで質問ですが、本区内で清掃されている方よりそうした声が上がっているのでしょうか。そこで、本区ではどのような対策をとっているのか尋ねました。","respondent":"工藤品川区清掃事務所長","answer":"雇上車に乗車している運転手の方についてだと理解しております。事務室内は限られておりますが、特に今年の夏は特に暑かったということで、なるべく休憩をとられるようにお声がけをさせていただいたところです。","id":"exchange-080"},{"speaker":"たけうち委員","kind":"提案","question":"成果報告書の１５８ページ、不妊治療助成事業、１６０ページ、太陽光発電システム設置助成と、同じく１６０ページで環境費全般について伺います。私も平成２８・２９年の代表質問で提案してまいりましたので、今、その状況について非常に気になるところですとの意見を述べました。","respondent":"川島健康課長","answer":"一般不妊治療の平成３０年度１１月現在の助成の実績ですが、２６組、１２８万８,１８０円の助成の状況です。それから、制度を創設しました特定不妊治療医療費助成につきましては、１１月現在で２４組、１０７万３,６８６円、助成の実績があるという状況です。","id":"exchange-081"},{"speaker":"たけうち委員","kind":"質問","question":"すみません。いわゆる６２０件に対して２６件、５９０件に対して２４件ということなのか、説明を求めました。","respondent":"川島健康課長","answer":"答え方が少し違うのですけれども、２６件、２４件という助成実績です。まだ先のほうがなかなか読めないというのが正直なところですが、これから特定不妊治療助成は数が増えてくるのではないかと見ているところです。","id":"exchange-082"},{"speaker":"たけうち委員","kind":"質問・要望","question":"平成２９年度でいくと、不妊治療助成事業全体の実績が８３８件となっているのですが、その辺の要因がもしわかれば教えてほしいと求めました。","respondent":"川島健康課長","answer":"制度変更で、３５歳以上４２歳未満というふうに年齢を少し変更したというところ、もしかすると私どもの予算の見込みよりも少なくなるのではないかというような分析をしています。","id":"exchange-083"},{"speaker":"たけうち委員","kind":"確認","question":"１点確認ですけれど、平成２９年の代表質問のときに、国がペナルティーとして国保への国庫負担金の減額調整をしていたと。もしこの金額と、それがどのような形で活用されているか、わかりましたら説明を求めました。","respondent":"品川財政課長","answer":"国保減額調整措置の件ですけれども、今年度、金額が、おおむね９００万円程度となっております。それで、どこに充当したかというところですけれども、不妊治療助成事業に充当しています。","id":"exchange-084"},{"speaker":"たけうち委員","kind":"確認","question":"事務事業概要等で確認しますと、平成２５・２６年当時は、それで平成２９年はここにあるとおり２０件と。ホームページを先ほど確認したら増えていたのですけれども、固定価格の買い取り制度も来年で１０年を迎えて、何かわかれば説明を求めました。","respondent":"小林環境課長","answer":"固定価格買い取り制度の終了というところも１点あるかと思いますが、大きく、我々としては２点考えているところです。この周知については、引き続き、区と都が連携して実施を進めて、周知、また設置の拡大に努めていくといったところです。","id":"exchange-085"},{"speaker":"たけうち委員","kind":"質問・要望","question":"これは要望で結構です。お伺いしたいのが、それから戸越台中学校の複合施設が平成８年とか、その辺のご見解を説明を求めました。","respondent":"立木経理課長","answer":"第二庁舎の太陽光パネルは、平成６年、庁舎竣工時に設置されているものでございまして、２４年ほどたちます。設計寿命等は２０年程度と言われておりますが、設備の老化状況等を見ながら、改修等は考えていくということになると考えています。","id":"exchange-086"},{"speaker":"たけうち委員","kind":"意見","question":"大体２０年から３０年ぐらいと言われておりますので、そろそろ区の施設でも更新を迎える時期が来ているものが少しあるかと考えています。そこも場合によっては一括でやることでのコスト削減みたいなことも、あわせて考えていったらいいのではないかと思うのですが…","respondent":"小林環境課長","answer":"いろいろと検討の中では、さまざまな手法の導入については検討していきまして、適切なものを選択していくということを今後も考えていきたいと思ってあります。","id":"exchange-087"},{"speaker":"たけうち委員","kind":"質問","question":"リースは１つの例えですので、明確にしていただいた上でやっていただくのが大事かと思いますので、よろしくお願いします。何か、区で聞いているところがありましたら、またその内容についてもご説明ください。","respondent":"小林環境課長","answer":"日本版として、今年８月に発足しまして、現在、日本では１０自治体が登録していると聞いているところです。１つの流れとしましては、温室効果ガス削減がどのように進んだかというところを報告していくといった手順が、大きな流れと捉えているところです。","id":"exchange-088"},{"speaker":"たけうち委員","kind":"質問・要望","question":"まだ本当に始まったばかりで、実は東京２３区の中でも、まだどこも特にこの誓約に署名はしていないと聞いております。何がどうなのだということもあるかもしれませんけれども、しっかり連携しながら取り組んでいただきたいと思うのですが、お考えを説明を求めました。","respondent":"小林環境課長","answer":"品川区がしっかりと温暖化対策を実施していくというアピールは、１つ、区民の環境意識の向上につながるものと認識しています。こういった世界的な大きな取組みの中で、今後も引き続き、動向等を注視しながら検討していきたいと考えています。","id":"exchange-089"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"このほかには東京都や国などの助成はあるのか、あるのであれば、どういう中身があるのかということについても教えてほしいと求めました。この区有施設は何キロワットついているのかということも、一覧表に入れていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"小林環境課長","answer":"新築あるいは既存建物への設置、なかなか示すことは難しいかと考えておりますが、我々が助成する金額が１０％弱といったところかと捉えてあります。建物の立地状況あるいは使用用途にも応じて、さまざま検討した上で導入は進めてまいりたいと考えています。","id":"exchange-090"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は改めて、この費用の助成額を増額していただきたいと思っているのですけれども、いかがでしょうかということが１点です。もっとすることが必要なのではないかと思うのですけれど、その２点、いかがか尋ねました。","respondent":"小林環境課長","answer":"ほかにもＬＥＤの設置助成というところも行っているところでございまして、これも設置費用の１０％程度というところで、今後。広報紙にも定期的に掲載するなど、引き続き啓発の工夫はしてまいりたいと考えています。","id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"福島原発事故を起こして、運用開始から４０年を超えた原発まで次々と再稼働させていくという方針があると思うのです。もっと増やすし、世界の趨勢に追いつくことになっていくのではないかと思うのですけれども、そういう点についてはいかがか尋ねました。","respondent":"小林環境課長","answer":"国のやるべき施策につきましては、一自治体として判断するようなものでは基本的にないと考えておりますので、国のエネルギー施策全体を見据えながら、区としては、その推移を見守っていく立場であると考えています。","id":"exchange-092"},{"speaker":"鈴木（真）委員","kind":"質問","question":"１６１ページ、それから３項清掃費、その関係でお聞きしていきます。それから、件数がわかれば聞きたかったのですけど、それは担当の方がいないので、款が別になるから結構です。","respondent":"仁平品川保健センター所長、工藤品川区清掃事務所長","answer":"食からの子育て支援事業から、離乳食教室の委託の状況です。少し、八潮地域センターの調理室を使って実施していますけれども、来年度に向けてはまた実施場所を工夫してまいりたいと考えているところです。 ２件は一応、苦情が解消しておりますけれど、３件が残っている。私どもの対応としましては、私どももごみの性質というか、そういった調査に入っているという状況です。","id":"exchange-093"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"離乳食教室の関係で、今もうお答えが少し出たのですけれど、やはり場所的なものが厳しいのではないかということのお話を伺っています。やむを得ないということで、地域の方々の要望にお応えしていただければということで、。","respondent":"工藤品川区清掃事務所長","answer":"平成３４年度から３９年度まで６年間の期間をとりまして、新たに生まれ変わるです。こちらのほうは、２３区からの粗大ごみ・不燃ごみを一律して処理するという関係ですので、そのような形で進んでいるです。","id":"exchange-094"},{"speaker":"鈴木（真）委員","kind":"質問","question":"そうすると、前回もお聞きしていますが、天王洲の地域のこれからを考えたときに、中継所跡地が２０２０年で変わってくる。作業としてやらなければいけない問題が残りますので、その辺をどう考えていいか、もう一回、お聞きかせください。","respondent":"工藤品川区清掃事務所長","answer":"私どもでも、何といいますか、経済性や効率性という部分を含めて検討しなければいけないと考えています。そういった部分も含めて、今後のあり方という部分を検討してまいりたいと考えております。","id":"exchange-095"},{"speaker":"鈴木（真）委員","kind":"質問","question":"今年聞いた話ですと、夏の暑さでペットボトルの量がものすごく増えて処理ができないような状況にあったということもお聞きしています。あの場所ももう、少し手狭になってきているのではないかということも含めて、資源化センターのあり方をもう一度説明を求めました。","respondent":"工藤品川区清掃事務所長","answer":"プラントもかなり老朽化が認められているということで、更新の検討時期に入っているです。そういった部分を含めて処理のやり方、あと処理能力という部分を検討してまいったというものでございまして、その経費です。","id":"exchange-096"},{"speaker":"鈴木（真）委員","kind":"質問","question":"リサイクルは非常に大事だと思っていますので、お金のかかる部分もありますけれど、区としてリサイクルに対する考え方をもう一度説明を求めました。","respondent":"工藤品川区清掃事務所長","answer":"リサイクルにつきましては、環境問題を改善するためには必要な施策です。これからもしっかりと、ごみ減量、リサイクルに取り組んでまいりたいと考えています。","id":"exchange-097"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１６６ページの品川区シルバー人材センター支援事業と、１６９ページの情報通信業等の企業間連携支援について伺います。そうすると、会員お１人当たりどれぐらいの、そういった会員たちに支払われている１人当たりの金額等をお教えほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"それから、連携事業としましては、喫煙マナーアップ啓発事業、あるいは資源回収の受付などというようなことです。そうしたことで、１２億円を、材料費など主要経費を引いて会員数約２,４００人で割りますと、年間、大体５０万円ぐらいです。","id":"exchange-098"},{"speaker":"高橋（し）委員","kind":"質問","question":"１２億円ということと、それから１人当たり約５０万円という形になりますが、この金額についてどのような評価といいますか、区としてのお考えはお持ちか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"委託を出すところの管理・指揮命令を受けない軽作業というようなところに限られているようなところがありまして、そうしたところで、なかなか契約をとるのに苦慮しているような状況ということで伺っているところです。","id":"exchange-099"},{"speaker":"高橋（し）委員","kind":"質問","question":"今お話がありましたが、８億円余りが軽作業ということで多くを占めていると。同じように決算特別委員会で少し質問させていただいたのですが、現在はそれがどのように進んで、どういう状況か尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"いろいろ検討して、この１０月から仕組みが整いまして、いろいろ挑戦中というようなことです。そうしたスキルのある高齢者の方が、そうした方々への研修なども充実させていくというようなことで、区としても伺っているところです。","id":"exchange-100"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、保育補助という言葉が出ました。何といいますか、具体的にこんなお仕事がというのをご説明いただけるとわかりやすいのですが、。","respondent":"山崎商業・ものづくり課長","answer":"就業の種類の拡大といいますか、それから地域のそうした人材不足を補う貴重な戦力としても活躍できるのではないかというようなことで、区として期待しているところです。","id":"exchange-101"},{"speaker":"高橋（し）委員","kind":"質問","question":"高齢者の方、労働派遣契約事業というのでしょうか、シルバー型人材派遣がさらに進むことを願っております。これはどういうところで、どうしてここと派遣契約の形になるのか、お願いいたします。","respondent":"山崎商業・ものづくり課長","answer":"それで、高齢者の貴重な戦力を、一般就労に近い形の就業に活かしていける仕組みを、シルバー人材センターの中で検討されておりました。しごと財団は各エリアの人材センターの取りまとめ機能も持っていまして、シルバー型人材派遣の検討も、そこを通じてやりとりされていました。","id":"exchange-102"},{"speaker":"石田（ち）委員","kind":"質問","question":"私は、成果報告書１５５ページの成人歯科健診から、歯の健康について順番に伺いたいと思います。それと、健診率で言うと何％ぐらいになるのか伺いたいと思います。","respondent":"川島健康課長","answer":"それから５,３５４人になったという平成２８年度から平成２９年度の増加理由につきましては年齢拡大の効果があったのではないかと見ております。受診率につきましては、平成２８年度が８.７３％、平成２９年度が９.１５％ということで、受診率は０.４２ポイント上がったです。","id":"exchange-103"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"全ての国民が安心して医療を受けることができる制度の実現を求めたいと言っているのですけれども、やはりなかなか歯医者にかかるというところでは。体も歯も一緒にというところで、ぜひセットにしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"川島健康課長","answer":"２０歳からの健康診査と成人歯科健診を同じような年齢の設定にしてくださいという意味だと思いますが、こちらの成人歯科健診につきましては５年に１回というところで、私どもは考えているものです。","id":"exchange-104"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"先ほど、どなたかの質問で、４０代から歯周病等が進んでいくということがありました。口腔内から見る、口腔内の健康格差といったことを、区はどのように認識されているのか尋ねました。","respondent":"川島健康課長","answer":"こちらの健診につきましては、無料で健診の機会を提供しているということ。もともと４０歳からだったものを２０歳まで、なかなか歯医者に行けない方も、こちらを利用できるのではないかと考えております。","id":"exchange-105"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"なぜそれが５年に１度なのかというところもお答えほしいと求めました。それと、口腔内の健康格差の認識もお願いします。","respondent":"川島健康課長","answer":"さらに細かく区で５歳刻みにして、さらに２０歳まで開始時期を下げたというようなところで、かなり対象を拡大しているというところ。それから、口腔内の健康格差というのは、当然、歯医者にかかれなかったりする方たちがいるということは、私どもも認識はしております。","id":"exchange-106"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ、成人歯科健診と若者の健康診査を一緒にセットにしていただきたいということを強く求めたいと思います。そして２番目に、いないのか、伺いたいと思います。","respondent":"川島健康課長","answer":"私どもの取組みというのは、今までの取組みも、新しい歯科口腔保健法の取組みと同じ目標に向いてやってきているということなので、しっかりその理念というのは踏まえた仕事になっております。","id":"exchange-107"},{"speaker":"石田（ち）委員","kind":"質問","question":"そういった理念を持っておられるのであれば、それに基づいた計画・目標はあるのでしょうかと伺ったので、お答えください。","respondent":"川島健康課長","answer":"それから４０歳以降の歯周病が増加しているため、今回の、２０歳まで成人歯科健診の年齢を下げたというところがあります。そういった目標というのは、そういう考え方は、同じ目標に向かってやっているです。","id":"exchange-108"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですので、やはりここに、しっかりとイニシアチブをとる区が、こうしたことを進めていきますということを掲げるべきではないでしょうか。そして、東京都と連携してやりましょうと言われているのですけれども、それは品川区にはないということでよろしいのか尋ねました。","respondent":"川島健康課長","answer":"私どもの成人歯科健診、それから歯科口腔保健に関する施策というのは、東京都と連携してしっかりやっているです。それから、歯科口腔保健法につきましても、健康プランの中で紹介するなどしておりますし、その辺は踏まえた形で取り組んでいるです。","id":"exchange-109"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それを踏まえて、地域の実情を踏まえて自治体も目標・計画を持とうというふうになっていますので、ぜひ今後つくっていただきたいと求めます。そうした施設を私たちも設置してほしいということを、共産党の予算要望にも毎年挙げさせていただいているのですけれども、いかがか尋ねました。","respondent":"川島健康課長","answer":"それから、歯科口腔保健支援センターというのは、今のところ、つくる考えというのはございません。こちらは無料の健診ですので、毎年実施ではないですけれども、経済的な格差がある方でも無料で受けられるというものです。","id":"exchange-110"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、きっかけを増やすためにも毎年行っていただいて、さらにきめ細やかに、やはり区民の口腔内の健康を維持していくためにも、基本的事項に沿った目標と計画を立て、支援センターもつくってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-111"},{"speaker":"伊藤委員","kind":"質問","question":"８０２０運動、それから９０１６運動、非常に好評です。歯の異常を定期的に点検していくべきだと思うのだけれども、それから健康増進等に寄与すべきと考えますが、品川区のお考えを説明を求めました。","respondent":"川島健康課長","answer":"７０歳以上の方の歯科健診につきましては、成人歯科健診と同じような形で年齢だけ延ばせばいいというものではないということです。そういった新たな健診項目をつくる必要があるというところで、今、国保医療年金課において検討しています。","id":"exchange-112"},{"speaker":"伊藤委員","kind":"質問","question":"例えば２％上乗せする商品券を発行していくとか、それから３年間続けていくと、現時点でどうお考えなのかをお聞かせください。お願いいたします。","respondent":"山崎商業・ものづくり課長","answer":"春に発行額３億円、秋に３億円というような形で、このボリュームで通常行ってまいりました。平成３１年度の予算編成をしておりまして、そうした中で、いろんなご要望なども勘案しながら検討させていただいているというような状況です。","id":"exchange-113"},{"speaker":"伊藤委員","kind":"意見","question":"そのことについてのご見解と、抽選を行った結果として８倍以上の競争率になった、このような現状が今あります。だから、矛盾した話かもしれないけれども、そういうことも含めて、３割以上が買えない現状の対応をどう考えていくのか、あわせて説明を求めました。","respondent":"山崎商業・ものづくり課長","answer":"先ほど平成２８年度から、そのはがきの抽選が大体８.６倍というようなことで、監査委員の報告はそうしたことを受けてというようなことです。プレミアム商品券については先駆的に取り組んでまいりましたので、データを分析して…","id":"exchange-114"},{"speaker":"伊藤委員","kind":"意見","question":"２％上がることで、そういうことをしていく必要があると思うのだけれども、品川区のお考えをお聞かせください。お願いいたしますとの意見を述べました。","respondent":"品川財政課長","answer":"消費税の２％アップの件ですけれども、やはりさまざまな景気の状況を見て判断という形になるかと思います。これから区内消費もどうなるかというところも、いろいろ動向があるかと思いますので、そういう面もさまざま見て研究していきたいと考えております。","id":"exchange-115"},{"speaker":"若林委員","kind":"質問・要望","question":"今後、洋式化とともに洗浄機についても積極的にご検討いただきたいということで要望しますけれども、見解を伺いたいと思います。今年度の新規事業になりますでしょうか、交流・福祉向上が目的だと思いますけれども、どのような改築に対して支援するのかについてお聞きしたいです。","respondent":"溝口公園課長、川島健康課長","answer":"設置していきたいと考えているところですが、また利用状況といったものも勘案しながら、しっかりと検討していきたいと考えているところです。公衆便所については全てオリンピックまでに洋式化を完了する予定でおります。 それで、今までのやり方と同じ支援を続けるよりも、何か新しいことも検討する必要があるということで、事業を起こしたというようなところです。２月ごろには調査結果がまとまる予定で、今、動いているところです。","id":"exchange-116"},{"speaker":"若林委員","kind":"質問・要望","question":"この場で、お願いしますという要望しかできないのですけれども、これはご要望だけさせてほしいと求めました。では、公園便所のほうのご答弁を。","respondent":"溝口公園課長","answer":"公園便所・公衆便所の整備についてお答えします。はしっかり洋式化、それとあわせて改修できるところについてはしっかり改修しながら、より多くの方が利用できるようなトイレにしたいと思います。","id":"exchange-117"},{"speaker":"須貝委員","kind":"質問","question":"実際、診療費というのは幾ら上がるのですか。妊婦自身に負担させるのではなく、社会全体で私は支えるべきものではないかと思うのですが、ご見解を説明を求めました。","respondent":"仁平品川保健センター所長","answer":"休日や夜間型の対応とはまた違ってくるかとは思いますけれども、平日、医者にかかられるとプラスになっていく。一地方自治体が支援に回るというのは、さまざまな利用のされ方がありますので、そこだけピックアップするのもさらに困難かと認識しています。","id":"exchange-118"},{"speaker":"須貝委員","kind":"質問","question":"品川区内の病院に患者が行ったとして、そこでこういうふうに加算請求されるということは、それでいいのですかという疑問を私は投げかけたいのです。これでいいのか尋ねました。","respondent":"仁平品川保健センター所長","answer":"あくまでも診療報酬の中の仕組みの話ですので、そこの部分の是非について区として見解を出すのは難しいと考えています。","id":"exchange-119"},{"speaker":"須貝委員","kind":"質問","question":"これはまた品川区の今後の事業にどのように活かしていくのでしょうか。説明を求めました。","respondent":"品川財政課長","answer":"それから、区内景況のほうにつきましては、中小企業の景況というのが四半期ごとに出されております。その動向を見て常に研究しているという状況です。","id":"exchange-120"},{"speaker":"須貝委員","kind":"質問","question":"本当は、もう品川区も方向性を変えていくべきではないのですか。それで、方向性も少しずつ変えていかなければいけないのではないか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"２５％。まだまだ根幹業種として製造業のほうのご支援と、要はさまざま最適な方策を考えながら対応させていただいているような現状です。","id":"exchange-121"},{"speaker":"石田（秀）委員","kind":"質問","question":"そういうこともあったのだけど、今度は洋式化されたら、災害のとき、どういうふうにするのですか。下水に直結などというのはなかなかできないのだから、ピットがあるところをどういうふうにするのかということだけ説明を求めました。","respondent":"川島健康課長、溝口公園課長","answer":"１日の歩数がわかると、がくっと減るというようなところがあって、これは何とかしなければと思うというようなところもあります。それから、こういうところで動機づけのきっかけとして… どう対応していくのか。そういったものについてはしっかりと検討していきたいと考えているところです。","id":"exchange-122"},{"speaker":"石田（秀）委員","kind":"質問","question":"そういうのであれば、スタンドパイプのとき、あれだけいろいろやったじゃないですか。ここはどういうふうに今、判断されているかというのをお聞きしたい。","respondent":"工藤品川区清掃事務所長","answer":"考え方といたしましては、やはり１つでもリサイクルを増やしてごみ減量をしていくです。そういった、ごみ問題という部分は、自分自身の問題であるという部分もご理解いただきながら進めているところです。","id":"exchange-123"},{"speaker":"石田（秀）委員","kind":"質問","question":"それをどうしようという議論は、どこか頭の片隅に入れておいてほしいというのは１つ。そういうことも、私はもう一度改めて考えるべきだと思っていて、その辺の考えを、もしあれば教えてもらいたい。","respondent":"工藤品川区清掃事務所長","answer":"これまでも２３区全体では、有料化という部分の具体的な検討はされておりませんが、廃棄物減量等推進審議会等でも２回ほど触れられました。したがいまして、こちらは継続してやってまいりたいと考えているところです。","id":"exchange-124"},{"speaker":"石田（秀）委員","kind":"質問","question":"それはもうそういう方向で動いてほしいので、その見解をというのと、子供の森公園のところもありますよね。私はもう、それではそこは清掃事務所も含めて、全部一体で公園の整備をするのだろうと思っているので、そこのところだけお願いします。","respondent":"柏原企画調整課長","answer":"東品川につきましては、いろいろ検討を今、進めているところですので、それに合わせた形での、今の仕事をどうするかという検討です。清掃の事務所が区のものになるというのはありますので、そういった中で、全体の中での検討というのは必要だと考えています。","id":"exchange-125"},{"speaker":"石田（し）委員","kind":"質問","question":"１６７ページ、１６７ページ、１５６ページの公衆便所費についてお伺いします。決算書には清掃等委託と書いてありましたが、そこに管理と点検も含まれているのかどうかお知らせください。","respondent":"立川文化観光課長、山崎商業・ものづくり課長、溝口公園課長","answer":"こちらは、旧東海道にあります品川宿交流館に２台、配置したものです。金額としましては２,５００万円です。 商店街の活性化につきまして、決算ベースの金額でいきますと、４億３,０００万円余というような状況です。イベント事業などに… 公衆便所の管理です。通常の清掃ですとか、また特別清掃、高圧洗浄といったものを行っているものの費用を含んだものになっているものです。","id":"exchange-126"},{"speaker":"石田（し）委員","kind":"質問","question":"４億３,０００万円ほどの支援をしているといった中で、区としては今、目的に対しての達成度というのはどのように考えられているのか教えてください。例えばできる限り、カメラ等を隠せる死角をなくしていくというような対策をとられているのか、その辺を説明を求めました。","respondent":"立川文化観光課長、山崎商業・ものづくり課長、溝口公園課長","answer":"契約の形態ですが、しながわ観光協会への委託です。リースではなくて、いわゆる機器の購入と設置作業の委託です。 そうした東京商工会議所品川支部の中では、お互い連携する形で共有の施設を設置するなどというような検討もなされていると聞いております。… 利用者が多いところは２回やっている。出入口、また中を含めて、死角がないような整備といったものも進めていきたいと考えています。","id":"exchange-127"},{"speaker":"安藤委員","kind":"質問・要望","question":"１６０ページ、環境調査測定費、航空機騒音調査に関連して、羽田新ルート計画撤回を求めて質問します。一般質問でも区長の公約について伺いましたけれども、まず改めて伺いますが、新ルート計画の中止を求めることではないのか伺います。","respondent":"鈴木都市計画課長","answer":"羽田新ルート案に対する区の考え方ですが、区民への丁寧な周知・説明、それから騒音環境の軽減について取組みを求めている。これは、これまでもこれからも、今のところ変わっていないです。","id":"exchange-128"},{"speaker":"安藤委員","kind":"質問・要望","question":"区長の公約は、計画の中止を求めることではないのかどうかと伺いました。そうなのか、そうでないのか、お答えください。","respondent":"鈴木都市計画課長","answer":"先日も第３回定例会で一般質問をいただいた中で、部長も答弁させていただきました。この答弁の中身が現在の区の考え方というところでございまして、先ほどご説明したとおりです。","id":"exchange-129"},{"speaker":"安藤委員","kind":"質問・要望","question":"本会議では、こうした質問に対して区長はお答えはなかったと思いますので、今の答弁はかみ合わないかと考えています。それで、私が伺ったのは、安全安心を最優先すると言いながら、なぜ中止を求めることにならないのか、この理由を改めて伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"これは国が国策として進めていく中で、しっかり対応を図っていただきたいです。国のほうでも、これまでもそういった対策について公表されてきているものもありますし、これからも区としてしっかり求めていきたいです。","id":"exchange-130"},{"speaker":"安藤委員","kind":"質問・要望","question":"区はこのことを伺うと、「安全は国が保障するべきであり、区は求めていく立場だ」とおっしゃいます。それで、私は、区長の公約にあるように、区民の安全安心を最優先と言うのであれば、都心ルート計画の中止しかないと思うのですが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"この基準を守らないと日本の空港には着陸できないという基準も、今、実施に向けて国も進めているところです。こうした取組みを一定、評価しながら、具体にどうやったらそれが本当にしっかり実施されていくかというところは、今後も国に強く求めていきたいです。","id":"exchange-131"},{"speaker":"安藤委員","kind":"質問","question":"それで、今の私の問いに対する課長の答弁というのは、区長の考えと同じなのでしょうか。伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"繰り返しになりますが、一般質問の中でご答弁を差し上げたところです。これは、区としての考えを述べさせていただいたところですので、同じだです。","id":"exchange-132"},{"speaker":"安藤委員","kind":"質問・要望","question":"そうではないのですか。安全安心最優先というのであれば、計画の中止を求めるべきではないのかと何度も伺っているのですが、改めて区長に伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"今、いつ確認したのだというお尋ねですが、これは繰り返しになりますが、まさに議会の本会議一般質問の中でお答えしているというところが全てです。","id":"exchange-133"},{"speaker":"安藤委員","kind":"質問・要望","question":"自民党や公明党からも、あるいは「多くの区民の理解しがたい現状がある」などの認識が示され、本会議で質問がありました。区議会は少なくとも、現状で区民の理解は得られていないという認識で一致しているのですが、品川区も同じ立場なのかどうか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"先ほど３点、オープンハウス型という説明会はこれまで４回ほど実施されてありますが、教室型の説明会がまだ実施されていないというところもあります。それから、そういった周知に関しては、区内に常設型の説明の展示ブースも設けていただきたいというところも…","id":"exchange-134"},{"speaker":"安藤委員","kind":"質問","question":"伺ったのは、区議会は、少なくとも現状で、この計画に対して区民の理解は得られていないという立場が党派を超えて出されております。区も同じ立場なのかどうかと伺いました。","respondent":"鈴木都市計画課長","answer":"第二回定例会の一般質問の中でいただいているお言葉、例えば、このまま教室型説明会が開かれないのであればというところは、区としても重く受けとめているところでございまして、それは議会のお声としてしっかり受けとめさせていただいて、それを国に強く求めていくです。","id":"exchange-135"},{"speaker":"安藤委員","kind":"質問・要望","question":"重く受けとめているということですが、私が伺ったのは、少なくとも現状で、この計画は区民の理解を得られているのかどうか。それで、その質問に対してお答えほしいと求めました。","respondent":"鈴木都市計画課長","answer":"やはりまだまだこの中身について知りたいという方もたくさんいるというのは、実感として受けているところです。そうした意味では、しっかり国に強く求めていきたいというところです。","id":"exchange-136"},{"speaker":"安藤委員","kind":"質問","question":"何度聞いてもお答えがありませんけれども、区も議会と同じ立場なのかどうかということについて、なぜお答えがないのか伺いたいというのが１つです。あるのであれば、それがいつなのか伺います。","respondent":"鈴木都市計画課長","answer":"今、言っていただいた３月以降、区長が国土交通省に行ったり、あるいは来たということはございません。","id":"exchange-137"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、今、それ以降、ないということですが、今後予定はあるのか伺いたいと思います。もし予定があるのであれば、区は、区長は、どういったことを国に伝えていこうと考えているのか伺います。","respondent":"鈴木都市計画課長","answer":"丁寧な説明ということが非常に大事だと受けとめてありますので、教室型の説明会ですとか、区としてもしっかり求めていきたい。そういった中で、今後可能性があるかもしれないです。","id":"exchange-138"},{"speaker":"安藤委員","kind":"提案","question":"あくまで可能性について、さまざまな質問や求めをしたもので、区としてはもっともな姿勢だ」と答弁いたしました。航空ルールに沿っているのか、危険であり現実的には不可能な提案だと思いますが、それぞれいかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"その中で、平成２８年の軽減に向けた取組みの中で、高度がそれまでの案よりも上がったというところもあります。今後も国には、例えば飛行高度の改善などのさらなる取組みを図っていっていただきたいというところで、区としても申しています。","id":"exchange-139"},{"speaker":"安藤委員","kind":"提案","question":"区長は国土交通省みずからができないと述べていることを提案したのでしょうか、伺いたいところですが……。〔時間切れにより答弁なし〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-140"},{"speaker":"こんの委員","kind":"質問・要望","question":"３歳児健診の健康診査の中の視力検査についてお伺いします。一人でも多くの区の幼児の屈折異常や弱視を、一日も早く区の健診によって発見され、対応・対策をしていただくよう求め、質問します。","respondent":"篠田学務課長","answer":"就学前健診につきましては、個別のお子様の対応のためにやっているということもございまして、全体の集計は実はとっていないというのが現状です。今年度でいきますと３名の方で０.１％ほど、直近３年ということでございませんけれども…","id":"exchange-141"},{"speaker":"こんの委員","kind":"質問","question":"所見があったというところの３.２％のお子さんが、この健診で、３歳児健診のときではどういう結果のお子さんだったのかということが気になります。こうした状況が起きてしまう現状は、区としてはどのように、この３歳児健診のあり方というところも含めて捉えていらっしゃいますか尋ねました。","respondent":"仁平品川保健センター所長","answer":"３歳児健診のときに保健所が、同じような検査を２次フォローということで行って、改めて検査でチェックする。その後、診察医が目の異常等をチェックして、その時点で有所見があれば、精密検査を出すというような手順になっております。","id":"exchange-142"},{"speaker":"こんの委員","kind":"質問","question":"私がお聞きしたのは、見逃されてしまうという現状があることについては、３歳児健診のあり方についてはどのようにお考えか尋ねました。","respondent":"仁平品川保健センター所長","answer":"３歳児健診における視力なのですけれども、見逃しといいますか、この時点では医師が区のマニュアルに沿った検査を行っているということになっております。","id":"exchange-143"},{"speaker":"こんの委員","kind":"意見","question":"近視、治療が遅れ、３歳児健康診査における視力検査及び保健指導を適切に実施されるようお願い申し上げます」という通達が出ているかと思います。先ほど医師の所見があったということなのですが、いま一度、この３歳児健診の視力検査のあり方についてのお考えを説明を求めました。","respondent":"仁平品川保健センター所長","answer":"現行では、３歳児健診における目の異常の発見率といいますか、特別区でも、現行の品川区と同様の検査体制をとっている区がありますけれども、ほぼ同じ程度の発見率になっておりますので、現行の健診体制では、今現在は滞りなく行えていると考えています。","id":"exchange-144"},{"speaker":"こんの委員","kind":"質問・要望","question":"先ほど確認で、適切な検査というのは、３歳児健診の場で適切だったのかというところもご認識されたほうがいいのかという気がいたします。そうしたことを導入していきながら、３歳児健診のやはり視力検査の強化を求めていきたいと思いますが、いかがか尋ねました。","respondent":"仁平品川保健センター所長","answer":"機器の導入の件につきましては、引き続き課題の一つとさせていただいておりまして、各区の導入状況等も様子を見ているところです。学会でも今、問題になっているという話もありますので、その辺の動向も見ていかなくてはいけないかと考えているところです。","id":"exchange-145"},{"speaker":"こんの委員","kind":"質問・要望","question":"そして、スクリーニングの成功率は９７％と、この学会でもおっしゃっております。こうしたことも公表されておりますので、どうかその辺も見ていただきながら、導入に向けて今後ご検討いただきたいのですが、いかがか尋ねました。","respondent":"仁平品川保健センター所長","answer":"機器の導入にあたりましては、ほかの各区の状況などもいろいろと聞いているところですけれども、やはり健診時間が長くなってしまったとか、少し暗目の静かな部屋の準備が必要だとか、環境面の課題がありますので、引き続き研究を続けていきたいと思っています。","id":"exchange-146"},{"speaker":"こんの委員","kind":"提案","question":"時間がなくなってしまいましたが、１点だけ、もったいないプロジェクト事業ですけれども、先ほど、つる委員から、ドギーバッグの質問がありました。こういったことを提案して終わりたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-147"},{"speaker":"渡部委員","kind":"質問・要望","question":"こちらがもう準備に入っているところなのでしょうけれど、もう一回、確認だけすると、環境未来館はこれからスケジュールがどういうふうになるか。プロポーザルをした上で、事業者と協議しながら内容を決定していくのかと、そこの確認だけさせてほしいと求めました。","respondent":"小林環境課長","answer":"コンセプトの検討を進めているところでございまして、所管の建設委員会におきまして、その内容についての概要をご説明したところです。事業者を決定するプロポーザルの中にそれらを含めてプロポーザルを実施するという考えで、今、考えているところです。","id":"exchange-148"},{"speaker":"渡部委員","kind":"質問・要望","question":"例えば１６７ページの商店街支援のことでお伺いさせてほしいと求めました。どうか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"商店街をめぐる１つの支援モデルといいますか、ビジネスモデルのご紹介がございました。そういう意味では、五反田で集積する新しい力などを商店街に還元するような、そういった考え方も１つあるかと思っている次第です。","id":"exchange-149"},{"speaker":"渡部委員","kind":"質問・要望","question":"というか、答えられてしまったので、ぜひやっていただきたいというところは要望で終わりますけれど。品川ビジネスクラブについて少しお伺いさせてほしいと求めました。","respondent":"山崎商業・ものづくり課長","answer":"例えばその生徒につきましては、区としても顕彰させていただき、ＳＨＩＰの利用券もお渡しするようなこともやっております。年齢などは関係ありませんので、品川の地で育った、そういったことも大いに取り込んでまいりたいとは思っているところです。","id":"exchange-150"},{"speaker":"渡部委員","kind":"質問・要望","question":"ぜひ、何か形にしてほしいとは思います。確認させていただきたいのが、もう品川区は一応、これでおしまいですということでよろしいか尋ねました。","respondent":"山崎商業・ものづくり課長","answer":"タイは５年、過去に国際的な見本市などへの出展支援でありますとか、ビジネスサポートセンターを設置したです。例えば企業の進出先を検討する際に、そうした汎用的な中小の海外進出を支援しているＪＥＴＲＯの豊富なメニューといいますか、より汎用的なものに。","id":"exchange-151"},{"speaker":"渡部委員","kind":"確認","question":"ビジネスクラブでもう一つだけ確認させていただきたかったのが、ビッグサイトでやっていますよね。ちゃんとしっかり品川区とわかるようなものを配ってほしいなどとお願いはしていたのですけれど、今はどうなっていますか。","respondent":"山崎商業・ものづくり課長","answer":"装飾につきましては、品川区として視認がいただけるようなパビリオンになるようお願いしています。ああいったものなどを用意して、一定程度、配布などするというような取組みをさせていただいているところです。","id":"exchange-152"},{"speaker":"渡部委員","kind":"意見","question":"しっかり、そういうところで広告のチャンスがありますから、やってほしいと求めました。終わりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-153"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/295139?Template=document&Id=1458#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":113501,"voices":352}},{"id":"h30-20181112-4","meetingId":"h30-c-settlement","date":"2018年11月12日","dateIso":"2018-11-12","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時２６分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を158件整理しています。","topics":[{"id":"topic-01","title":"◯鈴木（博）委員長 ただいまより決算特別委員会を開会いたします。 それでは、平成２９年度品川区一般会計歳入歳出決算","agenda":"◯鈴木（博）委員長 ただいまより決算特別委員会を開会いたします。 それでは、平成２９年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"芹澤委員","kind":"質問","question":"私からは、１８３ページの空き家等対策事業、時間があれば、１７１ページの放置自転車対策事業についてお伺いします。はここ５年の戸数が、伸びてきているのか、減ってきているのかという推移もあわせて説明を求めました。","respondent":"森住宅課長","answer":"平成３０年９月末現在で、７９９戸の空き家を確認しておるところです。ここ５年というお話ですけれども、平成２６年に実態調査をいたしまして、そこからそれほど大きく数字としては伸びているものではございません。","id":"exchange-001"},{"speaker":"芹澤委員","kind":"意見","question":"危険な空き家、いわゆる特定空家の危険を排除するとともに、空き家の有効な利活用を促進するというのが法律および条例で定められているかと思います。特定空家がこの７９９戸の中にどれほど含まれているのかということを、わかればで結構ですので、地区ごとに説明を求めました。","respondent":"森住宅課長","answer":"現在、７９９戸のうち、特定空家としてカウントしているものは、荏原地区に１戸あります。ほかの地区につきましては、特定空家等というふうに指定しているものではございませんが、不適正な管理があるものとして１０５戸と認識しております。","id":"exchange-002"},{"speaker":"芹澤委員","kind":"質問","question":"荏原地区にまずは１戸ということで、区が特定空家として認識をしてから代執行をするまでの流れ、平均的な期間等がありましたら説明を求めました。","respondent":"森住宅課長","answer":"命令という形で進めてまいりましたが、ご協力を得られず、最終的に代執行を行ったです。日数としましては、平成２７年度に認定をいたしまして、平成２８年度に実施をしたです。","id":"exchange-003"},{"speaker":"芹澤委員","kind":"質問","question":"先ほど触れたとおり、区の条例の目的には、「空き家の有効活用を推進する」という記載があります。活用の具体的な指針は記載が特にないのですが、このような事例がありましたとか、有効活用の具体的な内容がわかれば説明を求めました。","respondent":"森住宅課長","answer":"場所やタイミングであったり、時期であったりというところがなかなか難しいところです。そういった方々に連絡をとりながら、どのような対策ができるか、どのような活用ができるかという検討をしていきたいというふうに考えております。","id":"exchange-004"},{"speaker":"芹澤委員","kind":"確認","question":"もう１点、空き家ホットラインで確認した後に、他の自治体も同じかと考えています。所有者の確認、今後、協定を結ぶ準備があるのかということもあわせて説明を求めました。","respondent":"森住宅課長","answer":"空き家ホットラインの拡充も含めて検討しておりますので、その中で対応できる部分については対応していきたいというふうに考えております。それを具体的に進めていくための方策として…","id":"exchange-005"},{"speaker":"芹澤委員","kind":"意見","question":"所有者が不在の場合、その所有者にも財産がない場合の２つの場合において、債権回収をどういう流れでする予定なのかをお聞かせください。先ほどお話しいただいたとおり、もう既に代執行を何度かしているというお話でしたので、この代執行をした実績も含めて説明を求めました。","respondent":"森住宅課長","answer":"先ほど申しました代執行を行った２件につきましては、その方に求償をして代執行の費用としては回収してきているです。代執行を進めて、そのようなところも含めて、しっかり債権回収はしていきたいと考えております。","id":"exchange-006"},{"speaker":"芹澤委員","kind":"意見","question":"８００戸ほどの空き家があるということで、行政から早めにアプローチをしていただいて、情報提供等で空き家になる前に多くの方々と行政とが連携して問題解決に取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-007"},{"speaker":"新妻委員","kind":"提案","question":"１７８ページ、１７９ページ、時間がある限りお伺いをします。私が建設委員会の所属のときに、お得な割引クーポンを発行してみてはどうかと提案させていただきましたが、このことについて現状を説明を求めました。","respondent":"今井土木管理課長","answer":"昨年と合わせてですが、今年度中に５００台、そして５１ポート程度を区内に全域展開で開設していこうというふうに考えております。今後もいろいろな区のイベント等のときに、何かそういうふうなアイデアが出せるか、所管と連携して対応していきたいと思います。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問","question":"濱野区長が、「９月に災害時のシェアサイクル利用を都内で初めて決めました」と、こう答えられているものが載っておりました。災害時には大変有効と考えています。","respondent":"今井土木管理課長","answer":"現在、都内９区で連携をしておりますので、ドコモ・バイクシェアと何らかの形で災害支援という形でできないかということで協定に至ったところです。それぞれの場所に行って対応するというふうな仕組みで、今、締結しています。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問","question":"詳細を伺いました。続きまして、可動式ホーム柵整備助成について伺います。","respondent":"鈴木都市計画課長","answer":"次に、今後の整備予定駅ですが、今年度は、東急大井町線旗の台駅の３・４番線で整備が行われます。平成３１年度につきましては、東急大井町線旗の台駅の５・６番線、それから下神明駅および戸越公園駅、りんかい線の大井町駅が予定されてあります。","id":"exchange-010"},{"speaker":"新妻委員","kind":"確認","question":"確認をさせていただきました。何とか１日でも早く、事業者との間で何かやりとりがされているのか、少しでも早い設置が可能なのかどうかという見通しをお伺いいたします。","respondent":"鈴木都市計画課長","answer":"そうしたところでの下半期というところでございました。区としても、整備助成を行うものですので、その助成の協議の中で、少しでも整備が早急に行われないか協議しながら進めていきたいです。","id":"exchange-011"},{"speaker":"新妻委員","kind":"質問・要望","question":"そこで確認したいのは、この事業には、コンサルタント会社が入っておりますけれども、このコンサルタント会社はどこか。２回行われた会合で出された資料ですが、コンサルから出された内容を区が確認をして、これでいきましょうというふうにしているのかお知らせください。","respondent":"鈴木都市計画課長","answer":"それから、過去の区内の実績ですが、同様のまちづくりの委託について、１件、受注実績がございました。平成２９年度２回の懇談会の資料ですが、八潮地区の現状ですとか、修正を何度かやらせていただきながら資料として使わせていただいたです。","id":"exchange-012"},{"speaker":"新妻委員","kind":"質問","question":"今後はそのようなことにもぜひ対応していただきながら、回を重ねていくことも必要だと考えています。回を重ねていく中で、いい方向性が見出されてくるかとも思いますので、そこら辺も踏まえて、今後もぜひお願いしたいと思いますが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"八潮団地は、昭和５８年に竣工し、入居が開始されてからおおむね３５年経過しています。それが将来、しっかり役立つような何か基礎的なものとして取りまとめられるように、地域の方と一緒に考えていきたいと思います。","id":"exchange-013"},{"speaker":"新妻委員","kind":"質問・要望","question":"引き続き、暑さ対策にはぜひ取り組んでくださいというご要望もいただいております。何か翻訳機みたいなものもここにあればいいのだけれども、そういうお声もいただいておりますが、今後の区のご見解をお伺いいたします。","respondent":"溝口公園課長","answer":"そういった中、レンタル自転車、非常に人気があるような、年間を通じて１万人以上がご利用するような施設です。そういったものに取り組んでいきながら、利用状況等を踏まえ、必要であれば必要な措置をとっていきたいと考えているところです。","id":"exchange-014"},{"speaker":"新妻委員","kind":"質問","question":"羽田空港から一番近い水族館、そして羽田空港に一番近い水族館、行きも帰りも活用されるようなインバウンドの誘致のところでお伺いしたいと思います。今後の予定をお知らせください。","respondent":"溝口公園課長","answer":"しながわ水族館のインバウンド、国際化に対しての取組みですが、１つは、１１月に台湾の国際旅行博への出展、そういったものを考えています。さまざまインバウンドについては取り組んでいきたいと考えているところです。","id":"exchange-015"},{"speaker":"中塚委員","kind":"質問・要望","question":"１８０ページの広町地区整備検討委託より、１８４ページの区営住宅より、同性カップルの申込資格を伺います。ぜひＪＲに混雑解消を求めてほしいと求めましたが、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"８時台、９時台、そういった事象が起きているです。区としても状況の確認や鉄道事業者としての捉え方などを確認しながら、必要な協議を行ってまいりたいというふうに考えてあります。","id":"exchange-016"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ状況を把握していただいて、混雑解消をＪＲに申し出ていただきたいと要望しておきたいと思います。そして区に委託先から納品されている報告書には何が書かれているのか伺います。","respondent":"稲田都市開発課長","answer":"ＪＲとの共同検討と、区単独検討ということで予算が組み立てられておりますが、今ご質問の区単独検討についてですが。要するに、道路とか広場とかの関係で、どういう建物が都市計画上できるかということを検討したものです。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"なぜなのか伺いたいと思います。何ページ分あるのか、目次には何と書いてあるのか、その報告書を公開してほしいと求めましたが、いかがか尋ねました。","respondent":"稲田都市開発課長","answer":"さまざまな検討をやっていくというところにおきまして、今後さらに検討を進めていくためには、諸条件を検討する必要があるということで。検討結果、大体２００ページぐらいあるのではないかと、その程度のものです。","id":"exchange-018"},{"speaker":"中塚委員","kind":"質問","question":"なぜ見せられないのか、改めて伺います。議会の関与を否定するものだと思いますが、現段階で公開できないというのであれば、いつの段階で公開するのかあわせて伺います。","respondent":"稲田都市開発課長","answer":"そういうところにおきましては、しっかりと広町のまちづくりをやっていきたいというふうに考えて、現在、検討を進めているところです。庁舎の検討というふうなお話ですが、まだまだ検討の途中ですので、まだまだ早いというふうに考えております。","id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"ならば、同性カップルも使用者資格の対象にすべきだと思いますが、いかがでしょうか。あわせて、２３区で区営住宅の入居対象に同性カップルを認めている区がありますが、他区の状況も伺いたいと思います。","respondent":"森住宅課長","answer":"同性カップルについては、親族関係が確認できないことから、現在、入居を認めておりません。他区の状況につきましては、渋谷区、世田谷区、文京区などで、それぞれ区営住宅への入居を認めている区があります。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"同性カップルも事実婚として認めない理由は何か伺いたいと思います。事実婚であっても、異性カップルは認め、同性カップルは認めないというのは、なぜなのか伺いたいと思います。","respondent":"森住宅課長","answer":"これにつきましては、民法や戸籍法に基づきまして、住民票に記載されているものをこちらとしては確認しています。同性カップルにつきましては、親族関係が確認できないというところで認めているものではございません。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"事実婚も届出を出した結婚も、どちらも２人の合意です。そういう意味では、同性カップルについて婚姻が認められないというのは偏見だと思いますが、いかがか尋ねました。","respondent":"森住宅課長","answer":"婚姻というものにつきましては、繰り返しになりますが、民法、戸籍法で示されておす。未婚の夫というふうに書かれるですので、そういった意味で、区としては事実婚についても入居要件として認めているところです。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"実際の社会には、同性カップルが存在しているわけですから、区が同性カップルを対象にしないのは、性的指向を理由にした差別です。性的指向を理由にした差別をなくすというのが品川区の立場ではないのか伺います。","respondent":"森住宅課長","answer":"区全体でそういった方々への配慮に向けた支援でありますとか。検討していくものかと考えておりますので、関係所管と協議を進めながら、そういった対応を進めていきたいというふうに考えております。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"今どういう状況に置かれているのか、ぜひアンケートをとってほしいと求めましたが、いかがでしょうか。差別をなくし、同性カップルも対象にすることは、住宅施策の大事な要だと思いますけれども、いかがか尋ねました。","respondent":"森住宅課長","answer":"区として１つの具体的な展開として、性的マイノリティの方への区営住宅の入居も１つ議論になるのかというふうには考えております。その中で、人権啓発課等が中心となりまして、そういった議論を進めていく中で、さまざまな方の声を聞いていきたいというふうに考えております。","id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"ちょうど第５次男女共同参画のマイセルフ品川プランの素案も発表されました。ぜひ同性カップルの区営住宅への対象拡大を強く求めて質問を終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"いながわ委員","kind":"質問・要望","question":"私から３点お伺いしていきたいと思います。１７２ページの道路安全施設費には、実際、具体的に交通安全を目的に道路や路面改良を行った事例があるかどうかを教えてほしいと求めました。","respondent":"今井土木管理課長、古郡交通安全担当課長、多並道路課長","answer":"現時点では３社、区内業者１社が含まれておりますが、そちらの業者のほうに委託をして実施しています。 私からは、心の啓発ということでお答えさせていただきたいと思います。このほかにもさまざまなキャンペーンを実施しておりまして… 昨年度についても１４カ所の交差点改良ということで、啓発看板を増やすなど、そのようなことでさまざまな対策を連携をしながら進めているところです。…","id":"exchange-026"},{"speaker":"いながわ委員","kind":"質問・要望","question":"３社で区内業者が１社ということでありますが、そのような連携をとることはされているのかどうなのか、その業務内容を教えてほしいと求めました。さまざまな手法があろうかと思いますので、それをぜひ実行していただきたいと考えていますが、いかがか尋ねました。","respondent":"今井土木管理課長、古郡交通安全担当課長、多並道路課長","answer":"公有地管理におけます土地家屋調査士との連携ですけれども、今後、呼びかけてまいります。こちらは公共嘱託登記土地家屋調査士会という公共事業を推進する… まさしく学校の周りは交通事故があってはならないということで、警察と道路課と連携しまして、通学路の安全点検を実施しております。看板を設置したり… 私からは、先ほどご紹介いただいた大田区との境も含め、特にバス通りは振動等の対策は非常に気を遣わなければいけない部分でもあります。…","id":"exchange-027"},{"speaker":"いながわ委員","kind":"質問・要望","question":"ヒヤリハット地図というすばらしいものがあるわけですから、しっかりその辺は未然に事故を防ぐように努力をしてほしいと求めました。それをはるかに超越した仕組みとか、そういうものも考えていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"藤原委員","kind":"質問","question":"１７９ページの天王洲公園改修工事ですけれども、平成２９年度の監査結果において工事監査の結果が書かれていますけれども、天王洲公園のＡ・Ｂ面の改修工事が監査対象になっているのですけれども、改めてこの工事を監査の対象にした経緯と、監査の結果について教えていただけますか。","respondent":"小川監査委員事務局長","answer":"Ａ・Ｂ面が人工芝の張替えを行いまして、東京２０２０大会に向け、さらなる区民の利用に供するということで監査対象といたしました。ワールドグランプリを世界初開催したことによりまして、国内外においても当該公園をアピールするということで…","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問","question":"その監査結果を受けて、所管の課はどういうふうにこれから考えてやっていくのでしょうか。それと、スポーツの面からも、監査を受けて所管はどういうふうに考えているのか説明を求めました。","respondent":"溝口公園課長","answer":"監査委員事務局長からもお話がありましたように、スポーツの振興が１つ大きな視点にあったと思います。そのようなものをすることによって、区民だけにとどまらず、スポーツの推進に公園課としても取り組んでいきたいというふうに考えているところです。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問","question":"次、１８３ページの耐震改修についてお伺いするのですけれども、私は、９月に区民委員会の視察で北海道に行ってまいりました。もし亡くなってしまったりしたら、誰が賠償責任というのでしょうか、損害に対しての責任を負うのか尋ねました。","respondent":"長尾建築課長","answer":"その建物、塀を所有されている方、またはそれを使っている方が責任を問われることになるとは考えます。所有者または使われている方が、どの程度維持管理を適正にしているか、そのような点を含めての責任の所在の確認という話になると考えています。","id":"exchange-031"},{"speaker":"藤原委員","kind":"確認","question":"課長の答弁を伺う限り、どういう規定になっているかわからないですけれども、改めて。どこでどういうふうにするかわからないですけれども、はっきり区民の方にお知らせをしていかないと、その辺についてはいかがか尋ねました。","respondent":"長尾建築課長","answer":"まず１つとしては、建てる際に法令をきちんと守ってつくっているかどうかというところがあると考えます。そのような責任の所在につきましては個別の事案になってくるかと考えますので、一概に全て所有者が負うという話になるとは限らないと考えます。","id":"exchange-032"},{"speaker":"藤原委員","kind":"質問","question":"維持管理を何年に１回とか、そういう形でやって、維持管理をしていることの証明書とかは出ないと思うのです。しつこいですが、私は、天災ならそういうふうに賠償責任はいかないと思っておりましたので、もう１回答弁をお願いします。","respondent":"長尾建築課長","answer":"かなり専門的な部分も出てきますので、全てご自分で確認するというところは、現実的にはなかなか難しい部分もあるかと思います。定期的にご相談されたり、チェックしていただいたり、そういったところを心がけていただくのがまず１つ大事かと考えます。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問","question":"１７１ページ、１項土木管理費１目土木総務費、駅周辺等放置自転車対策事業について伺います。２点目は、配布対象となる件数と、実際に配布された件数を伺います。","respondent":"古巻防災課長","answer":"２０１７年度につきましては、マンション管理組合の防災対策等検討交流会、そういった中でお配りをしているという状況です。それから、４９２棟のそれぞれの居住者に対しまして、防災対策のハンドブックを総計で３万９,８０８部、各戸別に配布をしております。","id":"exchange-034"},{"speaker":"田中委員","kind":"確認","question":"居住者が高層マンション特有の対策を意識する必要がありますから、全戸配布の仕組みを検討されるべきと考えますが、区の見解を伺います。「高層マンション防災対策の手引き」、ハンドブックが居住者の全ての方にわたる仕組みとなっているのか確認をさせてください。","respondent":"古巻防災課長","answer":"こちらについては各戸配布をしていくということで考えておりますので、対策、啓発は進めていけるのかと考えております。それから、プラスして印刷経費としてかかってくるのかというふうに考えております。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"新規入居があったときにも、必ず住居者の手に渡る仕組みをぜひ持っていただきたいと思うのですけれども、見解を伺いたいです。コミュニケーションボードなどのツールを検討し、管理事業者と共有することも必要だと考えますが、何か検討されているのか伺います。","respondent":"古巻防災課長","answer":"転入の方への対応ですけれども、「わが家の防災ハンドブック」あるいは防災地図を転入者の方にお配りしているというようなことをやっております。韓国語版の、日本語を含めて４カ国語での対応ということで、防災地図も含めて多言語対応を今後進めていきたいと思いますので。","id":"exchange-036"},{"speaker":"田中委員","kind":"質問・要望","question":"ＮＴＴに伺ったところ、品川区内の公衆電話の設置数は３９０台で、うち屋外は２１９台ということです。品川区が一部の補助金を出すなどして、ＮＴＴに協力要請をして増設に向けた協議をぜひ進めていただきたいと考えますが、見解を伺います。","respondent":"古巻防災課長","answer":"土木費と少し離れているのかという気もしますけれども、公衆電話に関しましては、一義的には利用者の設置の判断が入ってくるのかと思います。品川区におきましては、災害時優先電話を５台ずつ備蓄をしておりまして…","id":"exchange-037"},{"speaker":"田中委員","kind":"質問・要望","question":"そのような形でＮＴＴに協力を要請して増設に向けた協議をぜひ改めて進めてほしいと求めましたが、見解を伺います。システム変更で改修になるときには、幅やラックの高さを現在の自転車に見合ったものに変更するよう求めますが、見解を伺います。","respondent":"古巻防災課長、古郡交通安全担当課長","answer":"１つの考え方ではあるかと思いますけれども、被災時に安全が確実に確保できる場所ということで、避難所での設置を進めているところですので。そのような面でさらに連絡手段の確保を進めてまいりたいと思います。 ラック幅の変更ということで、３０cmだったものを４０cmから６０cm、電動アシスト車に対応できるような形で全て改修をしています。大森駅に関しては、平置きということで設置をしています。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問","question":"なので、避難所で設置されている電話を使ってほしいというのは、ちょっと区の方向性と違うのではないかということを思います。放置自転車対策についても伺います。","respondent":"古郡交通安全担当課長、古巻防災課長","answer":"今現在、近い方は歩いてきてくださいという方針でいるところです。 避難所の公衆電話の件ですけれども、避難所は、災害時に地域での防災の拠点となる施設というふうに位置づけをしております。在宅避難の方も避難所と連絡をとっていただくということが１つは重要かと思いますし、また…","id":"exchange-039"},{"speaker":"筒井委員","kind":"質問","question":"１７７ページ、景観まちづくり推進事業、天王洲地区についてお伺いいたします。料金の再検討をされてはいかがかと思っておるのですけれども、区のご見解を説明を求めました。","respondent":"古郡交通安全担当課長","answer":"自転車等駐車場の関係でありますけれども、区では、先ほどおっしゃっていた当日利用で１５０円ということになっております。それに１時間ごと５０円だとか加算されていくものですので、やはり１日使って１５０円というのは、現在のまま実施していきたいと考えています。","id":"exchange-040"},{"speaker":"筒井委員","kind":"質問","question":"すみ分けをしているというか、利用者の利用状況の違いを踏まえて、そうした設定をされているということなのですね。１日料金については感じてしまうことになっている原因かと思うのですけれども、周知という点は、どのようにお考えか尋ねました。","respondent":"古郡交通安全担当課長","answer":"その辺の広報関係につきましては、ホームページ等を含めて広報啓発を行っていきたいと考えております。","id":"exchange-041"},{"speaker":"筒井委員","kind":"質問・要望","question":"特に狭い道路では渋滞みたいなことが起きているので、そうした工事等で作業車を道路に停車する時間帯は通勤時間帯をせめて外していただきたいと。例えば、１０時以降にやっていただくとか、また土日の活用などをやっていただきたいのですけれども、その点はいかがお考えか尋ねました。","respondent":"古郡交通安全担当課長","answer":"早朝からやらないように指導していて、実施許可は８時半ごろから出していると思うのですけれども、それは個別の案件に対して警察が許可を出しているというふうな認識をしております。","id":"exchange-042"},{"speaker":"筒井委員","kind":"意見","question":"では、個別の案件でそれぞれ対応されているということなのですけれども、そうであるならば、やはり狭い道路でそうした作業をやって停車する場合は、渋滞等を考慮していただいて、なるべく一般の方の通行の妨げにならないような配慮をお願いしたいのですけれども、その点のお考えを説明を求めました。","respondent":"今井土木管理課長","answer":"いわゆる水道、ガスなどの占用企業者または区関係の企業者等と、どのように道路を使っていくかということを年４回協議を進めております。なお、その会議には、警察の所管の方にも出席していただいて、指導、啓発をしていただいているところです。","id":"exchange-043"},{"speaker":"筒井委員","kind":"質問・要望","question":"天王洲地区についての景観重点地区指定等をお聞きしますけれども、今、検討の声をもっと広げていただきたいということを考えております。こうした景観まちづくりをやっていますという周知をもっと行っていっていただきたいのですけれども、その点、いかがお考えか尋ねました。","respondent":"鈴木都市計画課長","answer":"重点地区化にあたっては、いろいろまちづくりニュースも配布しながら、あるいは駅のほうにも置かせていただきながら進めさせていただいている。広くパブリックコメント等を行いながら、より多くの方の声をお聞きして、重点地区化に向けた検討を進めてまいりたいです。","id":"exchange-044"},{"speaker":"筒井委員","kind":"質問・要望","question":"事業者の方はどうしてもモチベーションが低くなってしまうので、特に周辺隣接地域の声もしっかり拾っていっていただきたいと考えております。これは要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"成果報告書１７４ページ、１７９ページ、公園新設改良費の中の八潮北公園改修工事についてお伺いしたいと思います。これが大井町駅のイトーヨーカドーのところに設置され、私もデザインの確認をさせていただきました。","respondent":"多並道路課長","answer":"今、しながわ観光大使シナモロールをデザインしたマンホールの蓋をイトーヨーカドーの横の歩道上につけさせていただいてあります。道路課のほうもそうですけれども、観光協会のほうにも来ているということで、そのような中で認識しています。","id":"exchange-046"},{"speaker":"高橋（伸）委員","kind":"意見","question":"平成３０年度中にまだ設置の予定があるのかないのかというところと、河川下水道課のほうでやるのかというところも問い合わせをしたいと思いますとの意見を述べました。","respondent":"多並道路課長","answer":"区内の観光資源がそこにあるということをお知らせするために設置しようということで、タイルを３カ所、工事をこれから進めようとしています。もともと２,０００枚を予定したところでしたが、６,０００枚ほどを予定して、予定しています。","id":"exchange-047"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"１７９ページ、八潮北公園改修工事に関連しまして、昨年の１１月２０日にオープンしましたスケートボード場についてお伺いしたいと思います。約１年たった中で、平成２９年度は１,１３９回というところで、どういうふうにお考えになっているのかというところを。","respondent":"溝口公園課長","answer":"委員お話のように、１１月２９日にオープン以来、もうそろそろ１周年を迎えるところです。そういったところに取り組んでいる中で、そういったものをしっかり行いながら、利用者の拡大に努めていきたいと考えているところです。","id":"exchange-048"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"公園の管理上でいろいろ検討していただきたいというのが、定期的に月に２回とか、その辺のところをお聞きしたいと思います。","respondent":"溝口公園課長","answer":"１１月１日から受付をして、今日現在で１５人の応募が来ている状況ですので、また２０名の定員を超える応募があるかと予測しています。クリアしなければいけない課題等があると思いますが、さまざま検討して、運動施設としてより充実した施設にしていきたいと考えているところで…","id":"exchange-049"},{"speaker":"つる委員","kind":"質問・要望","question":"１７１ページ、交通安全啓発費、１８３ページ、住宅費、１７７ページ、治水対策費、１７９ページ、公園新設改良費について伺いたいと思います。その上で、ヒヤリハット地図ですが、それは反映していただく頻度は、どういうタイミングでやられるのか説明を求めました。","respondent":"古郡交通安全担当課長","answer":"ヒヤリハット地図に関しては、年１回、各小学校や新聞配達の業者だとか、高齢者クラブ等に調査をかけまして、１年間に１回、結果を反映しています。反映したものを地図とホームページ等で公開しております。","id":"exchange-050"},{"speaker":"つる委員","kind":"質問・要望","question":"先日も総務費のところで確認をさせていただいて、ぜひ改善を含めて考えていただきたいのですが、これは総務費でも確認させていただきましたが。システム、仕組みが必要だと思うのですが、交通安全の担当所管としてのご意見があれば説明を求めました。","respondent":"古郡交通安全担当課長","answer":"私どものほうでは、通学路の点検等を実施するということと、警察も交通安全と生活安全と連携した形で点検を実施するということで考えております。今後も引き続き、こういった形で実施していきたい、検討していきたいと考えております。","id":"exchange-051"},{"speaker":"つる委員","kind":"提案","question":"総務費のところでも確認させていただいて、しっかりと品川区として子どもたち、区民が守られる仕組みをぜひ進めていってほしいと求めました。住宅費の中で、会派で本当にこうした委員会等で設置を求めてきた居住支援協議会について伺いたいと思いますとの意見を述べました。","respondent":"森住宅課長","answer":"これまで平成３０年度に入りまして、子ども未来部を含めて集まりまして、庁内連絡会議を８月に開催しています。東京都および先進他区へヒアリングを行いまして、情報収集を進めておりまして、今後、設立に向けて具体的に進めてまいりたいと考えています。","id":"exchange-052"},{"speaker":"つる委員","kind":"質問","question":"その住まいはどうなっているのだというところでは、さまざまな施策が連携して進んでいくと期待していますので、ぜひお願いしたいと思います。亡くなられて、そこの家財処分を区が実施した、そういうケースがあれば説明を求めました。","respondent":"森住宅課長","answer":"孤独死された方の対応ですけれども、昨年度は２件ほど実際に区営住宅の中でお亡くなりになられたという方がおられました。区のほうで処分したということもあったようですけれども、基本的には親族の方がそれぞれ、家財の処分をしていただいているという形です。","id":"exchange-053"},{"speaker":"つる委員","kind":"質問","question":"昨年度だと２件ということで、ただ、その上で、過去に区が家財処分をしたというケース、財産放棄をされたので区のほうで処分したということがあると思うのですが、その際は、どういう根拠に基づいて区が家財処分ができたのかということを説明を求めました。","respondent":"森住宅課長","answer":"家財処分につきましては、国のほうで平成２８年度に通知が出されておりまして、残置物の対応方針の策定という通知があったところです。１件１件、それぞれの対応をしていきたいというふうには考えておりますけれども、国の対応方針の策定の通知も受けまして。","id":"exchange-054"},{"speaker":"つる委員","kind":"質問","question":"ここにもうちの会派からこのところがネックではないのですかというところで言っている家財処分のところが、パッケージで契約しなければいけない。それが一般ケアであれば単身で１５万円とか、これがつくられたのか、今あるのかないのかも含めて説明を求めました。","respondent":"森住宅課長","answer":"高齢者地域支援課で進めております住宅生活支援サービス事業につきましては、事業を進めるにあたりまして、住宅課。基本的にはパッケージで、今、１５万円、２０万円といったような形でやらせていただいているところです。","id":"exchange-055"},{"speaker":"つる委員","kind":"確認","question":"事務事業概要を見ると、住宅課のところでは、空き家対策事業とか、都市計画法に基づく開発許可が他課との連携ということで一覧があるのですが、この事業も、もう１回確認ですけれども、他課との連携事業のうちの１つということでよろしいか尋ねました。","respondent":"森住宅課長","answer":"事務事業概要のほうには具体的な記載はしておりませんけれども、今後進めていきます居住支援協議会も含めまして、福祉部、高齢者地域支援課とはしっかりと連携していきたいというふうに考えております。","id":"exchange-056"},{"speaker":"つる委員","kind":"質問","question":"１５万円という金額を貯蓄するのがどうなのか、月換算は２１万円ぐらいですから、１件がまだ継続中と。なので、保険として利用者に３,０００円とか５,０００円払っていただくことによって促進されるのかと思うのですが、最後にお願いします。","respondent":"森住宅課長","answer":"それぞれの入居者の方々が一時的に費用を負担するということはなかなか難しいです。その中でも支援サービス事業を１つのスキームとして、課題とか対応策について検討していきたいというふうに思います。","id":"exchange-057"},{"speaker":"おくの委員","kind":"質問","question":"もう２年もたたないうちに返ってくるであろうこの土地を、区としては、もう検討を始められたのでしょうか。お伺いします。","respondent":"柏原企画調整課長","answer":"そのような中で、こういう協定を結んだときには、ＴＯＣの事業の進捗に基づいて、おおむね８年といったところも含めてご報告申し上げたところです。我々といたしましても、そういった期限がある中で…","id":"exchange-058"},{"speaker":"おくの委員","kind":"質問・要望","question":"この土地の利用について、私たちは、住民の方からは、認可保育園にしてほしい、特養ホーム、あるいは公園などがいいという要望を伺ってきました。こういう近隣住民の方の要望を、そういう準備に着手すべきではないかと私は思うのですけれども、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"いろいろな跡地の活用の検討というところには段階があるのだと考えています。そのような検討が進む中で、さまざまなご意見を聞くというのは、これは出てくることであろうかと思いますけれども、まずは区の中で検討です。","id":"exchange-059"},{"speaker":"おくの委員","kind":"質問・要望","question":"おおむね８年間で返還させるのだと、普通の目には映るような状況ですから、なおさら８年間で返していただきたいと言えるような状況だと思います。ですから、これまで以上に強く８年間での返還を迫る交渉をこれからはしていくべきではないかと考えますけれども、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"人員であったりだとか、重機械の手配が難しいであったりとか、さまざま理由があるというふうには聞いてあります。きちんと事業を執行していただけるようにということで、今後も引き続き交渉といいますか、話をしていきたいと考えています。","id":"exchange-060"},{"speaker":"おくの委員","kind":"質問","question":"どうも常識的に見て口先だけのように見えるという場合、つまり、法的には絶対に不可能なことなのでしょうか。この点、お伺いいたします。","respondent":"柏原企画調整課長、稲田都市開発課長","answer":"ＴＯＣが建替えをしなかったというところだけでの契約不履行は法的には難しいだろうというふうに、我々も調査している限りでは捉えています。ただ、前段階での基本協定書がありますので… ここの開発計画につきましては、一時期、協議してきたところですが、また最近、協議してきているというところで、都市計画手法等を使って建替えをやりたいというようなことで相談に来ているところです。","id":"exchange-061"},{"speaker":"おくの委員","kind":"質問・要望","question":"とにかく本格活用に向けて、いろいろ区としても準備を進めていくことを強く求めて質問を終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-062"},{"speaker":"木村委員","kind":"確認","question":"１７１ページの中ほど少し下にあります交通安全啓発費からの質問です。車や自転車を運転している人には十分に注意をしていただくこと、歩行中の人には、よく周りを確認して歩行してくださいとのお願いだと思います。","respondent":"古郡交通安全担当課長","answer":"多いのは、平成２９年に関しては７３件が違反があったというものです。そのような中で自転車の安全教育はやはり必要不可欠だと考えていますので、今後も引き続きやっていきたいと考えています。","id":"exchange-063"},{"speaker":"木村委員","kind":"質問・要望","question":"こういう場合の対処の仕方によい方法はないでしょうか。あれば参考にさせてほしいと求めました。","respondent":"古郡交通安全担当課長","answer":"注意していただくというのはもちろんですけれども、やはりあまり反抗してくるようであれば、１１０番をしていただくのが一番です。自転車安全利用キャンペーンを実施しておりますので、そうしていくことによって減少していく、そのように考えております。","id":"exchange-064"},{"speaker":"木村委員","kind":"質問","question":"安全を守るためにいろいろと教えていただいたと思いますけれども、一時停止を忘れてしまったり、そういうことが多々あるのではないかと思います。お聞きいたしますけれども、もっと自転車事故の怖さを伝えていくには、どのように区民に周知、指導されるのか尋ねました。","respondent":"古郡交通安全担当課長","answer":"区内では、スケアード・ストレートをやっておりまして、スタントマンを活用して、自転車事故の悲惨さを植えつけて、こういう運転をすると、このような事故になるということをさらに啓発しながら、さらに実施していきたいと考えております。","id":"exchange-065"},{"speaker":"木村委員","kind":"質問・要望","question":"学校でも自転車の乗り方を児童には大変厳しく教えているかと思いますけれども、そういう子どもたちに対しての教育というのでしょうか、その点についてお聞かせ願えればと思います。","respondent":"大関教育総合支援センター長","answer":"そのほかヘルメットの着用を全児童に呼びかけて、家庭にも働きかけているところです。引き続き、交通安全教育に区立学校では努めてまいります。","id":"exchange-066"},{"speaker":"木村委員","kind":"質問","question":"学校や区民集会所など交通安全教育を２３回実施し、今後も警察署などと連携しながら交通事故防止に努めていきますとのコメントを出しております。お聞きいたしますけれども、１３歳未満の子どもは、何かそういうことは可能か尋ねました。","respondent":"古郡交通安全担当課長","answer":"高齢者に関しては、なるべくヘルメットを着用するように、高齢者交通安全講習会だとか、さまざまな場面で必要性を訴えているところです。今後もそのような活動をしていきたいと考えています。","id":"exchange-067"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"最初に、屋外広告物等実態調査に関してですが、これが１,９００万円ぐらい出ている、これについて細かく教えてください。まちづくりの構想をつくっている中から、まず方針を策定してというお話があったと思うのですが、その辺についてご説明をほしいと求めました。","respondent":"今井土木管理課長、稲田都市開発課長","answer":"平成２９年度、平成３０年度の２カ年で区内全域を対象に、袖看板などの屋外広告物や道路占用物件について実態調査を実施しています。平成２９年度は品川、大崎、八潮地区で行ったところです。 その中で検討方針が出てきております。それには４つほど主な部分を挙げたのですけれども、こういうところを基本的な方針として検討していきましょうということで、進めているところです。","id":"exchange-068"},{"speaker":"鈴木（真）委員","kind":"質問","question":"急にどうしてしまったのかという話だったので、その辺が疑問があったので、それを教えてください。先に建てなければできないし、区の庁舎を移転するとしても、道路ができているからいいのだということは、そこら辺を説明を求めました。","respondent":"今井土木管理課長、稲田都市開発課長","answer":"中小企業支援ウェブマガジン等でもお知らせし、簡単なパンフレット、わかりやすいパンフレットによる周知に努めてまいりたいと考えています。 そちらで検討方針の図面等をお示しさせていただいたところなのですが、既存の補助２６号線、この点線を描いた次第です。庁舎のあり方等々、このまちの都市基盤のあり方が非常に影響してくるかとは思いますので…","id":"exchange-069"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"もう１点、都市計画総務費のことで確認するのですけれども、京浜急行が１２０周年で駅名を変えるということが出てきています。区内に６駅あって、相当な負担が出てくると思うのですけれども、こういうときは費用負担は区で持つものなのか尋ねました。","respondent":"鈴木都市計画課長","answer":"現在、１２０周年記念ということで、京浜急行電鉄がこの駅名変更の募集を行っておりまして、募集期間は既に済んでおります。これは事前に都市計画課も情報提供いただきまして、基本的には、例えば鮫洲駅などは公共施設があるということで変更しない。","id":"exchange-070"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"地域の方が相当気にしているところなので、情報が入り次第教えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-071"},{"speaker":"あくつ委員","kind":"質問・要望","question":"品川区でも当時４万人の区民が加入されていたこと、１７年前に特別区が廃止をしたこの事業ですが、導入を求めさせていただきました。この１年間、この区民交通傷害保険の導入を再度要望いたしますが、いかがか尋ねました。","respondent":"古郡交通安全担当課長","answer":"区民交通傷害保険につきましては、先ほど委員が指摘されたとおりです。区といたしましても、安価で補償も手厚いということで、前向きに検討していきたいと思います。","id":"exchange-072"},{"speaker":"あくつ委員","kind":"質問・要望","question":"いろいろ豊かな水脈を利用して神社を建てるということがやはり多いものですから、非常に安全で、十分に検討すべきかと私も思いました。改めて伺いますけれども、土木担当、どこかのところで教えてほしいと求めました。","respondent":"古巻防災課長","answer":"民間の井戸については計画の中で活用という考え方はしておりませんで、区民避難所におけます浅井戸等での確保ということで進めているところです。実態については、防災課で把握しておらないところですけれども、計画上の考え方としては以上です。","id":"exchange-073"},{"speaker":"あくつ委員","kind":"質問・要望","question":"２３区のうち１０区がこういうことをしている、井戸を活用している中で、本当に地盤沈下が心配だと東京都が言っているのですか。今、こういうふうな発信をされているのですが、この点について、防災担当課はどのようにお考えなのか伺いたいと思います。","respondent":"古巻防災課長","answer":"とはいっても、各地域の方がご自身の湧水ですとか井戸、そういったものを活用したいというような声は聞いているところであります。使い方等、３カ所につきましても、少し区の中でどのような扱いができるのかというのは考えていく必要があるのかというふうには認識をしています。","id":"exchange-074"},{"speaker":"あくつ委員","kind":"質問・要望","question":"なぜ難しいのかというところ、それは理由がよくわからないので教えていただきたいということ。これを飲んでくださいと言っているわけではないですから、生活用水として、生活用水としてみんなで地域の方で使えるようにしてほしい。","respondent":"古巻防災課長","answer":"実際に地震が起きたりした際には、当然使われてくるというふうには考えております。どのような形で活用ができるのか、活用についての支援をどのような形でできるのかということは、しっかりと受けとめて考えてまいりたいと思います。","id":"exchange-075"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ですから、品川区役所として、品川区として、区民の声があるから、それは当然そうなのですけれども、そうではなくて、選択肢を増やしていただきたい。課長、もう１回ご答弁をお願いします。","respondent":"古巻防災課長","answer":"選択肢を増やすというような考え方、さまざまな対策をしていくことで、防災の力が強まっていくというようなことがあるかと思います。井戸についても同様かとも考えられますので、そのような形で区として支援ができるのか、そういうところも含めまして考えてまいりたいと思います。","id":"exchange-076"},{"speaker":"あくつ委員","kind":"質問・要望","question":"質問も含めてなのですけれども、質問もどうしても井戸に対しての補助ありきの質問が今まで多かったので、そうではないと思うのです。やはり登録して、皆さんで活用できる、こういうことを進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"},{"speaker":"安藤委員","kind":"質問","question":"１７３ページ、道路改良費、１７８ページ、北品川駅前広場整備等検討委託、１８０ページ、大崎駅周辺地区再開発事業について伺いたいと思います。地域の方から、高齢者の方など、「車両が通る際に危ない思いを何度もした、何とかならないでしょうか」という声も伺っております。","respondent":"多並道路課長","answer":"１９８０年代にコア・スターレ西大井であったり、再開発事業を行う中で、そこの現場の状況を踏まえて改良を加えてきたところです。区としましては、より安全安心な形で開発の歩道上の空地の整備のあり方などを含めながら、いろいろ一緒に検討しながら進めているところです。","id":"exchange-078"},{"speaker":"安藤委員","kind":"質問・要望","question":"開発とかを待っている時間がないというか、どのような活用をされるかというのは、まだ不透明なところがあります。働きかけはいかがでしょうかということと、行動するよう求めたいと思いますが、いかがか尋ねました。","respondent":"多並道路課長","answer":"ただ、やはり会社の今後の利用の観点があるので難しいというお答えをいただいているところです。より安全にできるような形で、今までもいろいろな形で進めているところもありますので、そういうふうに進めていきたいと思っているところです。","id":"exchange-079"},{"speaker":"安藤委員","kind":"質問・要望","question":"平成２７年４月６日からということで、その後にこういった動きが新たに出てきているわけですから、いかがでしょうか。区としての具体的な計画案を示して協議している段階なのか伺います。","respondent":"多並道路課長、東野まちづくり立体化担当課長","answer":"これからこの土地で活用のあり方について、開発部門とよく連携を図りながら情報収集して、よりよい形で進めていきたいと思っています。対策として、これも行ってきたところもありますので… 今後のスケジュールですが、広場の説明会、都市計画審議会等々につきましては、まだ決まったスケジュールは立っておりません。今のところ、来年５月の都市計画審議会に向けまして、見直しの作業を進めているです。","id":"exchange-080"},{"speaker":"安藤委員","kind":"質問・要望","question":"北品川のほうは、現計画との差異なども東京都とよく確認しているということだったので、課長がこういうことをおっしゃっています。以上の理由から、見直しにあたっては、１２ｍの拡幅道路もしっかり白紙に戻すべきだと思いますけれども、いかがか尋ねました。","respondent":"東野まちづくり立体化担当課長","answer":"こちらにつきましては、駅前広場の計画とあわせまして、区画街路も入れた形での見直しを現在行ってあります。東京都ならびに警視庁等々との協議が詰まり次第、また区としての方針を決定次第、議会のほうにも示させていただきたいと考えています。","id":"exchange-081"},{"speaker":"安藤委員","kind":"質問","question":"もう一度伺いますけれども、５月２２日には、この貫通道路を整備しない方向も含めて検討するということなのか伺います。","respondent":"東野まちづくり立体化担当課長","answer":"その辺につきましても、あわせて今、検討しています。区画街路につきましても、このような交通結節としての機能が必要かどうかも含めまして、現在、検討をしています。","id":"exchange-082"},{"speaker":"安藤委員","kind":"質問・要望","question":"最初に伺いたいのは、航空法で定められている高さの制限があると思うのですが、航空法の最高限度がこの地域は何ｍになっているのか伺います。あわせて、この大崎駅西口Ｆ南地区で計画されている３９階建てマンションの高さは何ｍの計画なのか、まず伺います。","respondent":"稲田都市開発課長","answer":"航空法でこの地区は１５０ｍという高さになってあります。それから、３９階建てで、高さは約１４９ｍです。","id":"exchange-083"},{"speaker":"安藤委員","kind":"質問","question":"３月に都市計画決定がされて、現在の進捗と事業計画の提出、公告縦覧の時期はいつごろを予定しているのか伺いたいと思います。あわせて、予定される総事業費、補助金投入額はおよそ幾らと概算しているのか、概算でいいのですが、伺います。","respondent":"稲田都市開発課長","answer":"準備組合が詳細を検討しているというところとあわせまして、権利者の１００％の同意を目指しながら、その辺をやっているです。総事業費につきましては、今、詳細もまた改めてやってきているところなのですが、６５０億円から７００億円ぐらいです。","id":"exchange-084"},{"speaker":"安藤委員","kind":"質問","question":"なぜ１４９ｍ、３９階建てでないといけないのかと聞いても、合理的な理由は説明されません。そうなのですか、そうではないのですか、伺います。","respondent":"稲田都市開発課長","answer":"緊急整備地域に接するなど、非常にポテンシャルの高い地域として、都心の中の駅前だという地域です。居住環境等を必要としながらまちづくり進めるという中において、最終的に出てきた結果がこのような形で居住環境等をつくっていくです。","id":"exchange-085"},{"speaker":"安藤委員","kind":"質問","question":"私が伺ったのは、結局、住友不動産のもうけをマックスにするためには１４９ｍのほうがいいわけですね。そうではないのですかと聞いたので、お答えください。","respondent":"稲田都市開発課長","answer":"大崎駅周辺地区という中におきまして、今、求められている施設を整備していくというところです。現状の道路が狭かったり、老朽化した住宅があったり、こういうところを解決しながらやっていくまちづくりを進めております。","id":"exchange-086"},{"speaker":"本多委員","kind":"質問","question":"１８３ページの建築行政費、がけ・擁壁安全化支援、１７６ページ、１７７ページの河川費について質問します。予算は２０件だったのですが、１１件の決算、これが工事の実施につながったのかどうかの状況を説明を求めました。","respondent":"長尾建築課長","answer":"先ほどご紹介いただきましたように、アドバイザー派遣としては、平成２９年度は１１件ございました。その中で実際の改修工事に進んだ件数としては、今のところございません。","id":"exchange-087"},{"speaker":"本多委員","kind":"質問","question":"わかりました。所有者の協力、平成２９年度はアドバイザーを派遣したことは前進してすばらしいことだと思うのですが、その点については課題としていかがか尋ねました。","respondent":"長尾建築課長","answer":"問題意識も比較的高いと考えますが、がけ・擁壁に関しましては、なかなかそのような観点を持ちにくいのが現状だとこちらとしても認識しております。それに加えてアドバイザー派遣も必要に応じてご案内しているというところがあります。","id":"exchange-088"},{"speaker":"本多委員","kind":"質問","question":"私、議員になりまして初めての一般質問で、ブロック塀をなくし、生け垣助成の推進と、軽量で耐震性に優れた新建材の推進を取り上げました。ブロック塀に限らず擁壁や大谷石、特にブロック塀の対策とか最終目標について、その点についての考え方を説明を求めました。","respondent":"長尾建築課長","answer":"基準を守ってつくっていたとしても、時間がたてば当然劣化が進みますので、安全性が十分に確保できないことも出てくると思います。は、危険な塀と思われるところの除却を区としても支援して、安全な通行の確保を目指したいと考えております。","id":"exchange-089"},{"speaker":"本多委員","kind":"質問・要望","question":"その進み具合、全区の倒壊の危険のあるブロック塀を対象に働きかけをしていただきたいのですが、その進み具合をまずお聞かせください。避難道路に直面する危ないブロック塀です。","respondent":"長尾建築課長","answer":"避難道路沿いの塀の安全化というところですが、過去、特に滝王子通りなどは改修対応を区のほうでしたというところはございました。避難道路というわけではないのですが、通学路に関しては、教育委員会のほうでも各学校に安全点検を緊急に実施したというふうに聞いてあります。","id":"exchange-090"},{"speaker":"本多委員","kind":"質問","question":"そういった方法や具体策など、どういうものがあるか、その方法論についてお聞かせください。橋脚自体は東京モノレールが自社で耐震性とか管理はされているというのは伺っておりますけれども、考え方等あれば説明を求めました。","respondent":"鈴木都市計画課長、持田河川下水道課長","answer":"私からお答えいたしますが、水辺の利活用につきましては、区のほうでライトアップも含めてさまざまな取組みを進めてあります。１つの事例として、モノレールの橋脚の例えば壁面を使うですが、会議等の場ではまだございません。 運河エリアの中では、さまざま賑わいをつくっていこうということで、東京都がライトアップのプランなどもつくってあります。区としても、ライトアップの考え方を踏まえながら取り組んでいきたいというふうに考えてあります。","id":"exchange-091"},{"speaker":"本多委員","kind":"質問・要望","question":"遊歩道の整備にあたりましては、暗い部分への対策と、道路にＬＥＤを埋め込む整備の考え方を聞きたいと思います。理想的な要望なのですけれども、品川区と大田区の区界がないぐらいに、まずは品川区内でのＬＥＤ埋め込みの整備の考え方はいかがか尋ねました。","respondent":"持田河川下水道課長","answer":"海水の満ち潮時には、そういったところにライトを設置しても大丈夫かどうかというような視点での検討も必要だと考えています。そのような製品があるのかないのかですとか、そのような対応がとれるのかということにつきましては、少し検討してみたいと思ってあります。","id":"exchange-092"},{"speaker":"本多委員","kind":"意見","question":"擁壁修繕、西品川一丁目と上大崎三丁目で平成２９年度に実施されました。この取組みはどういうふうに展開していくのか、同じような状況があるのかどうかも、この点について説明を求めました。","respondent":"多並道路課長","answer":"区内の道路の擁壁につきましては、現在、ストック点検ということで、点検を今行っている最中です。今後、より区民の皆様が景観上好まれるような整備ができるところがあれば、そこはまたいろいろ検討していきたいと思っているところです。","id":"exchange-093"},{"speaker":"松永委員","kind":"確認","question":"はじめに、１７１ページの駅周辺等の放置自転車対策についてですが、最近、ある方より、自転車を撤去されてしまったということを伺いました。取りに来られない方に対して、何か対策はとっておられるのかお伺いします。","respondent":"古郡交通安全担当課長","answer":"平成２８年で６５.８％、平成２９年度で６６.１％、だんだん返還状況は上昇している状況です。不動前が１,０００台、八潮が２,２００台程度、まだ十分空きがあるような状況になっています。","id":"exchange-094"},{"speaker":"松永委員","kind":"確認","question":"それを聞いて安心しました。確認ですけれども、そういったところも増えてくるのではないかと思うのですけれども、そうしたときにはどのような対策をとられていくのか尋ねました。","respondent":"今井土木管理課長","answer":"実際にシェアサイクル、ポート以外に放置されたものが撤去されて保管所にあったということが複数件報告されております。事業者であるドコモ・バイクシェアからご本人に通知が行きまして、原則として利用者の方に３,０００円の負担をしていただくということになります。","id":"exchange-095"},{"speaker":"松永委員","kind":"質問・要望","question":"我が会派としても、看板設置とかを進めてくれという要望があったのかわかりませんけれども、そうした２.４ｍの看板をつけていただいております。あそこの道路に関しては、ぜひ対策をとっていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"多並道路課長","answer":"１つは、警察と品川区で看板を設置するなど、今までも対策を講じてまいりました。さらなる対策ができないかということで、今後もいろいろ検討してまいりたいと思っているところです。","id":"exchange-096"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひいろいろ対策をとっていただきたいのですが、城南信用金庫の前に関しましては、ぜひ一灯式信号機の設置を要望いたします。最後に、水質改善について伺いたいと思います。","respondent":"小林環境課長","answer":"水が滞留しやすい地形的なものとか、さまざまある中で、そういうものが総合的に重なってこのような結果になったのかと認識しています。引き続き、調査結果が高い状態となれば、関係課とか周辺区と連携を図りながら、その推移は見守ってまいりたいと考えています。","id":"exchange-097"},{"speaker":"たけうち委員","kind":"質問","question":"１８３ページ、アドバイザー派遣が１１件あったということなので、その中で工事に結びつきそうなものがあれば教えてください。補正予算が成立すれば、１０５戸の不適正管理空き家の中で、そうした危険なブロック塀があるのかどうか把握されているのかどうか説明を求めました。","respondent":"溝口公園課長、長尾建築課長、森住宅課長、小林環境課長、持田河川下水道課長","answer":"ＪＲ西大井駅内に併設されている公衆便所でございまして、現在はＪＲと事前の設計条件等を含めて打ち合わせとしています。今… 今後考えられる改修の内容であるとか、そういったところを２時間ほどのお話の中でご説明して、アドバイスさせていただいているところです。… 不適正管理の空き家１０５戸に対するブロック塀の状況ですが、１０５戸につきましては、ほぼ草木が繁茂している等というところが多くあります。… 私ども公園課ですけれども、公園・児童遊園…","id":"exchange-098"},{"speaker":"たけうち委員","kind":"質問・要望","question":"トイレの部分と関連して協議の中でそのようなものもご要望してもらえないかと思いますので、一応、ご意見をほしいと求めました。今後、ブロック塀だけではなくて空き家の管理も含めてなのでしょうけれども、所有者を調べてご案内をしていただけるかどうか確認をさせてください。","respondent":"森住宅課長、溝口公園課長","answer":"今まで原則としましては、区営、都営、区民といったような公的住宅を提供しておりまして、東日本大震災のときにも３２世帯に入居いただいております。耐震性とか、民間住宅も含めて取り組んでいけるように… コインロッカーは駅利用者の方が使う施設だと考えています。公衆便所の改修にあわせて、ＪＲと協議を進めていく中で、そのような要望があるということはしっかり伝えていきたいというふうに考えております。","id":"exchange-099"},{"speaker":"たけうち委員","kind":"質問・要望","question":"後でいただきたいと思うのですが、不動産関係者の方とか、いざというときにご協力をいただける体制をつくっていかなければいけないと思います。一緒なのかわかりませんけれども、とっていってもらいたいと思いますが、ご答弁をお願いします。","respondent":"森住宅課長、古巻防災課長","answer":"今も空き家の適正管理審議会を今年３回開催しておりますけれども、その中でも不動産関係の団体の方々に入っていただいております。賃貸空き室も含めて、品川区内２万６,０００戸ありますけれども… 一時的にはさまざまな窓口が設置されるかと思いますので、住宅課と連携しまして、そういった形での日ごろからの情報共有を進めてまいりたいと考えております。","id":"exchange-100"},{"speaker":"たけうち委員","kind":"質問","question":"それぞれよろしくお願いします。今年度取り組んでいます災害時消えない街路灯整備についての今の進捗状況と今後の取組みの広がりみたいなものがあれば説明を求めました。","respondent":"多並道路課長","answer":"今年度、各学校避難所の出入口に１カ所ということで、工事を今ちょうど進めているところです。状況を見ながら、防災課と協議しながら、今後の整備のあり方をちょうど今検討しています。","id":"exchange-101"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから１８４ページの空き家等対策計画策定経費、そして１７９ページの公園整備事業費についてお伺いしたいと思います。この計画策定は、トータルでどれぐらいかかったのかということを１つ教えていただきいたのと、１１ページに１,０９３戸となっているのですけれども。","respondent":"森住宅課長","answer":"説明会をというお話でございましたけれども、今月２０日に情報交換会をやる中で、それぞれ内容について説明していきたいと考えております。そういった意味で、皆様に周知を図りながらやっていきたいと考えておりますので、説明会については今のところ考えてございません。","id":"exchange-102"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"説明会をやるというふうに、区の方針としてもぜひやっていただきたいということで、強くこれは要望をしておきたいと思います。荏原地域に１戸、これからどう対応されて、今後の見通しについてどう考えていったらいいのかについてお聞かせほしいと求めました。","respondent":"森住宅課長","answer":"今後の見通しにつきましても、今後は法令に基づいて命令とか代執行ということも含めて考えていきたいと考えています。代執行の中身につきましては、基本的に安全措置がとれる最大限の範囲をやっていただきたいというふうに所有者の方にはお願いをしています。","id":"exchange-103"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１日も早く地域の方が安心できるような対策として実施していただきたいというふうにお願いをしたいと思います。そして、本当に公園をつくってほしいというのが切実な願いなのですけれども、具体的にどうしたら公園ができるのかについても説明を求めました。","respondent":"溝口公園課長","answer":"公園・児童遊園がない町会・自治会ですが、区内２０１の町会・自治会がある中の３０町会の区域の中に公園がないという状況があります。そのようなところで、少しでも早い時期に全ての町会に公園ができるように取り組んでいきたいと考えているところです。","id":"exchange-104"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"具体的にどういうふうにしたらいいかということもお聞かせいただきたかったのですが、もう時間がありませんので、本当に地域のコミュニティとして公園は大事なものだと思いますので、ぜひ公園のない町会に整備をお願いいたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-105"},{"speaker":"大沢委員","kind":"質問・要望","question":"１７７ページの都市計画費について伺いたいと思います。それについてどのような対策を練り、どのようなビジョンを持っていらっしゃるのか説明を求めました。","respondent":"稲田都市開発課長","answer":"ご指摘の東急の武蔵小山駅ですが、現状もすごく電車が混んでおりまして、ホームから乗ることができないというような声も聞くことがあります。今は６両編成だということなのですけれども、他社の乗り入れの関係等もあるので、その辺を今後協議していきたいというふうに聞いていま…","id":"exchange-106"},{"speaker":"大沢委員","kind":"質問","question":"そこの部分で工夫をお願いしたいと思いますし、マンション建設が２つは具現化をして進んでおりますけれども、そこは工夫をお願いしたいと思います。町会、地域の調和をどのようにとっていかれるのか、方針があったら説明を求めました。","respondent":"稲田都市開発課長","answer":"確かにおっしゃるように、対応を今後、実際に地域の方々が交流できるような形を考えていかなければならないというふうには思っております。今までの住民の方、それから商店街の方、今後その辺を詰めていきたいというふうに考えております。","id":"exchange-107"},{"speaker":"大沢委員","kind":"質問・要望","question":"やはりコミュニティの崩壊になる、本当にこれは繁栄と衰退は表裏一体ですから、ここのところはひとつお願いをしたいと思っています。商業地と住宅地が一体となっているわけですから、もう１回、いいなで終わらないようなお答えでお願いしたいと思います。","respondent":"稲田都市開発課長","answer":"委員ご指摘のように、武蔵小山のコミュニティ、今後、区としても西の玄関口である武蔵小山が衰退するなどということは考えておりません。そういうところを利用と言っては失礼ですけれども、皆さんと考えながら、新しいコミュニティをつくっていきたいと考えております。","id":"exchange-108"},{"speaker":"大沢委員","kind":"質問・要望","question":"その中で、品川区内、今、昼間人口が３８万人ないし３９万人ということです。お考えを聞かせてほしいと求めました。","respondent":"鈴木都市計画課長","answer":"３９万人ですが、大きな見直しは昭和４８年に都市計画法が見直されまして、さらに用途地域が細分化されてきた中で見直しが行われてきてあります。区として人口何万人を許容できるという数字はございませんが、そうした動向は常に意識としてしっかり持って取り組んでいきたいです。","id":"exchange-109"},{"speaker":"大沢委員","kind":"質問・要望","question":"こういうような流れがトレンドができていたわけで、人口はトレンドですから、つかみどころはない。読み解きながら進めてほしいと求めましたし、現状あるスペースが少子化になると空いてしまいますね、どうか尋ねました。","respondent":"鈴木都市計画課長","answer":"空き家も戸建てからマンションの空き室、さまざまだと思います。やはり少子化が進んで世帯が減っていくですれば、やはりそのような部屋も増えていくのかというところは意識しています。","id":"exchange-110"},{"speaker":"大沢委員","kind":"質問","question":"だから空き家対策計画の素案をつくっていただいていて、これは問題意識が非常に高くなってきたからこういうような委員会での質問もでてきたのです。立ってご答弁をお願いします。","respondent":"森住宅課長","answer":"３つの方向性を持っておりまして、適正管理の促進、あと有効活用の推進というふうに３つの方向性を持ってやっております。まずは発生予防ということでさまざまな相談会を開いていきたいと考えておりますし、またそこに住宅が建てられるというふうになればと考えています。","id":"exchange-111"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"すぐにできることとして、今現在、行われているものを下流でもやっていただきたいという地域の方のご要望がありました。ということで、上流にこれが設置された経緯と、下流のほうにそのような鉄板を設置していただきたいというご要望に関して、お願いいたします。","respondent":"持田河川下水道課長","answer":"当然、町会等へ周知する中では、さらに詳しくご説明をというような声も出るのではないかということは我々所管も認識してございまして。こういったものが必要であればというようなところで、所管としましても、そういった地域のお声を聞きながら検討してまいりたいと思ってありま…","id":"exchange-112"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"３人ぐらい横に並んで歩いていくのですが、あるいは通行できると思うのですが、このあたりについてお尋ねします。それからもう１つは、品川道踏切ですが、エレベーター設置等のバリアフリー化に関してのＪＲとの協議の現状や今後についてお伺いします。","respondent":"多並道路課長","answer":"今後の改修の際に様子を見てやっていくという回答だったので、今後、いろいろなタイミングを見ながら都には要望していきたいと思っているところです。今後も引き続き区民の皆さんのご要望をお伺いしながら、関係機関と連携を図ってやっていきたいと思っているところです。","id":"exchange-113"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"いろいろ大変かと思いますが、強く要望をお伝えいただくことをお願いいたします。ほかの公園は裏に板があって落ちないようになっているのですが、そういった遊具についての扱いはどのようになっているのか尋ねました。","respondent":"溝口公園課長","answer":"山中公園の滑り台です。設置されてからそのままずっと皆さんに親しまれてきた遊具ですが、今、調整を進めているところです。","id":"exchange-114"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"改修の方向だということで理解いたしました。小さい子が落ちたり、挟まったりするので危険ですので、ほかの公園も含めて検討していってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-115"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"成果報告書１７８ページ、可動式ホーム柵に関連して、区内の鉄道駅のバリアフリー等々について伺いたいと思います。そしてホームドアがつくまでの間、そのようなことを鉄道会社に求めてほしいと求めましたけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"実施するということは伺っておりますが、できるだけ早い段階での設置を、補助金として区のほうで支援するという流れもありますので。安全対策の早期実施と、これは駅員の声かけとともに、駅を利用する方々の声かけです。","id":"exchange-116"},{"speaker":"石田（ち）委員","kind":"質問","question":"それがなぜなのか、京急からさらに計画が出てくるということは聞いているのでしょうか。そして、こういう事態について、区としてはどう考えているのか伺いたいと思います。","respondent":"鈴木都市計画課長","answer":"２０２０年までには計画的には、京急川崎をはじめ、技術的な課題が大分解消されてきているのだというところは認識しています。区内の設置につきましては、先ほどの申し入れの文書とともに、区内の５駅についても積極的に申し入れをしていきたいです。","id":"exchange-117"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ進めていくべきだと思いますし、区からも強く要望していただきたいと思うのですけれども、南品川の新馬場駅南口も同様です。こうしたことを進めていただきたいと思うのですけれども、京急との交渉が必要だと思うのですけれども、この辺は今どのように進めているか尋ねました。","respondent":"鈴木都市計画課長","answer":"地域の方、バリアフリーの観点から一番いい最良の方法なのかというところをしっかり調整といいますか、お話を聞きながら進めていきたいです。〔「委員長、関連」と呼ぶ者あり〕","id":"exchange-118"},{"speaker":"吉田委員","kind":"質問・要望","question":"生活者ネットワークとしては、かねてより区としての計画を持ってほしい、その辺についてのご見解を改めて伺います。改札まで案内してくださるというサービスをＪＲでは確認しているのですけれども、どのように確認して、もしそれがあれば説明を求めました。","respondent":"鈴木都市計画課長","answer":"私の認識では、ホームで乗るところまで誘導するということは、ほかの鉄道事業者も行っているという認識です。ソフト対策あるいは音声の誘導等も含めてしっかりやっていただきたいというところは、これからお出しする文書の中でもしっかり示していきたいです。","id":"exchange-119"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、その辺のことも品川区としてもこういうふうにやってほしいということをぜひ徹底してほしいと求めました。もう一言、ご見解があれば。","respondent":"鈴木都市計画課長","answer":"特に今、ソフト対策のところにつきましては、区のほうでやさしいまちづくり推進協議会等で、いろいろな視覚障害者の方とも意見をやりとりする場もありますので、そうした中で区としても鉄道事業者へのさらなるお願い、依頼、申し入れも含めてしっかりやっていきたいです。","id":"exchange-120"},{"speaker":"伊藤委員","kind":"確認","question":"勝島運河その２、その３、これらはそういうことを十二分に見越した対応であるのかということの確認をお願いするのが１点。大規模な浄化、それから地域整備等を検討すべきだと思うのですが、いかがか尋ねました。","respondent":"持田河川下水道課長","answer":"立会川の能力を補完する第二立会川幹線という下水道管を設置したり、そのような都市化の進展に伴う雨水流出量の増大への対応は進めているところです。今、この事業が終わるということが浸水対策としては１つの大きな節目になってくるかと考えていまして…","id":"exchange-121"},{"speaker":"伊藤委員","kind":"意見","question":"それをどういうふうに展開していって、立会川、勝島運河地域をきれいにしていくかということを、将来構想も含めてお聞かせください。お願いいたしますとの意見を述べました。","respondent":"鈴木都市計画課長、持田河川下水道課長","answer":"平成２９年度ですが、当地区のまちづくり、将来的な方向性を検討してまいりました。これに基づいて、今後、地域のまちづくりを地域の方と一緒に進めていくというところでは、しっかり水辺の活用も含めて行っていきたいです。 今、堤防のところを少し改修工事などをしまして、より川に近づきやすくなるような構想もあると聞いてあります。そのようなことも見据えながら、事業を続けてまいりたいと思ってあります。","id":"exchange-122"},{"speaker":"伊藤委員","kind":"提案","question":"国土交通省が指導する形で。これはほかの委員からの要望でもあったのですけれども、球場を拡大してはどうかという提案もありますので、いかがか尋ねました。","respondent":"持田河川下水道課長","answer":"ちょっとまだそのような部分で検討、整理しなければいけない部分があると理解しています。２４時間、何かあったときの責任の所在なども含めて、そのような大きな視点で水門の管理についてはまた検討していきたいと思ってあります。","id":"exchange-123"},{"speaker":"伊藤委員","kind":"質問・要望","question":"もちろん私たち、何回も担当課にも話をさせていただきましたし、法令、条例に基づいた対応を求めてきましたけれども、現状は回復しておりません。お願いいたします。","respondent":"多並道路課長","answer":"今の第一京浜の件ですが、区民の方からすれば、国道、区道の区別がなかなか難しいところもありますので、道路課のほうにお問い合わせがあります。なかなか国のほうの対応というところもあるので、区の中でできることということで、まずは生活福祉課と連携をしております。","id":"exchange-124"},{"speaker":"伊藤委員","kind":"質問","question":"国と連携をとっていくことも考えたらどうですかということと、改めて区長会等で議論すべきと思うのですが、いかがでしょうか。あわせてお願いいたします。","respondent":"多並道路課長","answer":"都道であれば都であったり、あとは、先ほど申し上げた警察との連携です。今ご提案がありました２３区との連携という意味では、そのような３者で、何か進めてまいりたいと思っているところです。","id":"exchange-125"},{"speaker":"若林委員","kind":"質問・要望","question":"１８３ページの親元近居支援事業、１７６ページの河川費について伺います。そして、転入の誘引、定住促進についての効果、どのような効果が上がっているか状況をお知らせほしいと求めました。","respondent":"森住宅課長","answer":"では、近居、同居を考えてみようといった方が３２％ございました。今まで７年間で２５８件に対し助成をしておりまして、一定程度、成果として一定上がっているというふうに考えております。","id":"exchange-126"},{"speaker":"若林委員","kind":"質問・要望","question":"その中でも３２％の方が考えてみようということで、また、１つの動機づけになっていたりということの一定の前進を確認させていただきました。支え合いについては、これは検証をされていないというふうに理解をいたしましたけれども、ここを１回お答えをいただきたい。","respondent":"森住宅課長","answer":"アンケートの中でも、三世代で過ごす時間が増えた、共通の話題が増えたというようなお話もいただいております。これに基づいてファミリー世帯が２５８件あったということではありますが、転居にあたって助けができているのではないかというふうに考えております。","id":"exchange-127"},{"speaker":"若林委員","kind":"質問","question":"今後は、私も今、大きな１つの目的、両方課題があって、特に人口動向を見ると、明らかに子育て世帯、ファミリー世帯が転出していく。次々年度と改善をしていく、そういう事業だと思いますけれども、いかがか尋ねました。","respondent":"森住宅課長","answer":"今、委員おっしゃいましたように、ますますの定住化ということは今後進めていく必要があるかと考えています。お互いに助け合いたいと考えている方に、少しでも助けとなるような制度設計につきまして、少しでも考えていきたいと思ってあります。","id":"exchange-128"},{"speaker":"若林委員","kind":"質問・要望","question":"大きな課題を抱える中でという意味で要望します。毎年何月ごろやっているのか、浚渫は何日間程度かかるのか説明を求めました。","respondent":"持田河川下水道課長","answer":"平成２９年度につきましては、五反田駅の近く、大崎橋の付近という形でやってございまして、平成２９年度に実施した時期は、１０月の下旬です。実施した期間としては、大体１週間ぐらいという形です。","id":"exchange-129"},{"speaker":"若林委員","kind":"意見","question":"この浚渫の時期、年に１回、２回ということも……。〔時間切れにより答弁なし〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-130"},{"speaker":"須貝委員","kind":"質問","question":"品川区には、国道、都道、区道がありますが、品川区は災害時の交通路の確保はできているのでしょうか。区内に非常用電源付信号機などは何台ぐらい設置されているのか、それもあわせて説明を求めました。","respondent":"古巻防災課長","answer":"警察、消防等と連携をとって、しっかり通行ができるような体制をとるような形になってあります。","id":"exchange-131"},{"speaker":"須貝委員","kind":"質問","question":"はい、連携がとれていますから渋滞はありません、特定緊急輸送道路も確保されています、そのようなことはとあり得ないのではないですか。それに対して対策は考えていないのか尋ねました。","respondent":"古郡交通安全担当課長","answer":"私からは、信号機の設置に関してご説明をいたします。通る車については、警察署のほうで通行車両の許可を与えたりとか、そのような形で実施をしています。","id":"exchange-132"},{"speaker":"須貝委員","kind":"質問","question":"それに一人ひとり配置するだけの人員などいるわけないではないですか。これに対して全く区としても考えていらっしゃらなかったか尋ねました。","respondent":"古郡交通安全担当課長","answer":"信号機に関しては、私は全ての交差点とは言っていませんので、主要な交差点で交通路を確保するという形です。主要なところに大体発動発電機がついたものを設置しておりますので、だんだん設置も進んでおりますので、そのような形になっております。","id":"exchange-133"},{"speaker":"須貝委員","kind":"質問・要望","question":"これも交通路や避難路の確保はできないのではないですか。この辺について、どのように対応を考えていますか。","respondent":"今井土木管理課長","answer":"東京電力は、最大震度７を記録した阪神・淡路大震災に耐えられるよう、また、風についても風速４０ｍは耐えられるような電柱を立てているところです。水素などで劣化するものもあるのですが…","id":"exchange-134"},{"speaker":"須貝委員","kind":"質問・要望","question":"避難路、交通路に関しては、これからも、これだけの数があるのですから、私は的確に早くやって対応してほしいと求めました。その辺についてどのようにお考えか尋ねました。","respondent":"稲田都市開発課長","answer":"そういうところで対応しているというところでございまして、二重ガラスとか、そういうふうな形もとっているというふうに聞いております。そういう面では、簡単にガラスが落下するというふうには考えておりません。","id":"exchange-135"},{"speaker":"須貝委員","kind":"質問・要望","question":"１０分の１か、５％かわからないですが、割れて落ちます。ぜひその辺の対応を早急に考えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-136"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これでもう１,０００戸来ても大丈夫ですというお考えなのか、事前に、更新しながらでもそういうことは多分もうすぐできる。それは防災協定を結ぶのかどうかは別として、そこら辺はもう一歩突っ込んでやれると思うので、そこら辺の見解を教えていただきたい。","respondent":"森住宅課長","answer":"あるいは区営、区民住宅、都営住宅といった公的住宅を使って対応していくという形で考えておるところです。そのようなことが考えられるのであれば、課題の認識を１つにしたり、研究してまいりたいと思います。","id":"exchange-137"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"５００の場合とか、それは協定を結ぶのかどうかは別としても、それはひとつぜひお願いをしてほしいと求めました。１００本ぐらいやって、例えば５０本は移設できましたとか、そこら辺のところを説明を求めました。","respondent":"長尾建築課長","answer":"土木管理課と連携を図りながら、その電柱の所有者である東京電力、ＮＴＴに依頼をしまして移設を図っているところです。同様に東京電力やＮＴＴにも細街路の拡幅は防災上の観点からも重要なものですので、協力をいただきながら移設を図っているところです。","id":"exchange-138"},{"speaker":"石田（秀）委員","kind":"確認","question":"４２条２項道路も指定しているわけだから、ということは、それは権利の問題がどういう形というのがさまざま議論されてきているわけではないですか。確認も４６しかないし、２万５,０００なのか３万なのかわからないけれども、どれぐらい時間を割いているかわからなくてなってしまいます。","respondent":"長尾建築課長","answer":"所有者の方に丁寧に説明しながら、難しいところもありますが、引き続き頑張っていきたいと考えております。先ほどの細街路について１件１件丁寧に対応していくところもあわせて、まずは今の体制で頑張っていきたいと考えております。","id":"exchange-139"},{"speaker":"石田（秀）委員","kind":"確認","question":"どうしてそういうことを聞いたかというと、確認をおろすときは事業者の方に、こういうことをしてくれと頼めるではないですか。さっき言った２万幾つも空いているというから、こういうことが必要だと思うので、そこら辺の見解を説明を求めました。","respondent":"森住宅課長","answer":"それについてはあり方検討という形で、今年度、委託をかけておりまして、短期、中期、長期の実際の使用料を含めた検討を進めているところです。今年度の検討を待っている形ですけれども、そのような地価の変動等々も加味しまして、柔軟に検討していきたいと考えています。","id":"exchange-140"},{"speaker":"石田（し）委員","kind":"質問","question":"１７６から１７７ページ、１８０ページ、１７１ページの駅周辺等放置自転車対策についてお伺いします。立会川等で、こういった事業を取り組んだらいいのではないかと思うのですが、まずご見解を説明を求めました。","respondent":"持田河川下水道課長","answer":"そうでもないのかという感じもありますが、河川には結構そのような環境団体の方がいろいろな連絡会などをつくっているケースもあります。区としましても、そのような川のほうに何とか注意を向けていただけるような取組みも今後いろいろと検討していきたいというふうには考えてあ…","id":"exchange-141"},{"speaker":"石田（し）委員","kind":"質問","question":"実際、私もちらっと運河のところでホテルらしきものがぽつんと浮かんでいるのをこの間見たのですが、その辺の取組みについてお考えをお聞きします。","respondent":"持田河川下水道課長、稲田都市開発課長","answer":"なかなか舟運のほうは事業者との収益的な部分を含めたルートの検討も必要になってくるものですが。水辺に設置して、そのような水辺の賑わいにつながる取組みということで、区としても必要な支援はしていきたいと考えています。 五反田駅におきましても、まちづくりに関わる地元協議会の活動も盛んになっております。そういうものを含まして、そういうものに沿いながら、よいよりまちづくりを進めていきたというふうに考えています。","id":"exchange-142"},{"speaker":"石田（し）委員","kind":"提案","question":"なぜ五反田エリアに多いかと言ったら、また活動されている方も含めて、全体的に未来を見据えたビジョンを持っていただきたいというふうに思います。我々としても、できる限り提案できるところはしっかりしていきたいと思いますので…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-143"},{"speaker":"南委員","kind":"質問","question":"駅周辺の放置自転車、これは減っているのか増えているのか、現状をどう見ているのかをまず伺いたいと思います。そういうふうに見えるのですけれども、そういう状況、区の認識と評価を伺いたいと思います。","respondent":"古郡交通安全担当課長","answer":"駅の放置自転車については、年々減少傾向にあるということで認識をしております。定期利用と一時利用の関係ですけれども、利用率からすると、一時利用のほうが多くなってきているような認識をしております。","id":"exchange-144"},{"speaker":"南委員","kind":"質問","question":"つまり、一時利用が増えているということ、これは放置自転車対策としての効果はあるというふうに見ていいのでしょうか。その点を１つ伺います。","respondent":"古郡交通安全担当課長","answer":"そうですね、区では、駐輪場の整備と撤去、指導・警告ということを三本柱でやっています。ですので、効果が上がっているという認識をしております。","id":"exchange-145"},{"speaker":"南委員","kind":"質問・要望","question":"品川区立の駐輪場の整備と、こういう認識でいいのかと思っているのですけれども、そこの確認です。民間にならって１００円ということでもいいと思うのですけれども、そういう仕組みに変えるべきだ、そういう点についてどうか尋ねました。","respondent":"古郡交通安全担当課長","answer":"民間の駐輪場整備等の効果で放置自転車が減ったのかという認識ですけれども、区の方も駐輪場の整備、それで減っているという認識をしております。無料時間の設定は、今のところ、現状のままやらせていただきたいというように考えております。","id":"exchange-146"},{"speaker":"南委員","kind":"質問・要望","question":"１日、学生だとか通勤者だとかの長時間というのは定期利用に誘導していけばいいわけですから、もっと品川区として考えていただきたい。中には傷んでいない木も遊具との関係で伐採をする、そういう状況もあったのだろうと思うのですけれども、そのあたりのことを説明を求めました。","respondent":"溝口公園課長","answer":"３０年が経過して改修工事を計画的に進めているところです。そのほか新植としては４６本、移植については７３本やっているような状況です。","id":"exchange-147"},{"speaker":"南委員","kind":"質問・要望","question":"大変傷んでいる木が多いというふうに聞くのですけれども、日常的な公園の樹木の管理、あるいは手当て、そういうことはどうなっているのでしょうか。そういう手当ても含めて、どういうふうに管理しているのか、そこを伺いたいと思います。","respondent":"溝口公園課長","answer":"今回、中央ゾーンにつきましては、子どもの遊び場の充実を１つの大きなテーマに持って整備をしています。今後また２０年、３０年、適正に快適に使っていただけるような形の整備を行っているものです。","id":"exchange-148"},{"speaker":"南委員","kind":"質問","question":"もっと具体的にきちんとした管理体制をとっていく必要があるだろうというふうに思っておりますので、その点について指摘をして終わりたいと思います。過去２回、具体的な項目、テーマを説明を求めました。","respondent":"鈴木都市計画課長","answer":"１５年先のまちづくりを検討していくですが、検討開始から１０年、１５年かかっているという声も伺っております。そうした方々がしっかり同じ方向を向いて、これからのまちづくりを考えていただけるような機運をつくりたいというところでスタートしたものです。","id":"exchange-149"},{"speaker":"南委員","kind":"質問・要望","question":"しかし、本当に瞬間湯沸器はすぐお湯が出るのですけれども、八潮の熱供給は大体３０秒ぐらいしないと水からお湯になってこないのです。抜本的に見直すような、そういうこともテーマに入れていただきたいと考えていますが、その点についてどうか尋ねました。","respondent":"鈴木都市計画課長","answer":"八潮地区、人口構成、高齢化が進展しているというところでは、区の受けとめ方としても同じです。このときの取組みが少しでも役立つような大きい視点でのまちづくりのあり方を少しでも検討していけたらというところで、しっかり進めていきたいです。","id":"exchange-150"},{"speaker":"南委員","kind":"質問","question":"最後に、具体的に熱供給のことも聞いたのですが、そこの見解をお願いします。","respondent":"鈴木都市計画課長","answer":"さまざまな課題は大きい視点の中で今後も検討していきたいです。","id":"exchange-151"},{"speaker":"こんの委員","kind":"質問・要望","question":"１７５ページ、１７８ページ、この３点をお伺いしたいと思います。これまで我が会派のたけうち委員が求めてきたことであり、撤去実施に至るまで時間がかかりましたが、求めてきたことの実現をうれしく思っております。","respondent":"多並道路課長","answer":"２００人以下であったり、近傍に横断歩道が設置されている、交通管理者や地元の方々の理解が得られている。これらの項目を全て満たす条件ということで示されているところで、今後としてもこのような形で進めていきたいと思っているところです。","id":"exchange-152"},{"speaker":"こんの委員","kind":"質問・要望","question":"２９年の予算特別委員会でも要望してまいりました南大井の桜新道の歩道橋、エレベーターをつけていただきたいというふうに求めてきたわけですが、この歩道橋についてはどのようにお考えか尋ねました。","respondent":"多並道路課長","answer":"桜新道の歩道橋については、実は８００人程度利用されているということが確認されているところです。地元からもご要望があって、学校や警察といろいろ協議した結果、撤去というところで方針として進めているところです。","id":"exchange-153"},{"speaker":"こんの委員","kind":"質問・要望","question":"もう１つが、改札口のコンコース、２階に上がって改札口に行く、そのエレベーターの入口の向きを改善してほしいという、この２点であります。このような要望が上がっておりますので、耐用年数の対応と方向性もある中で、どのようにこのことは考えられますか尋ねました。","respondent":"鈴木都市計画課長","answer":"一般的にエレベーターの耐用年数については、メーカーごとで多少違うところはありますが、２０年とか２５年とかというところはあろうかと思います。まずそういった計画がどれぐらい先に予定されているのかを含めて、シャフト…","id":"exchange-154"},{"speaker":"こんの委員","kind":"質問・要望","question":"保育園から公園に、公園から保育園にというような送迎バスに私立幼稚園のバスを活用する仕組みなどをつくってみてはいかがでしょうかと思います。２台、３台持っているところもありますので、こうしたところで地域の協力も得られるバスのこうした送迎はいかがか尋ねました。","respondent":"溝口公園課長","answer":"公園は誰もが利用できるところです。さまざまな方が利用しておりますので、そのようなところで所管と連携しながら、どういう形がいいのか検討していきたいと考えているところです。","id":"exchange-155"},{"speaker":"渡部委員","kind":"質問・要望","question":"いろいろ質問させていただいた環境未来館ができるというところで、経緯とかは確認させていただきました。車の流れとかも変わってくるようなところになるわけですから、その辺、戸越公園の改修についてどう考えているかということをお聞かせいただきたい。","respondent":"溝口公園課長、高梨木密整備推進課長","answer":"そのような中でいきますと、ほかにある遊戯ゾーンを充実していきたい。そのような中の１つとして、今後具体的にいろいろ検討を進めていく中で、しっかり検討していきたいというふうに考えているところです。 成果報告書の１８１ページの用地取得費について答弁します。用地の管理権限は東京都にありますが、防災に資する使い方等について、また東京都と積極的に協議してまいりたいと考えています。","id":"exchange-156"},{"speaker":"渡部委員","kind":"質問・要望","question":"機を見て要望します。鉄道事業者も入れて、いわゆる品川区の公共交通のあり方を全て包括的にもう１回話し合える場にしてほしいと思うのですけれども、いかがか尋ねました。","respondent":"鈴木都市計画課長","answer":"地域交通検討会、過去設置しまして、鉄道事業者は入っていないです。コミュニティバスを軸に区内の地域交通、公共交通のあり方については、しっかりご議論いただきながら進めていきたいというふうに考えてあります。","id":"exchange-157"},{"speaker":"渡部委員","kind":"質問・要望","question":"それを幾つもルートを走らせると大変なことになるものですから、品川らしい事業を構築ほしいと求めました。要望して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-158"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/295139?Template=document&Id=1460#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":119072,"voices":371}},{"id":"h30-20181113-4","meetingId":"h30-c-settlement","date":"2018年11月13日","dateIso":"2018-11-13","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時３０分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を160件整理しています。","topics":[{"id":"topic-01","title":"◯鈴木（博）委員長 おはようございます。ただいまより、決算特別委員会を開会いたします。 それでは、平成２９年度品川区一般会計歳入歳出決算","agenda":"◯鈴木（博）委員長 おはようございます。ただいまより、決算特別委員会を開会いたします。 それでは、平成２９年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"芹澤委員","kind":"質問","question":"１８８ページ、１９６ページ、時間がある限りお伺いをします。区が行っている具体的な取り組みについて、この４つの観点でございましたら、具体的な説明をお願いいたします。","respondent":"大関教育総合支援センター長","answer":"やはり児童・生徒の悩みをどのような把握するのか、具体的な取り組みという観点からお答え申し上げます。さまざまな観点から、子どもたちに自殺予防教育を行えるよう努めているところです。","id":"exchange-001"},{"speaker":"芹澤委員","kind":"質問","question":"スクールソーシャルワーカーであったり、匿名の電話であったり、ＳＯＳを受けとめるようなさまざまな取り組みをしているというお話をいただきました。では品川区全体で、このＳＯＳを年に何件ぐらい受けとめているのか、また過去３年ぐらいの推移もあわせて説明を求めました。","respondent":"大関教育総合支援センター長","answer":"例えば各学校に設置しております目安箱、それから専用電話、ＨＥＡＲＴＳのほうにかかってくるものなどで把握し対応しています。その他、専用電話につきましては、平成２９年度５１件、平成２８年度１０８件ございました。","id":"exchange-002"},{"speaker":"芹澤委員","kind":"質問","question":"では続いて、１９６ページの学校給食費についてお伺いをします。この検査費用が半分程度になった理由もあわせて説明を求めました。","respondent":"篠田学務課長","answer":"こちらは、それまでは毎年全校実施をしてございましたストロンチウムの検査を３分の１の学校に縮小いたしました。要は３年に１回の割合で全校が検査できるような体制に変更したということで、減少したものです。","id":"exchange-003"},{"speaker":"芹澤委員","kind":"意見","question":"被災から８年目に近づく中で、お金をかけて品川区が検査をする必要性がどれほどあるのかないのか、少し疑問に感じるところであります。そして、どれほど時間が経てばこの検査をやめることが選択肢に入ってくるのかということも、あわせて説明を求めました。","respondent":"篠田学務課長","answer":"先ほどもお答え申し上げたとおり、これまで検査で放射性物質は検出されたことがないという状況が１つはあるです。この実施については考えていく必要があるとは思っていますけれども、現状、今後十分検討していく必要があるというふうに考えているところです。","id":"exchange-004"},{"speaker":"芹澤委員","kind":"質問","question":"最後に、ボルダリングについてお伺いします。３年リースというようなお話を伺っていましたが、この設備をどうする予定なのか、ほかの学校でも配備する予定があるのかも含めて説明を求めました。","respondent":"有馬庶務課長","answer":"芳水小学校に設置しておりますボルダリング設備ですけれども、リースが切れた後は区にも譲渡ができるということになっております。今後も改築が予定されている後地小学校、後地小学校が終わった後は鮫浜小学校においても活用していこうかなというふうに考えているところです。","id":"exchange-005"},{"speaker":"新妻委員","kind":"質問・要望","question":"１８６ページ、教育指導費、１８８ページ、芹澤委員と同じですが、ボルダリングを活用した体力向上の取組みについてお伺いいたします。塚本副委員長が、第２回定例会での一般質問でも取り上げましたが、その後の品川区の対応について伺いたいと考えています。","respondent":"大関教育総合支援センター長","answer":"重たいかばんに関して、その後の対応に関するお尋ねです。その通知をするとともに、校長連絡会でも再び、１学期にも話題には出ていたのですが、改めて全校に徹底していただけるようお願いしたところです。","id":"exchange-006"},{"speaker":"新妻委員","kind":"質問・要望","question":"貼るだけでなく、今後もしっかりと対策がとられているかどうかという確認も行ってほしいと求めました。余り重さが変わらないという声も聞いておりますので、そこのところをしっかりと今後も対応を進めてほしいと求めましたが、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"その後、例えば朝登校してきたときに、保健室の前で何人か実際にランドセルの重さをはかってみたという学校があるとの報告も受けております。今後も引き続き、しっかりと家庭と学校が同じ方向で…","id":"exchange-007"},{"speaker":"新妻委員","kind":"確認","question":"先ほどの質問で、芳水小学校の後、別の学校でも使われるということが確認をされました。品川区内の小・中学生のボルダリングの競技人口を、どのように把握されているのかということをお伺いしたいと思います。","respondent":"大関教育総合支援センター長","answer":"ニュースポーツとして注目を浴びているということは把握していますので、学習指導要領にのっとったスポーツではございませんが、今後とも情報収集してまいりたいと思います。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"登れたときの達成感を味わってほしいというふうにメッセージを贈られていますが、気軽にできるスポーツであるということです。お隣のスポル品川大井町のボルダリング設備を使い、ぜひ品川区の大会の開催を要望いたしますが、いかがか尋ねました。","respondent":"池田スポーツ推進課長","answer":"昼間も大勢の方が楽しみ、そして土日となりますとお子さんも参加して気軽に楽しんでいる様子、私も拝見させていただいているところです。こちらのほうはぜひ何とか、考えていきたいと思います。","id":"exchange-009"},{"speaker":"中塚委員","kind":"質問・要望","question":"１８５ページの学事制度検討経費より、１８６ページの教育指導費より、学校スタンダードの検証と見直しを求めて質問したいと思います。学事制度についてですが、新たな人口推計が示される中、学校統廃合を検討する必要は全くないと思いますけれども、いかがか尋ねました。","respondent":"篠田学務課長","answer":"学校統廃合についてのお尋ねです。学事制度審議会の中ではさまざま検討されてきたものですけれども、今のところ学校を統廃合する要因はないものであると考えているところです。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問","question":"保護者からも、そろそろ建て替えの時期なのではないかという声も伺っております。先ほどの４校について、改築、建て替えの時期はいつなのか伺いたいと思います。","respondent":"有馬庶務課長","answer":"お問い合わせのあった学校ですけれども、今現在、品川区では長期基本計画に基づいて、毎年１校ずつのペースで学校改築を進めております。本来であれば先の見通しを全部立てて、今の４校のところについてを含めて…","id":"exchange-011"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひ学校やＰＴＡの要望をよく伺いながら、話し合いながら、決めてほしいと求めました。この１５ページにわたるルールづくりについて、子どもたちはどのようにルールの策定に参加したのか伺います。","respondent":"大関教育総合支援センター長","answer":"一緒に話し合うというよりは、まずはこのような形で１年生のスタートをしましょうということで学校の決まり等を示しています。児童会や生徒会の活動において自分たちで考えていく場面というものは、学級会活動をやっていく、そういった内容になっていくものです。","id":"exchange-012"},{"speaker":"中塚委員","kind":"確認","question":"話し合いというよりは、決まりを、ルールを守りましょうということは、この策定に子どもは参加していないということでいいのか確認したいと思います。子どもたちはこれらのルールづくりに参加しているのかいないのか伺います。","respondent":"大関教育総合支援センター長","answer":"まず１年生は学校生活をどのように進めるべきなのか、足をしっかりとつきましょう、それが学校スタンダードの１ページの内容かと思います。徐々に徐々に社会の一員として、立派な品川区民として育ってほしいというように各校とも願って、生徒規則等を考えているところです。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"こうした、事細かにルールを決めることが、なぜ自主的な力を育むことになるのか伺います。ルールに従うだけで疑問や質問を挟む余地をなくし、子どもの豊かな成長をゆがめてしまうと思いますが、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"ただ、毎回遊んではいけないということではなくて、１５分休みや昼休みなどもしっかりあります。それは個別の対応をやっているところです。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問・要望","question":"さまざまな家庭がある中で、この宿題のルールが正しいと決めることは、そこから外れる子どもは窮屈な思いをするのではないでしょうか。学校スタンダードの検証と見直しを求めますが、いかがか尋ねました。","respondent":"大関教育総合支援センター長","answer":"個別の対応というものが大前提かと思いますので、まずは１つの目安、個別に対応しています。あるいは保護者との連携した家庭教育も含めて子どもたちの教育については、家庭と十分に話し合いながら、充実させてまいりたいと思います。","id":"exchange-015"},{"speaker":"中塚委員","kind":"意見","question":"このルールを守りなさいと記されております。子どもの気持ちをないがしろにするような、こうした学校スタンダードは見直しが必要だと強く思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"松永委員","kind":"質問","question":"そして、子どもたちの膝に影響があるのではないかということがよく聞かれるのですけれども、実際のところどうなのでしょうか。あわせて伺います。","respondent":"有馬庶務課長","answer":"学校の校庭を人工芝生化していくことのメリットですけれども、委員ご指摘のとおり砂ぼこりの飛散への対応というものが一番大きいところです。それから子どもたちの膝の関係ですけれども、一応子どもたちの膝に対応するために、小学校では少し長目の芝を入れています。","id":"exchange-017"},{"speaker":"松永委員","kind":"意見","question":"そこは何か水はけがとても悪いように感じたのです。今後、本区の小学校は全校人工芝生にされるのか、また中学校についてもお知らせくださいとの意見を述べました。","respondent":"有馬庶務課長","answer":"そういったことを考えますと、基本的には今後は人工芝を中心に、進めていくということを考えているところです。中学校も同様です。","id":"exchange-018"},{"speaker":"松永委員","kind":"質問","question":"次に学校給食について伺います。現在本区では、料理をつくってくださっている給食センターの方々についてなど、どのように小・中学校の生徒に指導しているのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"子どもたちがどのように給食をおいしく食べられるかというさまざまな工夫、それから完食という２つの観点についてご質問いただきました。食材が残るのを防ぎ、やはり無駄にしない、大切に食品は扱うという指導も一緒にしています。","id":"exchange-019"},{"speaker":"松永委員","kind":"提案","question":"防災の意識を高める効果もあり、防災給食を行っていただきたいということを提案させていただきまして、この件については終わりたいと思います。そして残菜の量は年々どのように推移しているのか、改めて伺いますとの意見を述べました。","respondent":"篠田学務課長","answer":"週に２回ほど生ごみの回収を行いまして、それが最終的には動物の飼料に変わっていくといった形で、利用がされてあります。若干増加傾向にはあるのですが、おおよそ年３５０トン前後の残菜が４６校の学校で出ているというような状況です。","id":"exchange-020"},{"speaker":"松永委員","kind":"質問・要望","question":"ぜひ取り組んで、残菜を減らしてほしいと求めました。今後どのように変わっていくのか、そのスケジュールを、わかる範囲でいいので教えてほしいと求めました。","respondent":"有馬庶務課長","answer":"来年度は実施設計ということで、ここで基本的ないろいろ工事の工程が決まってくると思います。その後２年半ぐらいかけて校舎を建てまして、最終的には外構工事を進めていくというような形になってくると思います。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"私は１８６ページ、教育指導費についてお聞きしたいと思います。区内の公立中学生の低学力層の実態を、どのように把握しているか、そしてどのような状況になっているのか説明を求めました。","respondent":"熊谷指導課長","answer":"ただ、一人ひとりに着目しますと、習熟が進んでいる層もあれば、反対に基礎的な知識や技能が十分身についていないといった層も確かにあります。こちらは今申し上げた国の調査、都の調査、そして経年で行っている区の学力定着度調査で確認をしています。","id":"exchange-022"},{"speaker":"須貝委員","kind":"確認","question":"今確認をしていただきましたが、これぐらいの点数、正答率はこれぐらいということは把握していますよね。教育委員会として確認しているとは思うのですが、そしてそのまま学年がどんどん上がっているという、そのような実態をどのように捉えられていますか。","respondent":"熊谷指導課長","answer":"ただし、１人の子どもを２年生から９年生まで毎年追っていく形になっております。６年生から７年生に上がったときでも、保護者にもわかるように、そういった状況で子どもたちの学力を捉えているところです。","id":"exchange-023"},{"speaker":"須貝委員","kind":"質問・要望","question":"それをわかる範囲で教えていただきたいということと、公立中学校の場合には、数学Ｂの正答率が全国平均で４６.９％と出ています。その前に先ほどお聞きした、今の疑問点もそうですが、どれぐらいの割合の子がどれだけの点数領域にいるのか説明を求めました。","respondent":"熊谷指導課長","answer":"ただ、正規分布の５段階だと７％ぐらいが、いわゆるＡ、Ｂ、Ｃ、Ｄ層のＤにいるかなです。全ての教科においても、先ほど申し上げました秋田県、石川県、福井県と同等、もしくはそれ以上ということになっております。","id":"exchange-024"},{"speaker":"須貝委員","kind":"質問","question":"なので、いや品川区はいいのだという根拠にはならないのではないですか。このようにはっきりと正答率に違いが出ている中で、いや、うちは全国的にみていいからいいのだという理屈は通るのか尋ねました。","respondent":"熊谷指導課長","answer":"国立の正答率は約７０％でしょうか。品川区の場合は数学に関しましては７０％ですので、国立と同等というふうになろうかと思います。","id":"exchange-025"},{"speaker":"須貝委員","kind":"質問","question":"あくまでこれは昨年のものですからあれですが、数学Ｂが５１％、数学Ａが６７％。０点から２０点が十七、八名もいるという実態に対して、どのようにお考えなのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"やはり無回答ということで０点になってしまうお子さんも、現実にはいらっしゃいます。さまざまな中で習熟度別の学習というものを展開しながら、そのお子さんの定着している内容に応じた指導の工夫はしています。","id":"exchange-026"},{"speaker":"須貝委員","kind":"質問","question":"そうではないのですか。もう１回ご見解を説明を求めました。","respondent":"大関教育総合支援センター長","answer":"さまざまなお子さんの実態に応じて個別な配慮というお話をさせていただいただけですので、決して学力をおろそかにするということではございません。社会参加するための学校の役割というものがありますので…","id":"exchange-027"},{"speaker":"須貝委員","kind":"質問","question":"このようなことではいけないではないですか。それに対してこのまま、悪い言い方をすれば放置しているのと一緒ではないか尋ねました。","respondent":"熊谷指導課長","answer":"そういう中で補習が有効と考えています。付随して地域未来塾がコミュニティ・スクールにはありますので、全校で補習を行っているところです。","id":"exchange-028"},{"speaker":"須貝委員","kind":"質問","question":"だけれども、最低限、このような低学力層というのですか、定着しないという子に対して、やはりもっと力を入れるべきではないですか。自分の子どもだと思って、いかがか尋ねました。","respondent":"熊谷指導課長","answer":"原則として国語、算数、数学、理科、社会、英語を補習をしておりますけれども、中には英検受験の補習ということをやっているところもあります。校長や先生方も、やはり自分でも教えたいということで補習を行っているところですので…","id":"exchange-029"},{"speaker":"須貝委員","kind":"質問・要望","question":"申しわけないけれども、補習をきちんとして、子どもたちを支えているなら、このような状態になるでしょうか。お母さんに「どうなのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"田中委員","kind":"質問・要望","question":"通学安全確認業務等委託、そして時間があったら１９０ページ、４目社会教育費の品川区子ども読書活動推進計画について伺います。子どもたちの食の安全を守っていく姿勢を継続していただきたいと改めて要望いたしますが、いかがか尋ねました。","respondent":"篠田学務課長","answer":"こちらに関しましては、これまで平成２３年度から継続して実施してきたものです。対象、検査内容等を考えながら進めてきたところですけれども、今後については十分検討していく必要があるかなというふうに考えているところです。","id":"exchange-031"},{"speaker":"田中委員","kind":"確認","question":"安全を継続し、確認していくことがとても重要です。ＨＥＡＲＴＳの相談件数、相談の多い項目についてお知らせください。","respondent":"大関教育総合支援センター長","answer":"その中で広い意味で全体としての対応件数は、平成２９年度が４６校、２０４人に対応いたしました。中には保護者自身に支援が必要なケースもありますので、そちらに関しましては継続的にさまざまな、家庭訪問も含めました対応をしています。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問","question":"現在ヤングケアラーの状況にある子どもの数を把握されていたら、お知らせください。ヤングケアラーであることがわかったときには、どのような支援につなげているのか伺います。","respondent":"大関教育総合支援センター長","answer":"いわゆるヤングケアラーという調査項目はございませんが、「家庭環境」といたしましては、平成２９年度の１年間で、７０ケースを対応しております。その中の全てが要支援の保護者の方ばかりではございませんが…","id":"exchange-033"},{"speaker":"田中委員","kind":"質問・要望","question":"品川区でもＨＥＡＲＴＳの相談状況を踏まえ、教育委員会としてヤングケアラーについて問題意識を持っているのか伺います。ヤングケアラーについては教育委員会も担当課と協力して取り組んでほしいと思いますが、見解を伺います。","respondent":"大関教育総合支援センター長","answer":"さまざまな関係機関と情報を共有しながら対応に努めているところですが、あるいは欠席が続くといったところから発見というケースは確かにあります。これは不登校であったり、１つの機能が十分にあるというふうに教育委員会も考えておりますので…","id":"exchange-034"},{"speaker":"田中委員","kind":"質問・要望","question":"次にまもるっちの使い方の指導について伺います。教育委員会の事務事業概要では、子どもの健やかな成長を見守る教育委員会としては、この事業をどのように評価されているのか伺います。","respondent":"大関教育総合支援センター長","answer":"「１人になると危ないよ」という単元の中でしっかりと、万が一怖い目に遭ったときにはまずその場を離れる。離れてからまもるっちを引く、その上で１１０番をしたり、お店の人とか、近くの大人に助けを求めましょう、ここの指導を各学校では徹底しています。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問","question":"その指導は、事業者と警察署の指導で行われており、危険を感じたらすぐにブザーを引くように子どもたちに伝えられていました。こういったそごが発生する原因について、教育委員会はどのようにお考えなのか伺います。","respondent":"大関教育総合支援センター長","answer":"子どもたちに、助かるよというところを強調し過ぎてしまった事例があったというふうに、教育委員会は報告を受けております。それから大人に助けを求めるということを、大人向け、教員向けのテキストの部分を関係警察署とも共有をしたところです。","id":"exchange-036"},{"speaker":"田中委員","kind":"質問","question":"現在連携がとれているとは、ちょっと言えない状況があると思います。まもるっちの指導は学校の先生が行うよう見直すことで、認識の違いを生まず、子どもたちも混乱をしないと考えますが、教育委員会の見解を伺います。","respondent":"大関教育総合支援センター長","answer":"各警察署のスクールサポーターの方、あるいは生活安全担当を中心に、毎月の生活指導主任会にもご出席いただいておりますので、その中で引き続き共通理解を今後とも継続して図ってまいりたいと思います。","id":"exchange-037"},{"speaker":"田中委員","kind":"質問","question":"機能に追加されたＨＥＡＲＴＳについて伺うと、担当課では答えられないとのことでした。やはり子どもたちに直接かかわる教育委員会が主体となるべきだと、そのときにもやはり思ったのですけれども、見解を伺います。","respondent":"大関教育総合支援センター長","answer":"国立等へ通っている区民に対しても、まもるっちは対応されているというふうに伺っておりますので、区長部局全体で連携しながら進めているところです。新しい機種には、ＨＥＡＲＴＳのほうに、相談が入った場合には確実に受ける体制をとっているところです。","id":"exchange-038"},{"speaker":"田中委員","kind":"質問","question":"次に、人工芝生について伺います。教育委員会は校庭を人工芝生化していくことをいつ、どこの会議体で方針として持ったのか伺います。","respondent":"大関教育総合支援センター長、有馬庶務課長、菅生活安全担当課長","answer":"まもるっちの内容ですが、引き続き教育委員会といたしましては、生活安全担当とも連携をとりながら、さらに充実に努めてまいりたいと思います。 平成２９年度に向けての検討ということですけれども、デメリットを出しながら、そこで決めていったです。したがって、何かの会議体でということではなくて… これも児童や、こういった方に対しまして、まもるっちのシステムは一体どういったものかというこの機能や取り扱いを説明する取扱説明書であって。…","id":"exchange-039"},{"speaker":"田中委員","kind":"質問","question":"まもるっちは防犯システムではなかったですか。教育委員会としてしっかり把握していく、それでも生活安全担当でというのであれば、きちんと趣旨が共有されるようにしっかりとしてほしいです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"横山委員","kind":"質問","question":"１点目にマイスクール運営費についてお伺いいたします。品川区におきまして、平成２８年度にどのように周知され、現在どのような対応を行っているのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"不登校児童生徒への対応の指針といいますか、考え方、それから学校への働きかけという３点のご質問をいただきました。マイスクール五反田、そしてマイスクール浜川の３拠点を設置し、高校受験等にも困らない非常に手厚い体制というものをまずはそろえてまいりました。","id":"exchange-041"},{"speaker":"横山委員","kind":"質問・要望","question":"２点目なのですけれども、図書館経費についてお伺いしてまいります。平成２９年のレファレンスサービスの受付件数と実態を説明を求めました。","respondent":"大関教育総合支援センター長、横山品川図書館長","answer":"見守る、そのようなケースなど、いろいろ取り組み出したところです。この特別支援教室を週１回程度だけの活用ではなく、それ以外の日には… 平成２９年度のレファレンスサービスの実績ですが、全館合わせまして４万３,６５３件です。 マイスクールの荏原地区への設置の可能性ですが、マイスクール五反田の午後のコースを、今試験的にスタートしたところです。荏原地区の部分も含めまして…","id":"exchange-042"},{"speaker":"横山委員","kind":"質問・要望","question":"今お話をお伺いいたしましたので、一人ひとりの事情を見ながら、支援のほうを厚くしていってほしいと求めました。評価の仕方というものがしにくいというようにも言われておりますけれども、その重要性について区のお考えのほうをお伺いしたいと思います。","respondent":"横山品川図書館長","answer":"それについて図書館員が一緒に考えて、難しいケースにつきましては、国立国会図書館や都立図書館に協力を仰いで資料をそろえるようなこともあります。これからも拡大していきたいと思いますし、また、それを皆さんに知っていただくＰＲも重要だと考えています。","id":"exchange-043"},{"speaker":"横山委員","kind":"質問","question":"３点目に８３運動についてお伺いをいたします。４点目として英語教育、品川英語力向上推進プランについてもお伺いしてまいります。","respondent":"有馬庶務課長、熊谷指導課長","answer":"８３運動についてお答えいたします。現在は８３運動の推進委員会や小学校のＰＴＡ連合会が中心となって取り組みを行っております。 全３１校中１７校がTOKYO GLOBAL GATEWAYで活動を行いまして、既に５校が実施しております。来年度は２４校が実施する予定です。","id":"exchange-044"},{"speaker":"横山委員","kind":"質問・要望","question":"今回このTOKYO GLOBAL GATEWAYの活用の状況をお聞きした上でも、また学年の幅を広げたりなど、推進してほしいと求めました。こちらもし時間があれば一言お願いします。","respondent":"熊谷指導課長","answer":"現在２５０名の子どもが学んでおりますけれども、２泊３日のイングリッシュキャンプを行っているところです。今後はさらに一番近い江東区にあるTOKYO GLOBAL GATEWAYの活用なども考えて、さらに検討していきたいと考えています。","id":"exchange-045"},{"speaker":"横山委員","kind":"質問・要望","question":"ぜひ推進してほしいと求めました。８３運動については大変いい取り組みだと思いますので、ぜひ地域の方に啓発を引き続きお願いしたいということを要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"つる委員","kind":"質問・要望","question":"すまいるスクールでの夏季休業中の配食サービスの活用は子ども未来部のほうに求めましたけれども、例えば給食室の改修となったときに、一。これは要望させてほしいと求めました。","respondent":"大関教育総合支援センター長、菅生活安全担当課長","answer":"で、おおむね１５分程度で歩いていける範囲にあり、地域の学校をあえて安全の観点から選択していただいている保護者の方も多うあります。基本的には学校において、本区におきましては、そのような心配は今はしていないところです。 現在、例えば学校に来ていないということであれば、学校のほうからセンターのほうを通じまして、その児童の位置探査をしています。そういったことで…","id":"exchange-047"},{"speaker":"つる委員","kind":"質問","question":"ですから地域性もあると思いますが、今後さらにそうした防犯面。中川恵一准教授などを講師に招きがん教育をやってもらうなど、そういったことも必要かなと思いますけれども、そのあたりのご見解を説明を求めました。","respondent":"大関教育総合支援センター長","answer":"がん教育についてですが、子どもたちに対する中川准教授の医療チームの医師に直接教えていただく授業を、もう既に予定しています。家庭教育講演会として、家族ぐるみでがんについて考える講演会なども、教育委員会としては予定しておるところです。","id":"exchange-048"},{"speaker":"つる委員","kind":"質問・要望","question":"貸し出しができるようになっているのが確認できたのですが、そうした中で、いろいろなところでもう既に宣伝等があるわけですけれども。ですから、そうしたものの活用も含めて、これからどのように魅力ある図書館をつくっていくのかというところを説明を求めました。","respondent":"横山品川図書館長","answer":"所蔵についても、増やすように検討します。区民の本棚として、また居場所として、充実させていきたいと思います。","id":"exchange-049"},{"speaker":"つる委員","kind":"質問・要望","question":"区民の本棚として、しっかりとこれから展開してほしいと求めました。まさに図書館がそのような存在になると思いますので、ぜひ区民の方の本棚として、これからも充実を図ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"おくの委員","kind":"質問","question":"成果報告書の１８７ページ、教育指導費の中の学力定着度調査経費にかかわって、いわゆる学力テストについて伺います。学力４層の分類が使われていますが、その増減変化がどうなっているのか、もしわかるようならお教えいただければありがたいと思います。","respondent":"熊谷指導課長","answer":"今、手元に具体的な資料はないのですが、ただ正規分布の５段階にしますと、１に当たるところが７％というような状況です。","id":"exchange-051"},{"speaker":"おくの委員","kind":"質問","question":"１に当たるところというのは最下位層、５分類の内一番最下位に分類されるのが７％、平成３０年度はいたという理解でいいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"おくの委員","kind":"質問・要望","question":"そこでお伺いします。あるいは品川区学力定着度調査を行っている学校において、勉強好き、あるいは勉強嫌いの調査をされているのか尋ねました。","respondent":"熊谷指導課長","answer":"例えば国語は好きですかですとか、英語は好きですかといった調査は、子どもたちに行っているところです。","id":"exchange-053"},{"speaker":"おくの委員","kind":"質問","question":"やはり全般的に勉強、つまり学ぶことが好きなのかどうなのかということを、私としては子どもたちに聞いてほしい。検討をお願いいたしますが、いかがか尋ねました。","respondent":"熊谷指導課長","answer":"それを教員自身が、どこにつまずきがあったのか、１００人の教員で全部分析しました。子どもたちにとってわかる授業、そして子どもたちに真の意味で学力がつく授業への転換ということで、今回品川区立学校教育要領を改訂したところです。","id":"exchange-054"},{"speaker":"おくの委員","kind":"意見","question":"この問題を見た限り、私は余りいい問題だと思いませんでした。その工夫していることはわかるのですが〔時間切れにより答弁なし〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"筒井委員","kind":"質問・要望","question":"私からは１８８ページの理科観察実験支援事業に関連して、理数系科目の教育についてお伺いをいたします。時間があれば１８９ページ、オリンピック・パラリンピック教育推進事業についてお伺いをいたします。","respondent":"大関教育総合支援センター長","answer":"今ご指摘いただいたように、理数系教育の充実は、本区にとりましても重要な課題の１つというふうに認識しております。例えば５年間セミの研究をした清水台小学校の６年生のお子さんは、過去５年間の研究を通して、分布の推計調査まで行うような発表を行いました。","id":"exchange-056"},{"speaker":"筒井委員","kind":"質問・要望","question":"非常にユニークな取り組みをやられているということで、引き続き理数系教育を充実していっていただきたいのですけれども、課題があると思うのですが、今その理数系教育において、品川区の課題は何か尋ねました。","respondent":"大関教育総合支援センター長","answer":"教員が、昨今新たな小学校の教諭なども増えてくる中で、まだまだ不慣れなところへの手当てを今行っているところです。教科書で覚えるだけでなく、実験を確実に行える、そのための支援員の配置なども行っているところです。","id":"exchange-057"},{"speaker":"筒井委員","kind":"質問","question":"お聞きをしましたが、平成３０年度の結果を見ますと、これもちょっと課題ではないのかなと思っています。不慣れということと、理科の成績が余り伸びないということについて、今後品川区としてはその解決法をどのようにお考えになっているのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"先ほど申し上げました実験の強化以外に、やはり子どもたちがしっかりと興味を持てる題材、学習の場を提供できるように、教員の研修も充実が必要だと考えておりますので、次年度各校理科教員を対象とした研修の充実も含めた検討を、今行っているところです。","id":"exchange-058"},{"speaker":"筒井委員","kind":"質問","question":"成績が下がっているということについては、どうお考えになっているのか、そしてこれをどう克服していくのかということについて、何か対策というものは考えられているのか尋ねました。","respondent":"熊谷指導課長","answer":"そのときは楽しく実験をするのですけれども、何年かたつとすっかり忘れてしまうといったような状況になります。教員自身が確認し、子どもたちにもわかるように指導したり、そういったプリント教材を作成しています。","id":"exchange-059"},{"speaker":"筒井委員","kind":"質問・要望","question":"そして知識を定着させていくということが非常に大事だと、私も今お話を伺ってそう思いました。そのような学校や施設と提携してやっていっていただきたいのですけれども、ご予定あれば、その点をお知らせください。","respondent":"大関教育総合支援センター長","answer":"今ご案内いただきましたように、産業技術高等専門学校との連携も進めながら、さらに後期課程の段階ではものづくり教育ということで提携をする。教育委員会としても前向きに検討を進めているところですので、理数、子どもたちの指導を充実させてまいりたいと考えています。","id":"exchange-060"},{"speaker":"筒井委員","kind":"質問・要望","question":"そのためには授業の工夫というものも必要だと思いますので、その点もよろしくお願いします。要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-061"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"初めに東京２０２０オリンピック・パラリンピック競技大会、区内開催競技と応援競技の３競技について質問をします。その取り組み内容と、現状をお知らせほしいと求めました。","respondent":"熊谷指導課長","answer":"スクール」に国から、そして都からも指定されております。トライアスロンの場合は見るということが中心になりますけれども、さまざまなオリンピアン、パラリンピアンを招いた事業を行っているところです。","id":"exchange-062"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"はパラリンピックの競技応援校ですか、平成３０年度は７校、あと２園の９つになるのですね。５校から２校増えていますが、平成３０年度は新しい学校も入っているかと思いますので、その辺の仕組みを教えてほしいと求めました。","respondent":"熊谷指導課長","answer":"平成３０年度は昨年度の取り組みが都に評価されまして、アワード校が７校２園、そしてパラリンピック競技応援校が１校ということになっております。多分今行っている２園、８校につきましては、今の段階では何とも言えないところです。","id":"exchange-063"},{"speaker":"高橋（伸）委員","kind":"質問","question":"平成２９年度、平成３０年度も城南小学校や京陽小学校、学校の選定についてです。小中一貫校、そして分離型の小・中学校というのは、どのように選定をされているのかお聞きしたいと思います。","respondent":"熊谷指導課長","answer":"それぞれの幼稚園、そして学校が自主的に立候補してきたという経緯があります。今回幼稚園が２園となっておりますけれども、それぞれの園、学校でテーマを決めてやってきたことが認められたということになります。","id":"exchange-064"},{"speaker":"高橋（伸）委員","kind":"意見","question":"決算が３５０万７,０００円で、それについての講演等講師謝礼が、当初予算ですと６２０万円で決算が７４５万円余なのです。区内開催・応援３競技体験教室が減っているのに、どのようなことでそうなっているのかお知らせをお願いしたいと思いますとの意見を述べました。","respondent":"熊谷指導課長","answer":"その中で、学校によって学級数の差があったり、それに伴って時間が異なってまいりますので、実際行ってみたところ余裕があったというところです。その分を、せっかくなのでオリンピアン、パラリンピアンを学校に呼びたいというところに充てたということになっております。","id":"exchange-065"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そうしますと、来年度もそういった形がとられれば、金額の変動等はあり得るということですよね。そうするとオリンピアンを呼んだりなどということも、来年度も続けていくということでよろしいか尋ねました。","respondent":"熊谷指導課長","answer":"オリンピアン、パラリンピアンにつきましては、次年度も引き続き招致してまいりたいと考えています。それに伴ってということになりますけれども、できる限り一生に一度しかない経験を子どもたちにたくさん味わわせたいと考えております。","id":"exchange-066"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして１９０ページ、ＰＴＡ関係費に関連をしまして、質問をします。そのようなときの対策というものは、あとＰＴＡや近隣の、学校としての近隣の対策はどのように取り組んでいるのか教えてほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"例えば運動会の前に、ぜひお願いしますとお願いに行くということを、しているかしていないかで大きく対応が違います。可能な範囲で学校も配慮しつつ、近隣の方にも何とかご理解いただけるようにお願いに上がるということが基本的な対応です。","id":"exchange-067"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そういった子どもたちの部活動の声も、当然それはわかるのですけれども、このような場合の案件というものはどのように考えたらいいのでしょうか。説明を求めました。","respondent":"有馬庶務課長","answer":"どのように対応していくかということで、いろいろ対応はしたところですけれども、なかなか応じてもらえず対応に苦慮しています。規模を少し小さくするなど、こちらもある程度条件を示しながら、また相手の方と交渉のようなことを続けていければと思ってあります。","id":"exchange-068"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"この問題は旗台小学校だけではないと思います。ぜひその辺のところは子どもたちのためにも、この環境学習のためにも、改善をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"},{"speaker":"あくつ委員","kind":"質問","question":"１つ目は市民科に関連しまして、士業による外部講師の授業について伺います。ほかにどのような教育を行っているのか、また、それに対しての品川区としての支援があるのかどうか伺います。","respondent":"大関教育総合支援センター長","answer":"従来教育委員会から学校への支援といたしましては、ご厚意で本当に出前授業として、費用負担なくご協力いただいてきたというのが経緯です。専門的なプロの方にご指導いただくための講師料が必要かどうかも含めて、今後検討をしなければならないというふうに我々も認識しています。","id":"exchange-070"},{"speaker":"あくつ委員","kind":"質問・要望","question":"恐らく各会派にも要望が来ていて、教育委員会としても支援をされていく必要があるのではないかと思いますが、最後に確認で質問いたします。","respondent":"大関教育総合支援センター長","answer":"どういった内容が必要なのかも含めて、ぜひ検討しながら、一度に全てということは難しかったとしても、ぜひ行いたいという学校を応援していけるように、準備はしていきたいと考えています。","id":"exchange-071"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ちょっと私ども区民からさまざまなご意見があったので伺いたいのですが、まず基本的なところから、なぜ牛乳なのかと。なぜ緑茶ではだめなのか、その理由について教えていただきたいということが１つ。","respondent":"篠田学務課長","answer":"学校の設置者であります区におきましては、その学校給食会にこの牛乳の納入を委任するというような関係にあります。次に、現在国からは牛乳１本当たり４銭の補助金が出ているということで、こちらの手続に関しても学校給食会が行っているものです。","id":"exchange-072"},{"speaker":"あくつ委員","kind":"質問","question":"それともう１点、プラスチックストローの件で伺います。誰がこのストローを卸しているのか、いわゆる納入しているのか、簡潔に説明を求めました。","respondent":"篠田学務課長","answer":"教職員は１,５００人から２,０００人程度ですので、２万数千本、２万２,０００本ぐらいの数のストローが毎日使われているということになります。実際実施日数はそれぞれの学校微妙に違ったりもするのですが…","id":"exchange-073"},{"speaker":"あくつ委員","kind":"確認","question":"１９５日で換算をすると、大体年間で４２９万本が品川区内で消費をされているということを確認させていただきました。いろいろ聞きたかったのですが余り時間ないので、平成２９年度の志願者数に対する合格者数とその割合を説明を求めました。","respondent":"篠田学務課長","answer":"平成２９年度の英検の志願者数です。志願者数が２,０７５名、合格者数が１,２１９名で、合格率が５８.７％となっています。","id":"exchange-074"},{"speaker":"あくつ委員","kind":"質問・要望","question":"には一部助成で回数を増やすということも１つでしょうし、例えば英検３級をとるというような、ちょっと高めの設定をしてなるべくとっていく。こういったことが必要ではないかと思うので、ぜひ研究をしていただきたいと思うのですが、いかがか尋ねました。","respondent":"篠田学務課長","answer":"現在の英検の助成につきましては、まず英語検定に関心を持っていただくといった前提で、こういった形で幅広の制度となっています。この先、委員のご指摘のような形の導入もあり得るのかどうか、研究しながら現状の推移を見守っていきたいというふうに考えているところです。","id":"exchange-075"},{"speaker":"安藤委員","kind":"質問・要望","question":"１９１ページ、大崎図書館について伺います。解体計画は中止するよう求めますが、いかがか尋ねました。","respondent":"立木経理課長","answer":"大崎図書館のほうですが、こちらのほうは教育の行政財産から普通財産に今現在切り替わっておりまして、今解体の設計が終わり、これから解体工事の着手に移るというような段階になっております。","id":"exchange-076"},{"speaker":"安藤委員","kind":"質問・要望","question":"御殿山小学校の隣地で文教施設としての施設が求められたこと、２９号線整備の代替地の話は、移転判断後に都から話があったとの説明でした。大崎図書館の移転理由は、本当は２９号線道路のためだと、区民になぜ説明しなかったのか、理由を伺います。","respondent":"柏原企画調整課長","answer":"これはこれまでもずっとご説明してきた中で、今委員もご紹介いただきましたけれども、ＳＨＩＰが新しい開発のエリアででき上がったと。そういったものを１つのまとめとしてお話をさせていただいているといったところです。","id":"exchange-077"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いますけれども、今課長がおっしゃった答弁というものは、全く区長の挨拶と違うのです。この区長の発言が２９号線と関係ないと主張されるなら、その理由をしっかりとご説明ほしいと求めました。","respondent":"柏原企画調整課長","answer":"結果として２９号線に関して東京都のほうからの打診があって、順番というところではまず移転の考え方が先にあって、その後２９号線道路の話があったというものです。","id":"exchange-078"},{"speaker":"安藤委員","kind":"質問","question":"区長自身が２９号線で移転することになった、その後どうするかということを考えて、この場所が見つかったということを挨拶で述べているわけです。なぜそのような発言をしたのか、この２９号線のためだったということではないのか、区長にお伺いしたいのですがいかがか尋ねました。","respondent":"柏原企画調整課長","answer":"その後に東京都のほうから道路に関する協力ということの要請があって、形としてはこのような経緯で、今動いているというものです。ですので、それをトータルの話でお話を申し上げたと先ほど申し上げたとおりでございまして、そういったところでは矛盾はないと考えています。","id":"exchange-079"},{"speaker":"安藤委員","kind":"質問","question":"どうなのでしょうか。伺います。","respondent":"柏原企画調整課長","answer":"間違いということではなくて、私は再三ご答弁申し上げているのですが、今までの経緯をお話しいたしました。そういった経緯をトータルして挨拶のときにお話しさせていただいたというものですので、矛盾はないと思ってあります。","id":"exchange-080"},{"speaker":"安藤委員","kind":"質問","question":"なぜ２９号線の整備が、この大崎図書館の移転の目的だということを品川区は隠すのでしょうか。伺いたいと思います。","respondent":"柏原企画調整課長、横山品川図書館長","answer":"そういったところで、協力できるのではないかということで、協議を進めてきているといったものです。隠さないの話ではなくて、そういった経緯があったですので、ぜひともご理解いただければと思います。 大崎の移転に関しましては、惜しむ声もたくさんいただきましたが、移転後につきましては非常にご好評を得ております。","id":"exchange-081"},{"speaker":"本多委員","kind":"確認","question":"今、平成２９年度の審議をしておりますので、私の質問は２月１９日にオープンしたこの西口取次施設です。わずか５週間で４,５５４冊を取り次ぎ、３５年間使ったところが使えなくなっても、しっかりと使えるというところを確認したいと思います。","respondent":"横山品川図書館長","answer":"今ご指摘のありました大崎の３地区の図書施設につきまして、利用が多くて本がなくなるぐらい、とても好評をいただいております。今後も分館の準備を着実に進めまして、３館で大崎地区の図書環境を充実させていきたいと思います。","id":"exchange-082"},{"speaker":"本多委員","kind":"質問","question":"しっかりこの４年半議論してきた、積み上げてきたもの、やはりこれは地域の声なのです。本当に残念だと思って関連質問させていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-083"},{"speaker":"木村委員","kind":"質問","question":"このいじめ根絶協議会４０万円余、そしていじめ対策委員会３０万円余ですけれども、この協議会と委員会との違いは何か尋ねました。","respondent":"大関教育総合支援センター長","answer":"あるいは前年度１年間の取り組み内容の成果と報告などもしながら、また次年度の施策に活かしていく、そのような協議団体の場となっております。教育委員会が設置する調査組織にもなる委員会となりますので、アドバイスをいただいている、そのような会議体となっております。","id":"exchange-084"},{"speaker":"木村委員","kind":"質問","question":"早期解決を図るなど、地域社会が一丸となって防止対策に努める、取り組むことが必要とあります。一般的にいじめ等は水面下で行われることが大変多いわけでありますけれども、学校側や先生はどのように察知をすることが多いのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"その中には自分のことではなくて、気づいたことがあれば担任に対して発信をしてくれるような、そのような取り組みをやっている学校もあります。さまざまな形で発見、ＳＯＳを見逃さない仕組みについて、今充実に向け努めているところです。","id":"exchange-085"},{"speaker":"木村委員","kind":"意見","question":"自分の子どもがいじめに遭っていることがわかった場合、文句を言い、どなり込んでいく親御さんというものも、昔はよくあったものでありますけれども、今現在もそういうこともあろうかとは思いますが、冷静に考えた場合に、親は今どのような行動をとったほうがいいのか、その点も説明を求めました。","respondent":"大関教育総合支援センター長","answer":"いじめたり、いじめられたりすることはあり得るのだ、どの学校にもあり得るということをまず大前提としてご理解いただいております。その上で、また教育委員会としてはＨＥＡＲＴＳ、スクールソーシャルワーカー等が専門家として支援に当たっております。","id":"exchange-086"},{"speaker":"木村委員","kind":"意見","question":"いじめた児童・生徒に対して厳しく注意し、罰することも多くあろうかとも思います。そういった生徒の身になって、より一層深くかかわってほしいと思いますが、どのような接し方をするのかお聞かせをくださいとの意見を述べました。","respondent":"大関教育総合支援センター長","answer":"何か寂しさ、背景要因は何なのか、やはりそこに気づくことは重要なことだと我々も認識しております。これからもその背景要因に接した上での支援という視点は大切にしていきたいと思います。","id":"exchange-087"},{"speaker":"木村委員","kind":"意見","question":"いじめを通り越した事件と言うべき行為が過去にあったのか、もしあった場合にはどのように対処をしたのか、それを繰り返さないようにするためにはどのようなフォロー、そして手当てが行われたのか、お聞かせをくださいとの意見を述べました。","respondent":"大関教育総合支援センター長","answer":"個別のケースですので具体的なお話は申し上げられませんが、家庭での生活がその子自身にとってなかなか難しいようなケースも時にはあります。そのような場合には、やはり専門機関と一緒に相談しながら、本人のよりよい生き方のためにどうすべきか関係機関と相談をします。","id":"exchange-088"},{"speaker":"大沢委員","kind":"質問・要望","question":"１８６ページ、それと１８８ページ、それと１８９ページの保幼小連携推進経費ということで伺っていきたいと思います。４つありますけれども、これは平成２０年から国のほうで指針が出てきたわけですが、相違点があるようであれば教えていただきたい。","respondent":"大関教育総合支援センター長","answer":"従来から、やはり言語活動は大切な教育活動の根幹をなすものだというふうに、教育委員会では認識しております。これまでの間取り組んでまいりましたが、そこをしっかりと表現できるようにしていく、そこをさらにここ数年は各学校とも研究を進めているところです。","id":"exchange-089"},{"speaker":"大沢委員","kind":"質問・要望","question":"この言語活動の充実において目的とする、最終到達点として子どもたちに求める目的、成果、どのようなものを想定されているのか説明を求めました。","respondent":"大関教育総合支援センター長","answer":"国際的な社会の中で日本人として通用していく、そこがまず基本として大事だと、義務教育学校段階ではそこを高めたいということで目的としております。","id":"exchange-090"},{"speaker":"大沢委員","kind":"質問","question":"その中で今、アクティブラーニングという言葉が出ました。社会人ということで認識をしているのですけれども、そこを学校に今当てはめながらやろうという、そのような取り組みなのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"しっかりと考えていくためには、そういった授業のほうに、大学等の高等機関も生まれ変わってきている最中です。相手の発言のどこの部分をしっかりと押さえるのか、取りこぼさずに意味を捉えるのか、そういったことを日々の学習の中で行っています。","id":"exchange-091"},{"speaker":"大沢委員","kind":"質問","question":"その中で相手に伝える、双方向性という点から見れば、ディベートという手法もあるわけであります。物事を話す、ディベートは日本人になじまないのではないかなという気がしますが、そこの部分は教育委員会としてどのようにお考えなのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"市民科の学習の中では何かについて子どもたちが話し合う１つの手法、今この場では意見が対立するけれども、これは決してけんかではない。そういった意味をしっかりと教員が子どもに提示した上で行うディベートは意義があるというふうに学校では捉えております。","id":"exchange-092"},{"speaker":"大沢委員","kind":"質問・要望","question":"子どもたちにはディベートの意義、意味、日本人におけるディベートの意義というものをしっかりと教えてほしいと求めました。そこには語彙力が必要でありまして、語彙力を高めるための取り組みは、今どのようにされているのか尋ねました。","respondent":"大関教育総合支援センター長","answer":"例えば文字で認識するだけではなく、言葉、子どもたちの記憶に植えつけられていくものというふうに学校教育では考えております。ドリル等だけではなくて、そして書いた内容を発表させる、そういった日々の活動を繰り返すことで子どもたちの語彙力は高まっていくと思います。","id":"exchange-093"},{"speaker":"大沢委員","kind":"質問","question":"これがまず語彙力を高める方法の１つだと思いますし、先生方の裁量にもよるかと思うのですが、そういうものを利用した語彙力を高めるための授業ということは行われているのか尋ねました。","respondent":"熊谷指導課長","answer":"明治以降、特に明治時代の小説等にも、美しい言葉がたくさん出てきます。読書を通して語彙力を高めていくということも重要であろうかと考えます。","id":"exchange-094"},{"speaker":"大沢委員","kind":"質問・要望","question":"１つだけ、英語の語彙について伺いたかったのですが、和製英語というものがありますが、外国人にはこれが全然通じません。和製英語という単元、１つのプログラムで先生方が１つのユーモア、ユーモラスな部分として教えていらっしゃる時間といういうものはあるのか尋ねました。","respondent":"熊谷指導課長","answer":"特に年代を越えて高齢者の方とお話しするときにも、和製英語でないと伝わらないということもあろうかと思います。ですので、日本人として和製英語は大事にしていきたい言葉の１つであろうかと考えています。","id":"exchange-095"},{"speaker":"大沢委員","kind":"質問・要望","question":"毎日いろいろな予習等々で大変だと思うのですけれども、子どもたちに伝えるには先生方の話術なり、話し方のスキルが必要だと思うのです。研修等々で行われているとは思いますけれども、そこではどのようなことが行われているのか、ご披露してほしいと求めました。","respondent":"大関教育総合支援センター長、熊谷指導課長","answer":"区が行う研修以外に、東京都が行う研修などもございまして、その中には話法について学べるような機会もあります。プロの方のお話を聞くような機会などもありますし… 区の固有教員の研修ですけれども、昨年度は松竹芸能に来ていただいて、漫才師の方に笑育をやっていただきました。それから子どもたちの前でどのように伝えればいいのかというような、そういった授業を行っていただいたところです。","id":"exchange-096"},{"speaker":"大沢委員","kind":"提案","question":"これが適切な提案かどうかはわかりませんけれども、例えばお酒を飲んでいる時間などに落語を聞いていただきながら、その話し方について醸成を図ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-097"},{"speaker":"たけうち委員","kind":"提案","question":"私は成果報告書の１８７ページ、市民科・各教科充実経費、１９４ページ、通学安全確認業務等委託について伺います。その際、すでに、改訂版の防災ノートを品川区では７月に低学年から中学生まで漏れなくお配りをして取り組んでいるということを伺いましたとの意見を述べました。","respondent":"大関教育総合支援センター長","answer":"あるいは、低学年の子ですと、自分たちの地域に大雨が降ったらどうするなどということを考えるような題材のページもあります。それから担任が子どもたちに対して避難訓練の後、教室に戻ってから、さらに必要に応じて加える場面などでうまく活用しています。","id":"exchange-098"},{"speaker":"たけうち委員","kind":"質問","question":"本当に１ページでも２ページずつでも、かまわないのでしっかり取り組まれると本当に力になるなと思いましたので、お願いしたいと思います。これも聞けますので、何か代表の電話を使ってやってみるなどということも大事かなと思いますけれども、その辺のことを説明を求めました。","respondent":"大関教育総合支援センター長","answer":"実際に１７１の伝言ダイヤルにつながるとこのような音声が流れるというのを子どもたちに示してみる、そのような取り組みも有効かと思いますので、ぜひいただいた意見は共有していきたいと思います。","id":"exchange-099"},{"speaker":"たけうち委員","kind":"質問・要望","question":"研修まではいかないかもしれませんけれども、先生が現場で取り組むわけなので、ぜひその辺しっかりお伝えほしいと求めました。いわゆる今回の大阪府北部地震を受けて、その状況と、あわせて今後その所有者等に対するアプローチをどのように考えているのか説明を求めました。","respondent":"有馬庶務課長","answer":"回答につきましては、ひとまずそのような危険なブロック塀があるか、ないかというような報告は一応いただいているところです。学校の人たちが見て、まずは建築基準法で言われている２.２ｍ以上の壁があるかないか、学校のほうでは対応しています。","id":"exchange-100"},{"speaker":"たけうち委員","kind":"質問","question":"地震が起きて子どもたちがそのような目に遭っては、何のためにこのようなものができたかわかりませんので、ぜひそこはお願いしたいと思います。それができるまでは、今おっしゃったように学校でも通学路の安全マップと危険マップというのでしょうか、その件とあわせて見解をお示しください。","respondent":"有馬庶務課長、大関教育総合支援センター長","answer":"前段のほうの建築課との連携ですけれども、連携をとりまして、これを見ながら今回の対応についても参考にしてくださいというようなことでやりとりはしています。 ヒヤリハット地図につきましては、毎月見直しを関係機関の協力を得ながら、各学校行っているところです。当然交通事故の観点以外にも、関係機関ともその辺の部分は情報を共有しながら…","id":"exchange-101"},{"speaker":"たけうち委員","kind":"質問・要望","question":"今通学路に、ここにあるとおり通学安全確認の業務を委託してやっていただいている、主にシルバー人材センターの方もいらっしゃいますが。そうした面でいうと、できればそういう方たちからお声をかけていただくということも大事だと思うのですが、あわせて説明を求めました。","respondent":"有馬庶務課長","answer":"それから子どもたちの安全を見守るというような巡回をしてくれる方たちの２本立てで業務を行っております。そういった方たちについても、学校で今回把握した危険なブロック塀の場所など、情報共有できればしながら進めていきたいところです。","id":"exchange-102"},{"speaker":"たけうち委員","kind":"質問","question":"一般質問でも質問いたしましたが、私も今回それが大事だという思いで、各款別の中で主に防災等の関連の質問を取り上げさせていただきました。今後もしっかり取り組んでまいりたいと思いますので、ぜひ。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-103"},{"speaker":"飯沼委員","kind":"質問","question":"平均ですから毎週４０時間の労働のほかに毎週１５時間ずつ残業、つまり毎週５５時間働き続けるといった内容になっていて、私もびっくりしました。改善策はどうなっているのか説明を求めました。","respondent":"熊谷指導課長","answer":"さらに防災待機寮の対応というものがございまして、それから掃除に行ったりといったようなこともあります。給与や福利厚生費の対応も指導課で行っているところです。","id":"exchange-104"},{"speaker":"飯沼委員","kind":"質問","question":"指導課２４人に対して仕事量が多過ぎるのではないでしょうか。教員の長時間労働の原因はどこにあるのか、改善策を具体的に説明を求めました。","respondent":"熊谷指導課長","answer":"さらに働き方改革を進めまして、それがそれぞれ小学校で３分、中学校で２分、平均で減っているところです。原因なのですけれども、東京都や文部科学省が進めようと思っているさまざまな働き方改革の取り組みは、全て品川区では行ってきています。","id":"exchange-105"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１日８時間ではおさまらない仕事量があるということは、共通の認識になっているのでしょうか。この認識を持っていただきたいのですけれども、その点はいかがか尋ねました。","respondent":"熊谷指導課長","answer":"先ほどご質問がありました指導課の人員ですけれども、平成２９年度は１名増、そして平成３０年度も１名増となっております。これは本区ならではのものですけれども、そこの部分の補佐的なところができて、今回長時間労働の部分が改善に至っている部分です。","id":"exchange-106"},{"speaker":"飯沼委員","kind":"質問・要望","question":"国に求めていくのは当然ですけれども、ぜひ教員を増やしていただきたい、この点が１点です。この中には休養日週２日以上、ぜひこれを現実のものにしていただきたいのですけれども、いかがか尋ねました。","respondent":"大関教育総合支援センター長、熊谷指導課長","answer":"部活動のあり方につきましては、各学校のほうに通知をするとともに、平日においても休養日、そして土日においても必ずどちらか１日は休みを設ける。公式戦も含めまして土日と試合が続いたような場合は… 平均１７分の勤務時間の短縮、できるだけのサポート体制はつくっていきたいと思います。固有教員につきましては、さまざま今固有教員のあり方等についても検討していますので、今後の課題というふうになるかと思います。","id":"exchange-107"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ校長先生や副校長先生だけではなく、全職員の意見をしっかりと聞いて、見直しをしていただきたい。ここのところはいかがか尋ねました。","respondent":"熊谷指導課長","answer":"それから電話対応、そういったことを全てなんでもこれまで教員がというところがありましたので、１回洗い出しをしています。どういったところをこれから働き方改革で進めていくか、それも既に浜川中学校等では見直しを図って、協議を行ったところです。","id":"exchange-108"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いろいろ現状でできる部分や工夫がされているのは、お話を伺いました。今回の学事制度審議会の答申を受けての学校選択制の見直しに絞って、内容を教えてほしいと求めました。","respondent":"若生学校制度担当課長","answer":"そういったことをこれまで以上に強力に進めていく、これはさまざまアンケート等も審議会の中でとってまいりまして、議論を重ねてきたところです。広く選べるような形から、ブロック制から隣り合う学区域の中で選べるという形に見直すべきといったことで答申が出たものです。","id":"exchange-109"},{"speaker":"飯沼委員","kind":"質問・要望","question":"そして反対、疑問が２２件、改善を求めるが１０件だったのです。再検討をお願いしたいと思いますが、いかがか尋ねました。","respondent":"若生学校制度担当課長","answer":"３つも４つも学校を越えて、そういった意味で近隣等の地域とのつながりというものはより深まるというようなことを考えてあります。そういった中では廃止すべきというものは１割に満たない数字で出ておりますので、そういったところからも続けるべきと考えております。","id":"exchange-110"},{"speaker":"伊藤委員","kind":"確認","question":"確かに進捗していることは確認したのですけれども、たまたまなのかもしれませんが、黒板にチョークで板書をされている授業がほとんどでした。インカムを含めた教材を活用して、児童・生徒にわかりやすい授業展開すべきと思ったのですが、いかがか尋ねました。","respondent":"篠田学務課長","answer":"電子黒板等が設置されまして、これも平成２７年なのですけれども、プロジェクターを毎週利用していると回答した小学校の教員が７割を超えています。そのうちの毎日利用していると答えた教員が５３％ということで、３年前ですので…","id":"exchange-111"},{"speaker":"伊藤委員","kind":"確認","question":"方向性の確認はこれで終わりますけれども、要は効果的に使ってくださいということをお願いしておきます。そのときに品川区から配付されたパソコンはどうされているのでしょうかということが１点。","respondent":"篠田学務課長、大関教育総合支援センター長","answer":"ただ、一部教育系のデータなどの部分です。要は個人情報のないものに関しては、学校長の許可を得て持ち出しすることが可能となっております。 各教科ごとの教科会として共有フォルダーを区で設けておりますので、その中に保存して各学校の、例えば理科の教員が理科に有効な教材について全校で同じものを有効活用しているという仕組みは今整ってあります。","id":"exchange-112"},{"speaker":"伊藤委員","kind":"確認","question":"もう少し確認したいのだけれども、教材の学校ごとのアイデアはわかったのですが、要は個々の教員の指導方法がありますよね。お願いいたします。","respondent":"篠田学務課長","answer":"確かに委員ご提案のとおり、それぞれの教員のノウハウを持ち出して新しい学校で使っていくことは確かに有効な手法の１つだとは考えます。それは一定の手続をとった上で持ち出すという形になるものです。","id":"exchange-113"},{"speaker":"伊藤委員","kind":"確認","question":"デジタル時代ですから、新しい課題といえば課題なのだけれども、でもうまく活用していかないともったいないです。改めて文部科学省のホームページをいろいろ確認していたら、２０２０年度から全ての小学校においてプログラミング教育が必修化されます。","respondent":"篠田学務課長","answer":"これから先ＩＣＴ化がどんどん進展してくるのは間違いないだろうというふうに私どもも認識しています。しかしながら、そういったところ、どういったタイミングでどういった形で取り組めるのかということを慎重に考えてまいりたいと思っているところです。","id":"exchange-114"},{"speaker":"伊藤委員","kind":"意見","question":"もっと、１,０００分の１ぐらいだったかもしれませんけれども、でも非常に事務的な効率が上がったことを覚えています。予算化、そしてそれを品川区にも反映させていく仕組みをさらに検討すべきだと思うのですが、改めてご答弁をお願いいたしますとの意見を述べました。","respondent":"篠田学務課長","answer":"今後ＩＣＴ化の進展がとめられないことは間違いないという認識は持ってありますので、さまざまな部分を総合的に判断しながら、今後の展開について慎重に検討してまいりたいというふうに考えておるところです。","id":"exchange-115"},{"speaker":"伊藤委員","kind":"確認","question":"品川区に影響は出ないのかという確認だけお願いいたします。","respondent":"佐藤保育課長","answer":"私立の関係に関しましても連携をして、しっかり進めていきたいと考えております。","id":"exchange-116"},{"speaker":"若林委員","kind":"質問・要望","question":"１９２ページの学校管理費から自転車ヘルメットについて伺います。それから自転車にかかわった死亡事故も含めた事故の傾向性を確認させてほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"これはもう校長会の取り組みとして、引き続き１年生から６年生全員に渡るという状況をまずは担保した上で、交通安全指導を各校が進めております。特別支援教室担当の教員は、担当する学校には週１回、連携は非常に重要となっております。","id":"exchange-117"},{"speaker":"若林委員","kind":"質問・要望","question":"特別支援学級の学年別の人数、また特別支援教室の学年別の人数をわかれば教えてください。これも介助員、学習支援員の対象となっている子どもたちの、学年別の児童・生徒数がわかれば確認をさせてほしいと求めました。","respondent":"熊谷指導課長、大関教育総合支援センター長","answer":"先に特別支援学級の免許の所持率ですけれども、こちらにつきましては２３.３％、３０名です。 それから特別支援教室のほうになりますと、これは小学校段階では今年度４１６名に対応しています。今、小学校の学習支援員は２４８名の児童に対してついておりましたが…","id":"exchange-118"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１９６ページの学校給食費について伺いたいと思います。子育て支援や教育の充実という点からも、ぜひとも学校給食費の無償化を求めたいと思います。","respondent":"篠田学務課長","answer":"それから多子家庭のほうの給食費の補助金ですけれども、お子さんの数が、これも平成２９年度で２３０名、金額で申しますと１,０７６万円余です。先ほど申し上げましたトータルの１１億円から、この２つの金額を差し引きますと…","id":"exchange-119"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"第２条では学校給食の目標として、さまざま７項目が書かれておりますけれども、区の見解はいかがか尋ねました。","respondent":"篠田学務課長","answer":"委員ご指摘のとおり、学校給食の目的といった部分に教育的な見地が含まれること自体は、そのとおりであるものというふうに認識しています。","id":"exchange-120"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それであれば、私はこの給食費も無償化が求められると思うのですけれども、いかがでしょうか。文部科学省は平成２９年度に学校給食費の無償化等の実施状況ということで調査を行いましたけれども、その考え方についても説明を求めました。","respondent":"篠田学務課長","answer":"ちなみに光熱水費につきましては、こちらで光熱費については学校の設置者が負担することが望ましいということとされているということを踏まえまして。法の規定に基づいた形でそれぞれ必要な部分、そういった意味で実質上…","id":"exchange-121"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"補助金を出すことによって実質無償化にすることを禁止するものではないという見解が、文部科学省のほうからは出されているのです。ということで、実際に全く給食費がかからない、本当の無償化ということは可能だと思うのですけれども、その点についてはいかがか尋ねました。","respondent":"篠田学務課長","answer":"しかしながら、法の規定に現状はのっとった形で区としては対応しているものです。ただ、それが区の無償化の考え方と一致するかどうかということは、また別の問題かというふうに考えているところです。","id":"exchange-122"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今、８２自治体が無償化をしております。これが全国的な趨勢ですので、ぜひとも品川区でも無償化に取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-123"},{"speaker":"高橋（し）委員","kind":"質問","question":"そもそもこういった方々の異動等はどのような仕組みで決まるのでしょうか。区の固有教員の方が１人いらっしゃるとはお聞きしております。","respondent":"熊谷指導課長","answer":"Ｂ選考、そちらの方も昨今では指導主事になるということもございまして、教育総合支援センターの統括指導主事がＢ選考合格者です。ですので、実際にはどなたが来るかということは、区としての要望は出せますけれども、都と協議の上で教科等が決まってくるところです。","id":"exchange-124"},{"speaker":"高橋（し）委員","kind":"質問","question":"教科をお聞きしたところ、小学校は、これは専門の教科はないのでご自分の専攻という言い方になるのでしょうか。専門の指導主事、あるいは統括指導主事がいらっしゃらないという現状と、この状況は何年ぐらい続いているのか尋ねました。","respondent":"熊谷指導課長","answer":"なぜか、英語科の教員が指導主事選考を受けないという現状がございまして、都のほうでも非常に少ないというふうに聞いております。少なくとも平成２７年度、平成２８年度は英語科の専門の指導主事がおりませんでしたので、区の固有教員を指導主事として配置していた経緯がありま…","id":"exchange-125"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"区の教育委員会の中で英語の教育指導を引っ張っていく、あるいは進めていく、リーダーシップをとっていくということは大変重要なことだと思います。異動の要請のときに品川区のほうが、このような指導主事の方に来てほしいという要望を、具体的にどのような形で出していらっしゃるのか尋ねました。","respondent":"熊谷指導課長","answer":"英語科の指導主事が欲しいということを毎年申し上げているところですけれども、なかなかいないというところで配置にならなかった経緯があります。プロフェッショナルはいないのですけれども、一生懸命勉強して指導、助言ができるようにしています。","id":"exchange-126"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"どうしてもそういった能力をお持ちの方が必要になると思いますので、今後も東京都のほうに英語科の指導主事の方の配置を強く求めるということと。その多角的に分析した結果は、具体的にそこから明らかとなったこと、それを学校の現場でどのように活用しているか等を説明を求めました。","respondent":"熊谷指導課長","answer":"いわゆる正答率の分布を２５％ずつ分けたときに、一番高かかった子どもたちはそうした地域の行事に参加しているというところが見えてまいりました。そういったことで、各学校では活用しています。","id":"exchange-127"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"そして３つ目、マイスクールのほうは文部科学省から平成２９年度の、つい先月出されました。この全国的な傾向と、品川区における数的な面と、不登校の要因についてお聞きします。","respondent":"大関教育総合支援センター長","answer":"やはり家庭に係る状況という部分が１つの大きなキーワードで上がってきておりまして、不安の傾向、無気力の傾向が出ております。本区では学力の対応という部分もマイスクールのところで重要視するように、今、改善の見直しをしています。","id":"exchange-128"},{"speaker":"高橋（し）委員","kind":"質問","question":"不登校に関しては、また機会を改めてお伺いしたいと思います。今後の対応にもこういった調査を活かして、指導のほうをお願いしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-129"},{"speaker":"石田（秀）委員","kind":"質問","question":"私は１８６ページ、クラブ・部活動指導費関係についてお伺いします。例えばそのスポーツに対する経験がない方、この辺のところの現状というのですか、そのようなところはどうお考えになっているのか説明を求めました。","respondent":"大関教育総合支援センター長","answer":"そのスポーツの指導者として、現実的な課題として毎年各学校の管理職、校長は悩みとして抱えているところはあります。そこを補うために、ぜひスポーツの競技内容に詳しい方、地域の方などを外部指導者として副コーチのような形でお願いしたりしている現状にあります。","id":"exchange-130"},{"speaker":"石田（秀）委員","kind":"質問","question":"それぐらいまで、これはもう全国一律ですから、コーチングの資格をとれというと２００時間ぐらいやらなくてはいけないのです。それは各学校１人ではなくて、その点をもう１回お聞きします。","respondent":"大関教育総合支援センター長","answer":"これは私ども教育委員会としても今後の課題として、部活動指導者講習会というような形のあり方については、今検討を始めたところです。例えば講習会の場で講師としてご指導いただくような機会も今後検討すべきかとも思いますし、今後の課題というように捉えております。","id":"exchange-131"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひそれはやっていただきたいということと、もう一つ、先日の日曜日に少年野球連盟で野球教室をやりました。ぜひ年に１回なり２回なり、そのような集まりにもっと支援をしてあげるべきだと思うのだけれども、この辺の点のお考えを説明を求めました。","respondent":"池田スポーツ推進課長","answer":"そのほかに品川独自で指導者を育成するということが重要なことだとは思っております。これにつきましては、今すぐどうということではございませんけれども、ぜひ検討させていただきたいと思います。","id":"exchange-132"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もう少しペースを上げていただきたいというお願いと、それについてのお考え、その校舎がずっと改築中という子どもが出てきてしまうのです。その小・中学校がずっと改築中という子どもに対する配慮はどうお考えかというところもお聞かせ願いたいと思います。","respondent":"有馬庶務課長","answer":"７校、年間動いているということを考えると、なかなか簡単にペースを上げられないという現実があります。まさしくこのお子さんにとっても本当に成長が著しい段階で、できるだけそこは避けるような形で計画は立てていきたいというふうに考えております。","id":"exchange-133"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ペースを上げてほしいなと思いますし、小・中学校がずっと改築中という子どもに対する配慮も、やはりお願いしたいと思います。今そういう新人は多分多いのだろうなと思いますけれども、その辺の点がおわかりになったら、ぜひ教えてほしいと求めました。","respondent":"佐藤保育課長","answer":"幼稚園の資格の関係ですけれども、保育園に勤めている保育士に関しましては約５割ぐらい、４４％ぐらいの方が両方持っていると把握しております。新人の方に関しましては、委員ご指摘のとおり８割、９割ぐらいは持っているところだと認識しております。","id":"exchange-134"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"このような言い方がいいのかどうかわからないのだけれども、今、地域行事に非常に参加をしていただいているではないですか。そのような話が来ないよう何か指導というか、教育をするというか、何かそのようなことがあれば教えていただきたい。","respondent":"佐藤保育課長","answer":"一定のそういった関係ができるところではありますけれども、保育課も交えて施設長会等を頻繁に開いておりますので、そういった中で連携等していきたいと考えています。","id":"exchange-135"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それと１８６ページ、同じく１８６ページの教育指導費になるのかなと思いますが、性教育についてお伺いをいたします。帽子、衣類や水泳着におけるラッシュガード等の着用による紫外線対策を進めるべきと考えますが、ご見解を説明を求めました。","respondent":"大関教育総合支援センター長","answer":"例えば公民の教科書の中などでも、消費者としてどのようにやっていくか、そこはもう大切だというふうに学校現場も認識をしています。ただ、これまで個別の対応で、どうしても配慮が必要なケースというものは他区で実例がございましたので、それはもう個別の対応が必要かと思いま…","id":"exchange-136"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"それと、非常に３０代以下の若年層に対して大きな広がりを見せ、品川区としてはこのことについてどのように進めていくのか教えてください。１０代では２.５３％、なかなか中学生が助けを求める場所というのは、このハラスメントの相談体制について説明を求めました。","respondent":"大関教育総合支援センター長","answer":"特に７年生が一番多いかと思いますが、それからスクールハラスメントの対応、４点ご質問いただきました。あるいは教育総合支援センターの教育相談室のほうに相談があった場合には、そこはやはり見逃さず、丁寧に対応していきたいと考えております。","id":"exchange-137"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"東京都教育委員会から足立区教育委員会に指導が入って、性教育をどうしていくのかという議論が今、インターネット上でも大きく話題になっています。そのような中で、まず品川区としてこの性教育についてどのような教育をされているのか説明を求めました。","respondent":"大関教育総合支援センター長","answer":"具体的には４年生であれは体の発達、精通がある、異性への関心が高まるというような内容を４時間学びます。７年生であれば、９年生になりますとさらに具体的に性感染症、扱っております。","id":"exchange-138"},{"speaker":"石田（し）委員","kind":"意見","question":"１５歳以下だと１８９人が出産して８３９件の人工妊娠中絶があり、その選択率というものは８２％になっている現実がある。高校生、大学生など学生のうちに大きな損失をもたらしてしまう可能性が高いと思うのですが、その点について最後説明を求めました。","respondent":"大関教育総合支援センター長","answer":"異性の尊重をどのように考えていくのか、法や決まりということまで学んでいく、そういった今できることが何なのかという部分は引き続き研究してまいりたいと思います。","id":"exchange-139"},{"speaker":"南委員","kind":"質問・要望","question":"２６年も前の１９９２年、当時の文部省が出した通知には、登校拒否は誰にでも起こり得る。不登校の関係で区の認識を改めて伺いたいし、具体的な数字を教えていただきたいということ、２０００年から５年置きに教えてほしいと求めました。","respondent":"大関教育総合支援センター長","answer":"２０００年以降５年置きの実態および区の考え方、それから要因分析についてのお尋ねかと思います。クロス集計の中からも分析しておりますので、そういった内容について本区として引き続き対応を充実させてまいりたいと考えています。","id":"exchange-140"},{"speaker":"南委員","kind":"質問","question":"今日はどうなのかということもあわせて伺いたいと思います。そしてこういった対策に対して教育委員会の評価、どのように認識をしているのかも伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"あるいは１日はマイスクール五反田を活用しながらも、本区といたしましては適応指導教室の成果は出ているというふうに判断をしています。先ほど申し上げましたように、本区教育委員会が行う事業としてはまず学校復帰を前提としたものとして考えているところには変化はございませ…","id":"exchange-141"},{"speaker":"南委員","kind":"質問・要望","question":"母数は違うといっても数字そのものは微増、増えているわけですから、なくならない原因はどこにあるのかということを伺います。そのような点についてぜひ伺いたいと思います。","respondent":"大関教育総合支援センター長","answer":"先ほど言った東京都全体の出現率よりは品川区は抑えぎみになることができている要因の１つだというふうに受けとめて考えているところです。同時に関係機関と協力をして、必要な機関が必要な時点で必要な支援を差し伸べる体制をさらにこれからも継続していきたいと考えております。","id":"exchange-142"},{"speaker":"南委員","kind":"質問・要望","question":"このような気持ちにさせる、あるいはいじめがどうしても出てきてしまう、そのような状況をつくっているのではないかと思うわけです。そのような考え方をぜひとってほしいと求めましたが、いかがでしょうか、最後に伺います。","respondent":"大関教育総合支援センター長","answer":"子どもたちが学校生活の中で自分の居場所、役割を感じるということは、とても重要なことだと教育委員会も認識しておりますので、今後とも子どもたちの学校生活が実りある豊かなものとなるように、学校を支援してまいりたいと思います。","id":"exchange-143"},{"speaker":"南委員","kind":"質問・要望","question":"一人ひとりの子どもが、その友達と仲よく遊びたい、学校が楽しく行けるような、そのようなところになってほしいという願いは本当に大事にしていただきたいということを強調して終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-144"},{"speaker":"こんの委員","kind":"質問","question":"１９０ページ、１９３ページ、学校環境整備事業からお伺いしたいと思います。そこで貸し出しされた本は、返却された際、本の状態がどのような状況がありますか尋ねました。","respondent":"横山品川図書館長","answer":"そのうち書籍については、一般本、児童本合わせまして１万５,６６９件あります。それについては全体で２,０７４件ございまして、その中で免除をしたものが１,３３８件、ご本人にご負担いただいたものが７３６件ございました。","id":"exchange-145"},{"speaker":"こんの委員","kind":"意見","question":"貸し出しの本のクリーニングについて、あるいは消臭、抗菌などの殺菌消毒をする読書消毒機を４カ所の図書館に設置されていると認識をしております。機器の取り扱いはどのようにされているのか、現状をお知らせくださいとの意見を述べました。","respondent":"横山品川図書館長","answer":"五反田図書館、荏原図書館、大崎図書館に１台ずつと、品川図書館では購入して１台あります。アロマの香りがつくということで、これにつきましては子どもさんも非常に喜ばれて、自ら使うような形で利用が進んでいるような状態です。","id":"exchange-146"},{"speaker":"こんの委員","kind":"提案","question":"そしてその導入の経緯は指定管理者のご提案によるものということですが、いわゆるサービスでそれを設置してくれているという認識でいいのでしょうか。その指定管理者と区が契約をするときの契約書にそのようなことも設けられて設置がされているのか、その辺を説明を求めました。","respondent":"横山品川図書館長","answer":"ご好意といいますか、指定管理料の中の一部の使い方として、そちらのご提案をいただいている形ですので、そのような意味では経費は区が負担しています。","id":"exchange-147"},{"speaker":"こんの委員","kind":"提案","question":"その経費の中で指定管理者が提案をして、導入をしてくださっているということですね。そうすると、ほか残り６館のところでは、その指定管理料は、そうした図書の消毒機に使われる、そのようなことにはならないのか尋ねました。","respondent":"横山品川図書館長","answer":"各館いろいろな事情がございまして、スペース的に狭い館が多いので、置いてしまうことでかえって図書館全体が使いにくくなるようなケースもあります。ですから、そこは工夫をしないといけないということで、今のところは指定管理館では３館…","id":"exchange-148"},{"speaker":"こんの委員","kind":"質問・要望","question":"そうなると、そういう機会も捉えて、指定管理者にどうかそういうものを導入していただくような考えをお伝えいただきたいなと思います。私が１つ考えたのは、このようなものを活用して設置をするということも考えられるのかなと思ったのですけれども、いかがか尋ねました。","respondent":"横山品川図書館長","answer":"今導入している指定管理館の３館につきましては、たとえ業者が変わっても同じサービスを提供することは可能です。技術革新に伴っていろいろ新しいものを積極的に取り入れたいと思いますので、コンパクト化が進めば、ほかの館でも導入していきたいと考えております。","id":"exchange-149"},{"speaker":"こんの委員","kind":"質問","question":"こちらは小学校、中学校のプールの設備についてお伺いします。紫外線のことについてお話がありましたが、私もその紫外線に絡んで学校のプールの設備というところでお伺いしたいと思います。","respondent":"有馬庶務課長","answer":"学校のプールのひさしについてですけれども、プールは校舎の一体型になっているところと平場になっているところといろいろありますが、現在のところほとんどのプールはそういったひさしというものはついていないというところがほとんどだというふうに認識しております。","id":"exchange-150"},{"speaker":"こんの委員","kind":"質問","question":"プールサイドにはそうしたひさし、あるいは指導を聞いている時間帯で、熱中症のような症状を引き起こす場合もあるという懸念もあります。ですから、こうしたものをプールサイドに設置していくということが必要と考えられますが、いかがお考えか尋ねました。","respondent":"有馬庶務課長","answer":"今年の夏のような猛暑の中で３０分、４０分とずっと日なたにいるということになると、それだけで子どももダメージを受けるだろうと思います。今、改築校には日よけをつけているということもありますので、そういった対策も必要ではないかというふうに考えているところです。","id":"exchange-151"},{"speaker":"こんの委員","kind":"質問・要望","question":"ひさしは必然かなと思いますので、どうか今後の検討をしていただきたい、このように思います。日本の伝統・文化発信能力育成事業ですけれども、まずこの事業はどのような事業なのか、簡単に事業の概要をお知らせください。","respondent":"大関教育総合支援センター長","answer":"そのまま都から指定を受けることができますと、講師謝礼等、あるいは備品や消耗品を購入したりすることができるような内容となっております。子どもたちがアメリカ人のそのＪＥＴ青年に日本の文化を教えたりする、そのような取り組みなどを行っております。","id":"exchange-152"},{"speaker":"こんの委員","kind":"質問","question":"どのようにされているのか。そうしたことを見学するということも非常に学ぶ機会であると考えますけれども、こうした学ぶ機会の創出はどのようにされていますか尋ねました。","respondent":"大関教育総合支援センター長","answer":"伝統工芸ふれあい教室を、全校ではございませんが、実施しております。平成２９年度は８校が実施いたしまして、あるいは和竿など、区内のたくみの方のわざを実際に学ぶような機会を設けました。","id":"exchange-153"},{"speaker":"こんの委員","kind":"意見","question":"専門家の方々によるそうした授業、大事だと思います。この伝統の技と味／しながわ展、こうしたものも活用するとよろしいかなと考えますが、ご検討くださいとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-154"},{"speaker":"渡部委員","kind":"質問","question":"もともと６名採用というようなお話は伺っていたのですが、実際平成３１年４月、どのような体制になるのでしょうかということをお伺いしたいです。今２４名いる方、副校長の各職層に、どのような比率でいるのか説明を求めました。","respondent":"熊谷指導課長","answer":"東京学芸大学附属竹早中学校は本区と学芸大学との連携事業で、その子どもたちとの連携ということで、竹早中学校に今年度配置したところです。それから職層別ですけれども、職層は副校長１名、主幹教諭３名、主任教諭３名、教諭が１９名です。","id":"exchange-155"},{"speaker":"渡部委員","kind":"質問・要望","question":"コミュニティ・スクールなどもやっていて、地域と連携を図る中で、品川区の固有教員を各校に１人置いてほしいという要望を出し続けています。先ほどの金額を使えるのであれば、このようなところにしっかり使ってほしいと思うのですが、今後の区の固有教員の見通しを説明を求めました。","respondent":"熊谷指導課長","answer":"戦略的にアプローチしたさまざまな取り組みができているのも固有教員のいるおかげと思っています。本来ですと来年度１５中学校区に３０名が達成できるところだったのですが、まずは３０人の配置ということを目指していきたいと考えているところです。","id":"exchange-156"},{"speaker":"渡部委員","kind":"質問・要望","question":"これからいろいろ新制度に向けた周知等も始まると思いますから、ここはもう丁寧にやってくださいと、質問ではなく要望をします。ですから、それを紹介していったほうが早いと思うのですが、そこだけ考え方をお伺いします。","respondent":"若生学校制度担当課長","answer":"委員ご指摘のとおり、今後制度が大きく変わってくるところで、周知というものが重要になってまいります。確かに経過措置も含めますと複雑な制度になってまいりますので、保護者の皆様等にわかりやすく、あらゆることを視野に入れて検討してまいる所存です。","id":"exchange-157"},{"speaker":"渡部委員","kind":"質問・要望","question":"それはみんな家庭で食費は負担して、やっているわけですから、この給食費をただ無料にしろということは暴論だと私は思っています。２８０円、３２０円でしょうか、そのようなカテゴリーにて給食費が設定をされました。","respondent":"篠田学務課長","answer":"今後消費税の増税が考えられるという中で、そういったタイミングになると結構給食費自体も今厳しいというような状況もあります。どういった対応をしていくかということは、動向を見きわめながらきちんと考えていく必要があるものと考えます。","id":"exchange-158"},{"speaker":"渡部委員","kind":"質問","question":"そのような観点があるわけですから、その中でしっかりとした食材を提供し続けるということも、ある意味大事なのかなと思うのです。その辺は今すぐにそれはできる、できないという話ではないと思うのですけれども、検討を少し始めてほしいと思うのですが、いかがか尋ねました。","respondent":"篠田学務課長","answer":"子どもたちに安心・安全な給食を提供するために行政としてできることということで、今後ともそういった部分について、きちんと研究してまいりたいと考えているところです。","id":"exchange-159"},{"speaker":"渡部委員","kind":"質問・要望","question":"この仕組みで行われていくことと思いますが、全校で始まってみて、何か問題点等は生じていますでしょうか。この先、この制度を維持するために何か必要なものがあるとすれば、これからの品川教育ルネサンスの大事な１つですので、説明を求めました。","respondent":"熊谷指導課長","answer":"今後なのですけれども、課題というよりは、今度平成３１年の１月１９日、土曜日ですけれども、豊葉の杜学園でしながわ！そこでしながわＣＳＲ推進協議会の会員にも協力していただいて、地域の方々に発信していこうと考えているところです。","id":"exchange-160"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/295139?Template=document&Id=1462#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":116272,"voices":356}},{"id":"h30-20181116-4","meetingId":"h30-c-settlement","date":"2018年11月16日","dateIso":"2018-11-16","committee":"決算特別委員会","time":"午前１０時００分～午後 ５時０４分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を115件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問","question":"初めに、ＩＣＴの活用についてお伺いしたいと思います。区のアプリケーション配信状況についてお知らせください。","respondent":"中山企画部長","answer":"スマートフォンあるいはパソコンにおけるアプリケーションの活用というのは重要になっていると考えております。こういったものを配信し、区民サービスの向上、情報伝達に努めているものです。","id":"exchange-001"},{"speaker":"高橋（伸）委員","kind":"質問","question":"そこで質問をします。自動応答サービスＡＩチャットボットのメリットと、導入に当たっての問題について区の認識をお知らせください。","respondent":"中山企画部長","answer":"２４時間３６５日、区民からの問い合わせに対応できるという区民サービス向上の部分、若い人を中心に。職員のスキルも高めていく必要がある、このようなことが課題だというふうに認識しているものです。","id":"exchange-002"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"同じくＡＩ、チャットボットの導入についてお伺いします。ＡＩチャットボット導入に向けた今後の区の見解についてお知らせほしいと求めました。","respondent":"中山企画部長","answer":"こういう観点からしっかりと検討を進めていきたいと考えていますけれども、企業、事業者からの情報収集も行っているところです。効率化にもつながるか、こういう観点で導入の方法、対象業務について積極的に検討を進めてまいりたいと考えているところです。","id":"exchange-003"},{"speaker":"高橋（伸）委員","kind":"質問","question":"区として、たばこを吸える場所の整備を今後どういうふうにされていくのかという観点から質問します。あわせて、たばこをやめたい方の禁煙治療を支援する禁煙外来治療費助成の実績について、現在の申請数をお知らせください。","respondent":"福内健康推進部長","answer":"企業の管理者からの喫煙室設置に関する相談対応、普及啓発等に関する事務などを開始するほか、法および条例違反者に対する行政処分等も行う予定です。こうした新たな事務につきましては、適切に対応できるよう準備を進めております。","id":"exchange-004"},{"speaker":"高橋（伸）委員","kind":"質問","question":"主に屋内の規制が強化されるという認識をさせていただきました。次に、実際に区役所の庁舎内の喫煙所がどうなるのか、今後どのように整備していくのかをお聞きします。","respondent":"榎本総務部長","answer":"その中で、今回、先ほど説明があった法と条例の施行を受けまして、総合庁舎内につきましては、来年４月１日より全面禁煙としたいと考えています。それに伴いまして、来庁者用の喫煙所を建物の外に２カ所ほど設置する予定でおります。","id":"exchange-005"},{"speaker":"高橋（伸）委員","kind":"質問","question":"次に、まち中にある指定喫煙所についてお聞きいたします。区としてどういう考えで指定喫煙所の整備をしていくか説明を求めました。","respondent":"堀越地域振興部長","answer":"しかしながら、今後、都条例施行後の状況を見ながら、できるだけ可能性について検討していきたいと考えております。それからもう１つは、できるだけパーテーションを設置いたしまして、喫煙者と非喫煙者の方の分離を図っていきたいというふうに考えています。","id":"exchange-006"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"要望いたしまして、次の質問にいきたいと思います。多くの避難行動要支援者の方が避難できるよう、全ての町会・自治会で具体的な対応がなされていることの確認が必要なのではないかと考えています。","respondent":"曽田災害対策担当部長","answer":"そうした中で、先ほど委員からの紹介にあった避難行動要支援者の支援体制構築補助事業を区は平成２８年度から開始いたしまして。引き継ぎ、現在の支援事業を継続的に促すとともに、個別計画の作成が進むよう努めてまいりたいと考えているところであります。","id":"exchange-007","title":"町会・自治会支援"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"どういうふうに支援をするのか、具体的に、これからどのように支援をしていくのかお知らせしてほしいと求めました。今現在も取り組んでおられると思いますけれども、より一層深めていただきたいというところで、今後の展開を教えてほしいと求めました。","respondent":"曽田災害対策担当部長","answer":"全ての要配慮者をそのようなところに収容することは困難であり、まずは区民避難所における受入態勢を充実していくことが必要だと認識しております。この在宅の要配慮者に対する支援のあり方につきましては、今後…","id":"exchange-008"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"続きまして、スポル品川大井町と区の連携と、ホスピタリティハウスについてお伺いします。区と連携して東京２０２０大会に向けた機運醸成のためのイベント、そして教室等ができないものか、その可能性についてお伺いしたいと思います。","respondent":"安藤文化スポーツ振興部長","answer":"大井町の新たなスポーツを通した賑わいづくりに非常に貢献されているのではないかと考えております。今後、東京２０２０大会に向けて、機運醸成など、何ができるかＪＲと協議してまいりたいと考えています。","id":"exchange-009"},{"speaker":"高橋（伸）委員","kind":"質問","question":"続いて、ホスピタリティハウスについてお伺いします。ホスピタリティハウスの有意性の現状と今後の見込みについてお知らせください。","respondent":"安藤文化スポーツ振興部長","answer":"現在、誘致国が決定した場合には、敷地の一部を利用いたしましてホスピタリティハウスを開設していきたいと考えています。まだ現在のところは誘致国は決まってございませんけれども、いろいろな方法を通じまして積極的に誘致活動をしてまいりたいと考えています。","id":"exchange-010"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"次の質問に移らせていただきます。本区では、設置した場合、どのような内容になるのかお知らせほしいと求めました。","respondent":"安藤文化スポーツ振興部長","answer":"複数国のものもあろうかと考えています。設置国のＰＲだけではなく、区民の皆さんだけに限らず来訪者の方が繰り返し訪れて楽しいようなホスピタリティの内容ということで考えてあります。","id":"exchange-011"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"以上で私の質問を終わります。ありがとうございました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-012"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"２０年来、意見交換も行い、区に対してさまざまな要望を提出してきました。そしてもう１つ、近隣の方々から、このイベントに対する苦情等があったかについても、まず初めにお聞きしたいと思います。","respondent":"安藤文化スポーツ振興部長","answer":"今回も区をはじめ実行委員会、公園事務所、それからしながわ観光協会のほうにも１件もクレームは入ってございません。地域の皆さんによる実行委員会の方々の主体的な取り組みによって、観光地域づくりにつながるものができたというふうに考えてあります。","id":"exchange-013"},{"speaker":"石田（秀）委員","kind":"意見","question":"そのお考えをお聞かせ願いたいのと、全体の底上げは必要だけれども、地域を絞ってやっていかざるを得ないのだろうと思っています。そう考えると、やっぱり五反田から天王洲エリアが中心になってくるのかと考えていますが、その点についてのお考えも説明を求めました。","respondent":"安藤文化スポーツ振興部長","answer":"委員ご提案の品川の賑わいの創出については、その専門部会の水辺の部会の皆さんに図って検討していきたいと考えています。そのような中でもプライオリティとして、天王洲から目黒川を優先的に力を入れて取り組んでいきたいというふうにも考えてあります。","id":"exchange-014"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"都、国土交通省なりと折衝することも必要だと思っていますので、ここら辺についてもお考えをお聞かせいただきたい。この後ずっとそういう意味のレガシーにもつながると思いますので、天王洲地区、目黒川の整備計画もあわせてお聞かせほしいと求めました。","respondent":"藤田防災まちづくり部長","answer":"これに加えまして、区といたしましては、橋のライトアップ等についても、これまでの実験から本格実施に向けて準備を進めているところです。区といたしまして、引き続き、これに取り組んでいきたいというふうに考えてあります。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"もう１点言えば、あそこにも桟橋があるわけですから、お考えがあればそれは後で聞かせてください。次にもう１つ質問をしたいのは、大森貝塚遺跡庭園と品川歴史館について伺っていきたいと考えています。","respondent":"安藤文化スポーツ振興部長","answer":"それも先ほど言いました土器パネルとあわせて、体験型の事業が展開できるような形を考えてあります。バーチャルリアリティーを活用したＣＧによる縄文時代を再現できるような事業も、今後、展開できるような形で検討していきたいと考えています。","id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問","question":"そこら辺を生かすという考え方をもう１回お聞きしたいのと、例えば、電車から見えるように大きい横断幕を張ってもいいではないですか。学者の人もこれだけ書いていれば、それを読んでいる人も多くいるわけですから、そこら辺の環境整備の部分も改めてお聞きしたいと思います。","respondent":"安藤文化スポーツ振興部長","answer":"そういう部分の中で、観光の視点から歴史に由来するロマンは重要な観光のファクターというふうに私も考えてあります。そういうものについては、防災まちづくり部公園課と協議をしながら、できるところから早速進めていきたいと考えています。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"北品川駅の立体化についてお伺いします。北品川駅、そこについて、要望書も１月４日付で出しました。","respondent":"中村都市環境部長","answer":"旧東海道の景観と歩行者の安全に配慮した広場となるよう、引き続き、地域からのご意見をしっかりお聞きして進めてまいりたいと考えております。地域からの要望も非常に強いというところで、しっかりと区として進めてまいりたいと考えております。","id":"exchange-018"},{"speaker":"新妻委員","kind":"提案","question":"これまで公明党は、防災対策の強化を求め、一般質問等でさまざまな提案をしてきました。順次、各町会・自治会ごとにマニュアルの公開を要望しますが、見解を伺いますとの意見を述べました。","respondent":"曽田災害対策担当部長","answer":"現在は、現地確認の終了した避難所ごとに、これらの検討結果をマニュアル本文や施設の利用計画に反映するなどの作業を進めているところであります。ホームページに掲載することを検討しているところであります。","id":"exchange-019","title":"町会・自治会支援"},{"speaker":"新妻委員","kind":"提案","question":"これから改訂される「わが家の防災ハンドブック」でも、在宅避難の勧めを入れるよう提案いたしますが見解を伺います。毎年１１月１９日にはしながわ防災体験館でのイベントの開催や展示などを行い、東京都と連携した取り組みを要望いたしますが、いかがか尋ねました。","respondent":"曽田災害対策担当部長","answer":"在宅避難の考え方につきましては、改訂予定の防災ハンドブックには、そのための備えを掲載してまいる予定であります。特にイベント等は実施しませんが、備蓄の重要性、あるいは在宅避難の重要性を啓発してまいりたいと考えております。","id":"exchange-020"},{"speaker":"新妻委員","kind":"提案","question":"款別審査でもたけうち委員が質問いたしましたが、改めて、このチェックの必要性と家庭内トイレの使用についての意識啓発のお考えを伺います。そこで、トイレトレーラーもトイレ対策の１つとして視野に入れてはと提案いたしますが、見解を伺いますとの意見を述べました。","respondent":"曽田災害対策担当部長","answer":"ご提案のトイレトレーラーもこれらの対策の１つとなり得る可能性があるものと考えているところであります。今後もさまざまな状況を想定いたしましたトイレの充実と啓発に努めまして、発災時の安全安心、清潔なトイレの確保に努めていきたいと考えています。","id":"exchange-021"},{"speaker":"新妻委員","kind":"質問・要望","question":"そこで、２点お伺いいたします。提供された液体ミルクをむだにしないためにも、区の職員への認識を徹底してほしいと要望いたしますが、いかがか尋ねました。","respondent":"曽田災害対策担当部長","answer":"したがいまして、液体ミルクも要望すれば来ると考えております。避難所運営や、あるいは物資配送、これに携わる職員に徹底することは大変重要なことだと考えております。","id":"exchange-022"},{"speaker":"新妻委員","kind":"提案","question":"平成１５年６月の第２回定例会一般質問で、性的マイノリティの理解促進と行政文書のうち性別記載の不要なものは削除するよう提案しています。見解をお伺いいたしますとの意見を述べました。","respondent":"榎本総務部長","answer":"残り２２３件の様式につきましては、定期的に調査を行いまして、削除できるかどうかを検討してまいりたいと思います。その取りまとめは、人権啓発課で責任を持って行っていきたいと考えています。","id":"exchange-023"},{"speaker":"新妻委員","kind":"質問","question":"１点目は、ＬＧＢＴに対しての課題全般は、人権問題と考えるべきと思いますが、ご所見を伺います。２点目は、ＬＧＢＴ当事者の置かれている現状をどう捉えているか、どう認識されているか伺います。","respondent":"榎本総務部長","answer":"１点目につきましては、その中におきましても、さまざまな人権問題とともに解決していかなくてはならないというふうに認識をしています。職場での差別や医療機関での対応、それから遺産相続等、法的保護を課題として捉えているところです。","id":"exchange-024"},{"speaker":"新妻委員","kind":"提案","question":"そこで、現在、品川区の職員に対しての研修は、誰が、どの職員を対象に行っているのか伺います。今後の研修においては、一層配慮が進むよう、当事者の方が行う研修を提案いたしますが、いかがか尋ねました。","respondent":"榎本総務部長","answer":"今後の研修予定等ですけれども、講演会形式で性的マイノリティを課題として、平成２３年には世田谷区議をお招きして講演会を行っております。今年度につきましては、性的マイノリティの方の対応も含めた労働ジャーナリストの方の講演会を１２月に実施する予定です。","id":"exchange-025"},{"speaker":"新妻委員","kind":"質問・要望","question":"そこで、現状の確認と要望を込めて５点伺います。それぞれお伺いいたします。","respondent":"本城教育次長","answer":"スクールカウンセラーなど、あるいは養護教諭がＳＯＳにきめ細かく対応できるように努めているところです。相談のあった際は、ズボンの着用を認めるなど、必要な配慮について個別に対応をしてまいります。","id":"exchange-026"},{"speaker":"新妻委員","kind":"質問・要望","question":"ご所見を伺います。品川区でも法的な配慮を含めた相談ができるような体制を求めますが、いかがか尋ねました。","respondent":"榎本総務部長","answer":"総合相談、カウンセリング等を活用して対応していますけれども、みんなの人権１１０番等も活用していきたいというふうに思います。今後、その状況を見据えながら、女性相談員による法律相談につなげることが可能かどうかなどを検討してまいりたいと考えています。","id":"exchange-027"},{"speaker":"新妻委員","kind":"提案","question":"品川区でも条例策定も視野に入れた検討委員会の立ち上げを提案いたします。来年度改訂が予定されている品川区長期基本計画に、ＬＧＢＴをはじめ多様な生き方の支援を位置づけるよう要望いたしますが、それぞれ見解を伺いますとの意見を述べました。","respondent":"榎本総務部長","answer":"あまり低所得でない部分とか、そういうところもありまして、そういうものもさらに研究が必要なのかと考えています。いわゆるダイバーシティ＆インクルージョンという視点につきましては、長期基本計画の体系の中に位置づける方向で検討してまいりたいと考えています。","id":"exchange-028"},{"speaker":"新妻委員","kind":"質問・要望","question":"今回、さまざまな角度から現状や課題の確認をさせていただきました。だからこそ、この求める会の方々は、多くの地域で請願・陳情を出されております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"塚本副委員長","kind":"質問","question":"特にこの事業の中で立ち退き等で転居を迫られる方の支援策である住宅あっ旋事業は、執行率は約４０％で、実績６件ということになっております。住宅あっ旋事業の重要性に対する区の認識、それから現状の執行率にとどまっている原因について、初めにお伺いいたします。","respondent":"永尾福祉部長","answer":"区が間に立ってあっ旋をするということで、高齢者の住まいの確保という点では、大変効果がある事業だというふうに認識しているところです。なかなか課題はありますけれども、今後もそういうお声をきちんと把握しながら、さまざま事業を展開していきたいと考えているところです。","id":"exchange-030"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"款別審査で対象者の拡大、このような質疑がありましたけれども、改めてこの事業の特徴についてご説明をほしいと求めました。高齢者に物件を貸してもよいという理解を得るために、どのような周知をされているのか、その状況についてお伺いいたします。","respondent":"永尾福祉部長","answer":"いいなというふうに認識しても、来年度に向けての考え方といたしましては、また預託金の取り扱いについても検討していきたいと考えております。今後の取り組みとしては、また、宅建品川支部と共催で研修会の開催を予定しております。","id":"exchange-031"},{"speaker":"塚本副委員長","kind":"提案","question":"それからまた、どのような点が重要になると考えているのか伺います。品川区においても住宅部門と高齢者支援部門の連携強化のために、データ共有システムの構築を提案したいと思いますけれども、見解を伺いますとの意見を述べました。","respondent":"中村都市環境部長","answer":"区で独自に物件データベースを持つというところ、システムの構築については協議会の中で検討していきたいと考えております。そのときにあわせて国のセーフティネット住宅情報提供システムの運用を注視していく必要があると考えますけれども、協議会の中で検討してまいります。","id":"exchange-032"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"この住宅セーフティネット法が改正されたことによって、軽減策にどういうものがあるのかということを教えてほしいと求めました。高齢者の住宅生活支援サービス事業を推進していただきたいと要望いたしますけれども、これからの取り組みについて区の見解をお伺いしたいと思います。","respondent":"中村都市環境部長","answer":"これから検討する中では、少しでも実効性があるような、そのような制度の構築に努めてまいりたいと考えております。その内容も踏まえ、しっかりと検討を進めてまいりたい、そのように考えております。","id":"exchange-033"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"区内全域から我が地域にと、このような要望が出てくることが想定されますけれども、路線検討においては。あわせて路線検討に当たっての見解もお伺いしたいと思います。","respondent":"中村都市環境部長","answer":"区としましても、これまで交通事業者と協力しながら取り組みを進めてまいりました。財政負担の側面から、地域の方々、なるべく多くの方に利用していただくよう、そのような方策について、これから具体的な検討を進めてまいります。","id":"exchange-034"},{"speaker":"塚本副委員長","kind":"提案","question":"平成２４年第３回定例会一般質問で、コミュニティバス導入を提案し、導入に向けた提案をしてきました。地域公共交通会議をできるだけ早期に設置することを求めますが、設置のタイミングについて、区の見解を伺いますとの意見を述べました。","respondent":"中村都市環境部長","answer":"まず地域交通検討会は、地域交通の現状のあり方について検討する場としまして、平成２６年に任意の機関として設置いたしました。検討を開始する来年度ですが、導入の基本的な考え方を整理しまして、そしてルート選定の方向性を地域交通検討会を開催しながら進めてまいります。","id":"exchange-035"},{"speaker":"塚本副委員長","kind":"質問","question":"品川区は、平成２９年度に環境三計画改訂等経費を計上し、新たに品川区環境基本計画を策定しました。この計画策定に至る経緯と計画の概要、さらに計画の中で温暖化問題に対する認識や対策がどのように定められているのか伺います。","respondent":"中村都市環境部長","answer":"この策定に当たりましては、平成２８年度より策定業務を開始いたしました。アンケートの実施、そして学識経験者、区民、事業者から成ります協議会を開催して策定をしたものです。","id":"exchange-036"},{"speaker":"塚本副委員長","kind":"質問","question":"これらの事業について、道路やクールスポットについては、具体的な場所も含めて実績をお知らせください。暑さ対策として、効果をどのように評価しているかもお聞きします。","respondent":"中村都市環境部長、藤田防災まちづくり部長","answer":"まずミストにつきましては、平成１８年から２０年にかけて、真夏の暑い時期に戸越銀座商店街においてミストの発生機２台で実施しております。ＪＲ大崎駅西口バスターミナルにおきまして、来年度、停留所に設置される予定です。 平成１８年度から涼のみち整備事業といたしまして、遮熱性舗装、それから保水性の舗装に取り組んできたところです。遮熱性舗装では８度、保水性舗装では、１０度程度の温度を下げる効果があるということで認識をしています。","id":"exchange-037"},{"speaker":"塚本副委員長","kind":"質問","question":"今伺いましたけれども、遮熱性舗装と保水性舗装という２つの方式がありますが、使い分けの考え方について伺いたいと思います。遮熱性舗装については、２年後のオリンピック・パラリンピック競技大会に向けて、オリンピック後も見据えた今後の考えについて伺います。","respondent":"藤田防災まちづくり部長","answer":"現在の計画ですけれども、遮熱性舗装を行う予定でございまして、こうした舗装を毎年１カ所ずつ進めていくという考えです。今後の整備方針につきましては、それからもちろん地域の皆様方のご意見、このようなものも踏まえながら進めていきたいと考えています。","id":"exchange-038"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"遮熱性舗装、保水性舗装などの補助制度を活用して施策が展開できるのではないかというふうに考えますが、区の見解を伺います。効果的な打ち水施策によってクールスポット創出を推進してほしいとも要望いたしますが、区としてどのような施策が考えられるか説明を求めました。","respondent":"中村都市環境部長","answer":"例えば民間企業のＣＳＲの一環として実施したり、６商店街で実施されたり、そのような取り組みを行っております。このような普及啓発のためのさまざまな方法について、機会を捉えて努めてまいりたいと考えております。","id":"exchange-039"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"エコ＆バリアフリー住宅改修について、平成２９年度実績で、エコ目的の住宅改修が全体に占める割合について教えてください。遮熱性塗装など暑さ対策推進のため、予算全体の拡充を求めたいと思いますが、区の見解を説明を求めました。","respondent":"中村都市環境部長","answer":"引き続きこのような助成制度を使って耐震性能も上げるための屋根の軽量化とあわせて遮熱塗装などをしていただきたいと考えております。案内に努めるとともに、制度の利用者の声を踏まえ、予算についても適切な予算確保に努めてまいります。","id":"exchange-040"},{"speaker":"塚本副委員長","kind":"質問","question":"子どもに限らず、炎天下での区民の公園利用に対応するさらなる対策が必要と考えますが、どのような対策が考えられるか伺います。夏場の子どもたちの遊び場について、区としての考え方、見解を伺いたいと思います。","respondent":"藤田防災まちづくり部長、福島子ども未来部長","answer":"夏場には日よけとなるよしずを張る、このような遊具設置、あるいは管理の中でさまざまな対応をしてきたところです。区としてこれらについても承知をしていますが、先ほど申したとおり… 区内には、２５の児童センターがございまして、他区と比較いたしましても、かなり充実していると考えております。パパママ応援アプリの活用など、さまざまな媒体により、夏場の適切な子どもたちの遊び場について周知をしてまいります。","id":"exchange-041"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"体験型とのコンセプトなので、どのようなことが考えられるのか、現時点でのご所見を伺います。戸越公園、文庫の森とも池があり、区のご見解をお伺いいたします。","respondent":"中村都市環境部長","answer":"暑さ対策の考え方ですが、詳細はこれから検討していくですけれども、建物を建築する際にさまざまな可能性が考えられます。そして、自然の大切さと環境のかかわりについて、効果的に学習ができるように、そのような検討をしてまいります。","id":"exchange-042"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私からは、２３区で最低の福祉の改善と、高過ぎる国保料の引き下げを求めて質問いたします。この１２年間で特養ホームと老健施設の整備がどれだけ進んだのか、なぜ成果だと掲げたのか伺います。","respondent":"永尾福祉部長","answer":"特養ホームが３カ所で２３１床、認知症グループホームが５カ所で１３７床、看護と小規模と両方合わせて５カ所で１３７人というふうな実績があります。区といたしましては、高齢者の状態像や社会資源の状況、また保険料への影響…","id":"exchange-043"},{"speaker":"石田（ち）委員","kind":"質問","question":"そして、２３区で最も整備がおくれている最低の整備率を改善したいと区は考えているのか伺います。このままでいいと考えているのか、整備率がおくれていることで多くの不安を生み出していることを問題と考えないのか伺います。","respondent":"永尾福祉部長","answer":"在宅介護支援センターのケアマネジャーはそういう方について、どういうところで手助けができるか親身になって相談を受けているところです。そういうものをお聞きしながら…","id":"exchange-044"},{"speaker":"石田（ち）委員","kind":"質問","question":"最低の整備率を改善したいと考えていないのか、問題ではないのか伺いましたので、お答えください。","respondent":"永尾福祉部長","answer":"ですので、全ての施設についてすばらしく進んでいるというところはなかなか難しいのが現状だと考えています。これからもそういうところをきちんと調整しながら、つくるべきものはつくっていきたいというふうに考えております。","id":"exchange-045"},{"speaker":"石田（ち）委員","kind":"質問","question":"今、最低の整備率で聞いているのは、特養ホームと老健施設のことです。これを改善させたいと思われているのか、そしてこういう状況が問題ではないのかということを伺いましたので、その件についてお答えください。","respondent":"永尾福祉部長","answer":"特養、老健の問題ですけれども、先ほど申し上げましたように、過去５年間に必要性を感じて整備をしています。特養、老健のみが高齢者の幸せのための施設とは限りませんので、その他の施設も含めまして改善していきたいというふうに考えております。","id":"exchange-046"},{"speaker":"石田（ち）委員","kind":"質問","question":"区長が成果として掲げた、それが２３区で最低だということで伺ったのです。２年ありますが、８期まで２３区で最低のままでいくのか尋ねました。","respondent":"永尾福祉部長","answer":"平成２９年第２回の特養ホームの入所調整の進捗状況ですけれども、名簿の登録者が４３５人で、入所者が８１人、お亡くなりになった方が５２人というふうになっております。","id":"exchange-047"},{"speaker":"石田（ち）委員","kind":"質問","question":"改善しなくていいと考えているのか伺います。そして、区がこれから取得する林試の森公園隣の国有地、都有地についても続けて伺います。","respondent":"永尾福祉部長","answer":"ただ、区としても心を痛めておりますので、在宅支援についてより一層取り組んでいきたいと考えております。平成３１年度以降の用地の取得に向けて協議をしているところでございまして、内容について、またさらに検討をしていきたいと考えております。","id":"exchange-048"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"６割の方がどこかしか入れているという答弁でした。ですので、申し込まれて入れていない方が多くいるという現状をしっかりと認識してほしいと求めましたし、それでいいのか確認します。","respondent":"永尾福祉部長","answer":"やはり入りたいというご希望、数字的に見てもたくさんいらっしゃり、その方が入れない状況も認識しているということは事実です。予定されておりますのは、障害者の就労継続支援Ｂ型施設というところまでは検討の俎上に乗っておりますけれども、まだ未定となっております。","id":"exchange-049"},{"speaker":"石田（ち）委員","kind":"質問","question":"そして、この公有地には５階建てまで建設が可能だと思います。近隣住民の理解を得ながら、できる限りの定員数を確保してほしいと思いますが、いかがか尋ねました。","respondent":"永尾福祉部長","answer":"ここには看護小規模多機能居宅介護もつくる予定ですので、在宅の方で少し医療的な支援が必要な方についても、検討しているところです。公園に隣接している場所ですので、地域の方の生活が大幅に壊れることについては、区としてもそれを説明し切ることはできないと考えております。","id":"exchange-050"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ早急にさらなる増設計画を立てるべきと強く求めて次へ進みたいと思います。夫の年収４００万円、保険料負担は年１９万８,０００円ですが、家族構成の世帯が国保加入だと保険料は幾らになるのか伺います。","respondent":"福内健康推進部長","answer":"国保の構造的な問題ですが、加入者の年齢構成が高いこと、また、それにより医療費水準が高いこと、そして所得水準が低いことです。品川区の年収４００万円、４人世帯のモデルケースにした場合の国保料ですが、約４２万６,０００円です。","id":"exchange-051"},{"speaker":"石田（ち）委員","kind":"提案","question":"なぜ一般財源、つまり、税金を国保の子どもの均等割無料化に使うことが不公平なのか伺います。区が考える公平な税金の使い方とは何なのか伺いますとの意見を述べました。","respondent":"福内健康推進部長","answer":"区が考える公平な税金の使い方というご質問ですが、国民健康保険法に基づきまして、国民健康保険の被保険者の方が対象となっております。国民健康保険料をお支払いしていただいている方が、医療給付を適正に受けていただくことが国民健康保険においての公平性と考えています。","id":"exchange-052"},{"speaker":"石田（ち）委員","kind":"提案","question":"２３区区長会として、子どもの均等割無料化を求めているはずです。子育て支援にも大きくつながる子どもの均等割無料化を改めて求めますけれども、いかがか尋ねました。","respondent":"福内健康推進部長","answer":"子どもの均等割軽減につきましては、区はこれまでも特別区長会や全国市長会を通して国に求めているものです。国からは、法定外繰入金を解消、縮減するように求められておりまして、子どもの均等割軽減を区が独自に実施するということは困難です。","id":"exchange-053"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうした税金の使われ方が社会的にも要請されていますし、品川区も２３区長会で求めていると思います。それぞれを求めて質問を終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"安藤委員","kind":"質問・要望","question":"国土交通省は昨年１１月から国内の７空港で部品欠落の報告を求めていますが、半年間で何件の部品欠落があったのか伺います。それは目黒から五反田、大崎付近に当たりますが、この地域の危険性について国に確認しているのか伺います。","respondent":"中村都市環境部長","answer":"国からの説明では、外国の航空機も含めた落下物の予防低減策として、しっかりと進めていくというふうに聞いてあります。これは国からの説明では、機種や天候などから、最終的にパイロットが適切に判断するです。","id":"exchange-055"},{"speaker":"安藤委員","kind":"質問・要望","question":"何度もゼロになるのかと聞いても、今のように国に求めていくというだけで、この対策でゼロになるとも明言できませんでした。例えば、大井町上空では何メートル高くなり、またそのことにより音は何デシベル軽減されるのか伺います。","respondent":"中村都市環境部長","answer":"検討に当たってどのように安全を確保するかは国の責任において考えるべきものという考えです。大井町上空では、何メートル高くなり、何デシベル軽減されるのかですが、これも国が安全性も踏まえた上で検討する中で出す結論です。","id":"exchange-056"},{"speaker":"安藤委員","kind":"質問・要望","question":"国土交通省もできないという対策を区長は求めたのでしょうか。伺いたいと思います。","respondent":"中村都市環境部長","answer":"区としましては、検討に必要な技術がございません。国が検討するべきものに対して、区が検討するということに対して責任も持てるものではございませんので、国に対して求める以外の方法はないものです。","id":"exchange-057"},{"speaker":"安藤委員","kind":"質問","question":"これは区長の発言としてあまりにも軽過ぎないでしょうか。それぞれがどのようなトラブルだったのか、また、原因は何か、品川区は航空会社に抗議したのか伺います。","respondent":"中村都市環境部長","answer":"国からは飛行経路を逸脱した事案、また落下物に対する事案ということで、詳しい原因については調査中と聞いております。区としましては、国に対しまして徹底した再発防止と速やかな情報提供を引き続き行うよう、口頭で強く求めたところです。","id":"exchange-058"},{"speaker":"安藤委員","kind":"質問","question":"なぜ抗議をしないのか伺います。伺います。","respondent":"中村都市環境部長","answer":"航空会社を所管するのは国土交通省です。やはりそのような管轄する所管の国の機関に要求をしたほうがより効果的であるといった考えに基づくものです。","id":"exchange-059"},{"speaker":"安藤委員","kind":"質問・要望","question":"なぜ実現しないのか伺います。伺います。","respondent":"中村都市環境部長","answer":"区民の理解を深めるためには、国による教室型説明会を含めましたさまざまな形での説明や情報提供が必要と区でも考えております。アニメーションですが、これだけで説明の全てを行うことは現実的には無理であると区も認識しております。","id":"exchange-060"},{"speaker":"安藤委員","kind":"質問","question":"全然穏やかといいますか、抗議したのかと伺ったのですが、抗議するそぶりすら見えません。地元自治体の声を聞くために、２０２０年計画実施までに開かれる国の協議会、設置の目的と品川区は誰が参加することになっているのかご説明ください。","respondent":"中村都市環境部長","answer":"説明として、計画案が示された当初から地元の理解を深めるための丁寧な説明と情報提供、こういったものが示されてあります。特別区副区長および関係市の副市長で、目的は情報共有や意見交換、また国の協議会に反映するです。","id":"exchange-061"},{"speaker":"安藤委員","kind":"質問","question":"どういうことでしょうか。副区長が参加するとありましたが、区は計画への反対の意思表明をする考えがあるのかどうか、それぞれ伺います。","respondent":"中村都市環境部長","answer":"国に対し、さらなる具体的な対応策を求めていく必要があるというふうに考えてあります。したがいまして、引き続き丁寧な説明と情報提供を国に求めてまいります。","id":"exchange-062"},{"speaker":"安藤委員","kind":"質問","question":"改めて伺いたいと思います。伺います。","respondent":"中村都市環境部長","answer":"区民の方々から、区もいろいろと意見を伺っております。それは理解が得られている、得られていないの２つの選択というところでなくて、区が捉えているのは、理解が十分ではないという捉え方です。","id":"exchange-063"},{"speaker":"安藤委員","kind":"質問・要望","question":"伺いますけれども、区長選挙では、３人区長選挙に出ましたけれども、撤回を求めた２人の候補者の得票合計は５２％と半数を超えたこと。あわせて伺います。","respondent":"中村都市環境部長","answer":"理解が十分でないということについて、一番必要なものは、やはり丁寧な説明だと考えております。そういった方々、品川区内隅々まで情報が提供されるような取り組みに対して、やはりまだまだ求めていく必要があると考えています。","id":"exchange-064"},{"speaker":"安藤委員","kind":"質問","question":"なぜ住民の反対運動がこれだけ続いているのでしょうか。区が、区民の理解がないことを表明できない理由が何かあるのか伺いたいと思います。","respondent":"中村都市環境部長","answer":"今後も十分な説明会を施していただきたいですし、今、国に求めているところです。まだ実現はしてございません。","id":"exchange-065"},{"speaker":"安藤委員","kind":"質問","question":"改めて区長はどのような公約を掲げたのか、選挙広報に何と書いてあるのか伺います。そして、これはどういう意味なのか伺います。","respondent":"中村都市環境部長","answer":"これが根底になければ、その後、どのような対策を立てたとしても全く無意味です。国に対してさまざまな具体策を求めていく根底には、安全安心というものを一番優先した提案をしてくださいというふうに国に対して求めているものです。","id":"exchange-066"},{"speaker":"安藤委員","kind":"質問","question":"この区長選での審判、示された民意を区長はどう考えているのか伺います。伺います。","respondent":"中村都市環境部長","answer":"１つの原因で結果が決まるのではないというふうに感じているところです。そうした中で品川区は品川区民の立場に立って、丁寧な説明と不安の払拭を強く引き続き求めていかなければいけないという考えです。","id":"exchange-067"},{"speaker":"安藤委員","kind":"質問・要望","question":"ぜひ答弁をしていただきたいのですけれども、この品川区が反対しなくてどうするのですかという感情が、区民にあふれています。伺います。","respondent":"中村都市環境部長","answer":"やはりその中でも品川区は一番影響が大きい区だという認識のもとに、国に対していろいろな求めをしていかなければいけないというふうな状況です。国に対してさまざまな求めをしていくという立場で、引き続き、そのような考えで進めてまいりたいというふうに思ってあります。","id":"exchange-068"},{"speaker":"安藤委員","kind":"質問・要望","question":"委員長、区長自身の公約なので、区長に伺っているので答弁を求めてもらえますか。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"},{"speaker":"安藤委員","kind":"質問・要望","question":"改めて伺いたいと思います。一自治体が反対するわけにはいかないと発言し、反対しない意思表示を行ったのは、新ルートの容認表明そのものではないのか伺いたいと思います。","respondent":"中村都市環境部長","answer":"これはさまざまな意見が区に対して寄せられますけれども、もう少し説明をしっかりしてほしいというような意見が多数を占めております。地域の皆様方への丁寧な説明を国に対してしっかり求めていくというところで…","id":"exchange-070"},{"speaker":"安藤委員","kind":"質問","question":"区長、このような発言をしてきたのですから、自治体の長として反対を表明するべきではないですか。伺います。","respondent":"中村都市環境部長","answer":"経済社会の中の世界の中の日本ということを考えた中では、区もやはりそのような国の考えに対して一定の理解を示すものです。そのようなところに対して、環境影響に配慮した方策を具体的にしっかりと示すということが現時点で一番正しいと考えております。","id":"exchange-071"},{"speaker":"安藤委員","kind":"質問","question":"羽田新ルート計画は、区長と区議会が反対すればとめられます。共産党は、この計画を撤回させるため全力を尽くす決意を述べまして、質問を終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"},{"speaker":"いながわ委員","kind":"質問","question":"新たな集客イベントの誘致について、そして住宅等に対する助成金については、３点お伺いしてまいりたいと思います。観光以外の観点でも考えていく必要性があると思いますが、本区のＭＩＣＥに対する捉え方、そして考え方をお知らせください。","respondent":"中山企画部長","answer":"今、委員からもご紹介がありましたように、経済的な効果が通常の観光に比べても高いというふうに言われております。このような地の利も考えると、こういうものの可能性を高めていくことは非常に重要である、こういうふうな認識を持っているものです。","id":"exchange-073"},{"speaker":"いながわ委員","kind":"質問・要望","question":"品川においては、滞在型の都市型観光の考え方でＭＩＣＥ品川の誘致推進を前向きにお考えいただきたいのですが、本区のご所見をお伺いします。既存の区有施設の有効利用や、新設の集客施設の整備も前向きにお考えいただきたいのですが、本区のご所見をお伺いいたします。","respondent":"安藤文化スポーツ振興部長","answer":"そこの中でアフター５の観光、または比較的短時間で品川区を楽しめるような観光等、開発の充実に努めているところです。今後も一般の観光客に加えて、ご提案のＭＩＣＥ品川の可能性についても検討していきたいと考えています。","id":"exchange-074"},{"speaker":"いながわ委員","kind":"質問・要望","question":"非常に前向きなご答弁をありがとうあります。ぜひそれをうまくコラボレーションしていただいて事業を進めてほしいと求めましたが、改めて何かございましたらお願いします。","respondent":"中山企画部長","answer":"そういう１つの例になろうかと思いますが、なかなか施設的な対応が難しいということ、宿泊の課題等もあろうかと思います。区の中のさらに大きな対応もできるような考え方についても幅広い視点で、区の中でも促進するような視点を入れて考えていきたいと考えております。","id":"exchange-075"},{"speaker":"いながわ委員","kind":"質問・要望","question":"そして、今後、長期基本計画の策定の時期でもあります。ぜひこうした視点も盛り込んで議論をしていただきたい、そのように思っておるのですが、本区のご所見をお伺いします。","respondent":"中山企画部長","answer":"こういうものは今後とも区の重要な課題になってくるということで、長期基本計画の中でもしっかり検討していく。そういう点では、このＭＩＣＥもそういう観点の中の１つの要素になろうかと思いますので、長期基本計画の中でも今後考えていきたいと思います。","id":"exchange-076"},{"speaker":"いながわ委員","kind":"質問","question":"新たな集客イベントの誘致についてお伺いしていきたいと思います。本区において、このｅスポーツについて、どのようなご認識があるかをお知らせほしいと求めました。","respondent":"安藤文化スポーツ振興部長","answer":"主に１０代、２０代、３０代と、高校生や大学生を中心に盛り上がりを見せていると認識しております。そのような中で、まだスポーツとして確立されていないという認識はあります。","id":"exchange-077"},{"speaker":"いながわ委員","kind":"質問・要望","question":"誘致に向けた調査や研究を積極的に行ってほしいと求めましたが、区のご所見をお伺いしたいと思います。これは先ほど質問したＭＩＣＥとは多少それるかもしれませんが、ぜひ前向きなご答弁をお願いいたします。","respondent":"安藤文化スポーツ振興部長","answer":"つい先日、韓国で行われた大会では、３万人もの集客力を有したというふうに報道がありました。開催可能かどうかということを、今後しっかり研究調査してまいります。","id":"exchange-078"},{"speaker":"いながわ委員","kind":"提案","question":"次は、住宅等に対する助成金について、３点お伺いしてまいりたいと思います。パソコンやスマートフォンを使った助成制度の検索や受けられる概算金額の算出などができるインターネットサイトの開設を提案させていただきましたがとの意見を述べました。","respondent":"中村都市環境部長","answer":"委員ご指摘のように、インターネットサイトでの検索が非常に使いやすいものであれば利用される方々にとって大変有益なものであると考えています。今現在は、ホームページでの現在の周知に加えまして、一歩進んだ啓発になるという考えのもと、実施に向けました検討を行っているで…","id":"exchange-079"},{"speaker":"いながわ委員","kind":"確認","question":"制度活用がより一層進むものと考えております。改めての確認になりますが、こうした認識は必要だと考えていますが、いかがお考えか尋ねました。","respondent":"中村都市環境部長","answer":"その金額の概算がわかるということは、建て替えの判断をする際に大いに参考になるということで、事業推進の大きな後押しになると考えています。さらに商売につなげていただくというところも可能性としてあると思いますので、引き続き、検討してまいります。","id":"exchange-080"},{"speaker":"いながわ委員","kind":"質問・要望","question":"私を含む会派の要望が実現したということであり、本当にこのブロック塀の除去助成の創設に関しては、高く評価するところであります。３点について、それぞれのご所見をお伺いいたします。","respondent":"中村都市環境部長","answer":"今回のブロック塀の除却の助成につきましては、区民の早急な安全性の確保のための対応策といたしまして、緊急的に実施をするところです。これはやはり法４２条２項道路という、なかなか難しいところではありますけれども、丁寧に説明をしていくというところが大事だと思います。","id":"exchange-081"},{"speaker":"いながわ委員","kind":"質問・要望","question":"１つの資産でもありますので、法律の壁は超えられないと思いますので、しっかりとした周知をしてほしいと求めました。ぜひこのようなブロック塀、同じような３つの助成金があるわけですから、いかがか尋ねました。","respondent":"中村都市環境部長","answer":"このようなブロック塀の安全化対策につきましても、区民が安心して暮らせる住環境の確保のための重要な事業と捉えております。インターネットを含めたさまざまな周知を行ってまいります。","id":"exchange-082"},{"speaker":"いながわ委員","kind":"提案","question":"そこで、ここは１つ提案です。このワンストップサービス、窓口の設置を強く求めていきたいと思いますが、本区の前向きなご答弁をお願いしますとの意見を述べました。","respondent":"中村都市環境部長","answer":"区役所へ相談や手続においでいただいたお客様の対応につきまして、都市環境部があります本庁舎６階にほとんどの窓口が集約されているという状況です。しかし、委員ご指摘のように、窓口における利便性のさらなる向上は常に意識していくべきものですので…","id":"exchange-083"},{"speaker":"いながわ委員","kind":"質問・要望","question":"他課にわたっているものを１つの窓口でやるということが、実施に向けてやってほしいと求めましたので、よろしくお願い申し上げます。これで私の質問は終わりますが、ぜひ区政をさらに前へ大胆に牽引をしていただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-084"},{"speaker":"須貝委員","kind":"意見","question":"この状況についてご見解をお話しください。この地域ほどではありませんが、このような状況は今の品川区やこれからの品川区に当てはまると思いますが、ご見解を説明を求めました。","respondent":"中村都市環境部長","answer":"鉄道事業者に関しましても、計画段階から情報共有、また説明を行いまして、協議を行いながら計画を進めているところです。それから、計画段階から関係所管と予想される増加人口等を情報共有の上、対応を進めているところです。","id":"exchange-085"},{"speaker":"須貝委員","kind":"質問","question":"一部で住宅の容積率緩和などをやめる方針に転じていますが、区では、長期計画に縛られて方針転換はしないのですか。それともできないのか尋ねました。","respondent":"中山企画部長","answer":"子育ての支援等による自然増もあります。そういうものについては手立てを打っていく、こういう観点で長期計画の視点でも今後とも考えていきたい、このように考えているところです。","id":"exchange-086"},{"speaker":"須貝委員","kind":"質問","question":"施設を一時的にもつくらなければいけない。そういうことに関して、どのようにお考えか尋ねました。","respondent":"中山企画部長","answer":"それに対する対応は当然やっているということでありますけれども、税収にもつながる、区民の方が来るからこそ需要が出てくるです。あるいは、行政需要の変化に対応できるような施設のありようを整備の段階から考えていくとか、ときどきの需要に対応していくというのは。","id":"exchange-087"},{"speaker":"須貝委員","kind":"質問","question":"やはりご迷惑をかけるということがありますので、私は、少し修正ということを考えてほしいと思います。そして、今後の対応について説明を求めました。","respondent":"藤田防災まちづくり部長","answer":"今、そこで断線してしまうようなケースもあるということで、そのようなことにならないように耐震性の強化を進めるべきというふうに考えてあります。あるいは、それぞれの事業者のほうで…","id":"exchange-088"},{"speaker":"須貝委員","kind":"質問","question":"冬の１８時、風速８ｍ、車はそこで立ち往生するのではないですか。それに耐えられるかどうかという定めはないように聞いていますけれども、実際、大丈夫なのか尋ねました。","respondent":"藤田防災まちづくり部長、中村都市環境部長","answer":"基本的には車を置いて避難をしていただくということで、車を使わないということが前提にありますので、そのような中で混乱はないかと考えています。全ての信号ではございませんが、主要な交差点の信号については… ただ、委員もご指摘のとおり、飛来物によってガラスが割れて飛散したという例は、過去にも確かにあります。不燃化を進める地域の中では、バルコニーを設置することによって飛散をそこで受けとめるというような…","id":"exchange-089"},{"speaker":"須貝委員","kind":"質問・要望","question":"では、その車が邪魔だからどけてほしい。区で別に設置している免震ゴムの性能が生かされるため、建物にとってはより安全になると考えられますが、どうか尋ねました。","respondent":"榎本総務部長","answer":"どれくらいの性能なのかというところをまず調べるというところが第１点だと考えています。建築基準法上の基準は満たしておりますので、まずは構造計算を先に進めていきたいと考えています。","id":"exchange-090"},{"speaker":"須貝委員","kind":"質問","question":"実際、いつこれは修繕できるのですか。その辺も考えないといけないのではないか尋ねました。","respondent":"榎本総務部長","answer":"最終的にはＫＹＢ社に不良品の交換をすることを求めていきますけれども、全国的に数が多いということで、見込みは立っていないところです。役割分業していますので、ダンパーが一部不良だからということだけで…","id":"exchange-091"},{"speaker":"須貝委員","kind":"質問・要望","question":"震度７以上になると、この建物は危険ですと私は周知するべきではないかと思いますが、ご見解をお聞かせください。不安から多くの区民が助けを求めて集まってくると思いますので、緊急に改善が必要だと思いますが、対応策を説明を求めました。","respondent":"榎本総務部長","answer":"今後、詳細がわかった段階で、また新たに周知を進めてまいりたいと思います。議会棟も使いますので、今後検討していかなければいけないと思いますけれども、そういうのところの対応を考えていかなければいけないと思います。","id":"exchange-092"},{"speaker":"須貝委員","kind":"質問・要望","question":"教えてください。説明を求めました。","respondent":"本城教育次長","answer":"品川区といたしましては、その中で、いろいろな要因でなかなか十分に学力が満たせていない子どもたちは一定程度いると考えているところです。いわゆる補習等を通じて、一人ひとりに対してしっかりとした対応をしていくことが必要だと考えているところです。","id":"exchange-093"},{"speaker":"須貝委員","kind":"質問","question":"どうなっているのですか。一体どこに問題があるのか尋ねました。","respondent":"本城教育次長","answer":"それらを含めて、今、十分に学力が身についていない子どもに対しても着実に対応しています。品川区固有の教員だと考えていますので、子どもたちの力を着実に伸ばせるように進めておりまして、それが実現しつつあるところだと考えています。","id":"exchange-094"},{"speaker":"須貝委員","kind":"質問","question":"学校からこういう定期テストのデータなどがきちんと教育委員会に届いているのですか。それについてもう１回説明を求めました。","respondent":"本城教育次長","answer":"一次的には各学校が把握して対応すべき問題だと思いますが、この間、しっかりと充実した体制を整えてきたと考えているところです。","id":"exchange-095"},{"speaker":"須貝委員","kind":"意見","question":"私は、やっぱり１つ１つ学校にきちんと定期テストはどうなっているのか、どのぐらいの学力があるのか、きちんと把握してほしいと思います。その辺について、もう１回ご見解を説明を求めました。","respondent":"本城教育次長","answer":"それはもちろん全体的なものだけではなくて、各学校単位でもどういう課題があるのか、それも含めて把握しています。一般の授業のほかに補習授業等も通じて個々に対応して、しっかりとしたフォロー体制を整える中で充実した教育を実施しているものと考えております。","id":"exchange-096"},{"speaker":"須貝委員","kind":"質問・要望","question":"社会でみずから生き抜いていける基礎学力は、やっぱり身につけさせてほしいし、これは学校と教育委員会の責務だと思います。これから頑張ってほしいと求めました。","respondent":"米田総務課長","answer":"先ほど、３時ごろですけれども、大井２－１３のあたりで煙のようなものが上がり、火災ではないかと消防に通報があり、消防自動車が急行したものです。現場を確認したところ、特に火災の事実はなく、細かな状況については、現在も調査中です。","id":"exchange-097"},{"speaker":"吉田委員","kind":"質問・要望","question":"生活者ネットワークは、権利擁護と苦情処理のため、区とは完全に独立した第三者的な機関が必要であるとして設置を求め続けております。障害者に絞り、かつ区の施策に対してということに絞って区に苦情の申し立てがあった場合、どのような手続で第三者的に処理をしているか伺います。","respondent":"福島子ども未来部長、永尾福祉部長","answer":"区民の声ではおおよそ２週間、速やかに対応していますので、数日で回答しております。来年度設置を検討しておりますが、苦情の数自体も少ないですし、その必要性を含め考えていきたいというふうに思っております。 実際の支援サービスにつきましては、直接処遇をしている事業者でまず対応し、事業者が設置している第三者委員会にかけて。障害者の場合だと東京都社会福祉協議会で運営適正化委員会を設置しておりますので…","id":"exchange-098"},{"speaker":"吉田委員","kind":"確認","question":"２０１２年の質問に答えたとおり、基本的には一番最初は当該のサービス事業者ということでよろしいでしょうかという確認と、それから。子どものことは大体２週間か数日でというお答えがありましたけれども、高齢者、障害者についてはいかがかお知らせください。","respondent":"永尾福祉部長","answer":"本当に１週間、２週間で解決するものもあれば、半年以上かかってしまうものもあります。なかなか両者の主張の折り合いがつかなかったりというところで、難しいケースが、件数的にはとても少ないですけれども、あることはあります。","id":"exchange-099"},{"speaker":"吉田委員","kind":"質問・要望","question":"それはどうなのでしょうか。しかし、そこから完全に独立した人権問題や行政不服申立の制度に詳しい弁護士や学者をメンバーとした第三者機関を求めたいと思いますが。","respondent":"福島子ども未来部長、永尾福祉部長","answer":"利用者のお声を聞くということは非常に大切なことだと考えておりますので、今後とも周知を図りまして、さまざま区民の皆様の声を聞きながら施設運営に当たっていきたいと考えております。 重要事項説明書の中には、どうしても預けている方の関係で事業所に申し出にくい場合は、直接受ける先についても記載はきちんとされているところです。今の制度でいけば区の中で第三者委員会を設置しなくても…","id":"exchange-100"},{"speaker":"吉田委員","kind":"質問・要望","question":"国の協議会にあわせて開かれている部長級の幹事会が既に１５回開かれていて、２３区５市の意見の確認はできていると都の担当者は言っています。２３区５市の意見の確認ということは、その中に当然品川区の意見が含まれていると思います。","respondent":"永尾福祉部長、中村都市環境部長","answer":"利用者やご家族への説明不足だったり、連携が不足しているとか、そういうことが挙げられております。まずはそういうことにならないようにする取り組みを進め… その際、教室型説明会を含むさまざまな方法を検討するです。丁寧な説明、さまざまな方法で説明会を行うこと、このようなものが基本的な内容です。","id":"exchange-101"},{"speaker":"吉田委員","kind":"質問・要望","question":"根強い反対の声があるということは、きちんと言っていただきたいと思うのですが、その点についてはいかがでしょうか。ご見解を伺います。","respondent":"中村都市環境部長","answer":"教室型説明会を含むさまざまな方法を行っていただきたいというところで、「教室型説明会を含む」というふうにここに入れております。ただ、これまでも継続して強く求めているにもかかわらず、なかなか国としてもこの要望が聞き入れられないという状況です。","id":"exchange-102"},{"speaker":"吉田委員","kind":"質問・要望","question":"では、現時点では、説明会を求めるまでは先に進めないというようなことで発言していらっしゃると理解してよろしいでしょうか。その検討内容をどういう形で決めていこうとされているのか、その辺について改めてご答弁を伺いたいと思います。","respondent":"中村都市環境部長","answer":"現時点におきましては、委員ご指摘のとおり、丁寧な説明と情報提供、またさまざまな方法の説明会です。ただ、本当に未定ですので、そのプロセスも含めましてお伝えすることができず本当に申しわけございません。","id":"exchange-103"},{"speaker":"吉田委員","kind":"質問・要望","question":"現時点では、教室型の説明会を求め続けているにもかかわらず開かれていない。得られていないということと、根強い反対の声があるということをきちんと言うべきと考えますが、その辺についてもご見解をお尋ねします。","respondent":"中村都市環境部長","answer":"したがいまして、これをあえてまたこの連絡会あるいは協議会の場で言うかどうかについても未定です。どのような内容で決定していくかのプロセスにつきましても、これも今後、発言する内容によって決定のプロセスは変わってまいると考えております。","id":"exchange-104"},{"speaker":"吉田委員","kind":"質問・要望","question":"そのさまざまな意見の中に、ちゃんと根強い反対の声があることを入れてくださっているのかということを確認させてほしいと求めました。かつ、適正に管理した上で公開すべきと考えますが、その点についてもいかがか尋ねました。","respondent":"中村都市環境部長","answer":"ただ、区としての意見としては、やはり丁寧な説明、情報提供、そしてさまざまな説明会というところが意見としては申し伝えているところです。これはその会議の状況によりまして、今現在、ここではご説明はできないところがあります。","id":"exchange-105"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、そのさまざまな意見として、ちゃんと反対意見を伝えてほしいというのが今の質問です。もちろん議事録確認をしていただいて、品川区としてちゃんとその発言内容を検証できるような形で残すべきではないかと申し上げております。","respondent":"中村都市環境部長","answer":"ただ、そこに反映されていないということになりますと、これは必要に応じて修正を求めることはしていかなければいけないというふうに考えております。これは委員のご指摘のとおりです。","id":"exchange-106"},{"speaker":"吉田委員","kind":"質問・要望","question":"だから、どういう発言をこういう場でしてくれているかをきちんと確認できるような形、だからもちろん議事録の中に全部明記されればいいですけれども。それを品川区の例規集の中に掲載すべきと考えますが、いかがか尋ねました。","respondent":"榎本総務部長","answer":"共通の基準、わかりやすいものができるかどうか、それについては検討していきたいと思います。その中でどのように検討できるかということを進めてまいりたいと考えています。","id":"exchange-107"},{"speaker":"吉田委員","kind":"質問・要望","question":"ですので、ぜひこれについては、私たちが拝見して、また納得のいく措置報告書が出されることを強く求めたいと思います。そういうことを示すこと自体が品川区への区政の信頼につながると考えますが、ご見解を伺います。","respondent":"榎本総務部長","answer":"委員ご指摘の部分もそれぞれあると思いますけれども、全体として大量の文書、それも紙文書と電子文書をそれぞれ管理しているということで、その中で最善の方法を探っていきたいと思います。","id":"exchange-108"},{"speaker":"吉田委員","kind":"質問・要望","question":"文書の管理について、品川区としての基本的な考え方をお示しほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-109"},{"speaker":"渡部委員","kind":"質問・要望","question":"品川区におきましては、引き続き、区民の福祉・生活の向上に努められますことを要望します。補助率を２分の１に引き上げていただいた経緯はありますが、さらに補助率をかさ上げできないか検討をいただけないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-110"},{"speaker":"若林委員","kind":"提案","question":"款別審査の中での意見、提案を十分に検討し、来年度の予算編成や改訂される長期基本計画に反映されるよう要望します。引き続き区政を付託された濱野区長を先頭に、品川区の発展に努められますよう求め、意見表明といたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-111"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２９号線のために地域に愛されてきた大崎図書館解体は今からでもやめるよう求めます。福祉を充実させ、区民の願いにこたえる区政運営を求め、意見表明とします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-112"},{"speaker":"石田（し）委員","kind":"提案","question":"歳入総額は２３億円増、実質収支は６２億円の黒字を維持し、本区の堅実な財政状況が示されています。本決算特別委員会での我が会派の指摘や提案を、次年度予算をはじめ今後の施策に反映するよう強く要望してとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-113"},{"speaker":"須貝委員","kind":"質問・要望","question":"特に低賃金で社会を支えている保育士、幼稚園教諭、介護士の処遇改善や防災拠点でもある区役所の耐震機能の改善を早急に実施していただきたい。通勤・通学に利用する鉄道の混雑緩和に力を注ぐとともに、公立中学校の低学力層の学力向上に全力で取り組んでいただきたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-114"},{"speaker":"田中委員","kind":"提案","question":"行政情報を積極的に開示し、区政への住民参加を推進すべきという立場で、品川・生活者ネットワークは事務事業の点検と政策提案を行いました。各款別審査で指摘・提案させていただいた意見を、予算編成に生かしていただくことを要望して…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-115"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/295139?Template=document&Id=1464#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":100392,"voices":249}},{"id":"h30-20181120-10","meetingId":"h30-cm11","date":"2018年11月20日","dateIso":"2018-11-20","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時１２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件整理しています。","topics":[{"id":"topic-01","title":"平成３０年第３回定例会","agenda":"平成３０年第３回定例会","exchanges":[{"speaker":"伊藤委員","kind":"質問・要望","question":"固定資産税・都市計画税の軽減措置の継続を求める意見書についてご説明いたします。本意見書は、東京都が現在実施している固定資産税および都市計画税に係る軽減措置を、平成３１年度以降も継続するように求めるものであります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-001"}]},{"id":"topic-02","title":"区議会防災訓練の実施","agenda":"区議会防災訓練の実施","exchanges":[{"speaker":"石田（し）委員","kind":"確認","question":"以前もあくつ委員から、防災服をいつ着るのかという質問があったかと思うのですけれども、その辺の確認が１点。来ていますよという出欠みたいなものをとるのか、それともなにか新しい試みでもあるのかどうか、そこだけ説明を求めました。","respondent":"久保田区議会事務局長","answer":"２点目の、今回は区議会の訓練と区の行う区内一斉防災訓練を合同で実施するということになりましたので、報告をお願いしているものです。そういうことで確認をとってあります。","id":"exchange-002"},{"speaker":"石田（し）委員","kind":"質問","question":"ほかの議員がどうするのかといった中で、区議会と行政が一緒にやるということは、そういうことも含めてのことなのか。どうしてあえて一緒にやるみたいなことを言っているのか、避難所訓練に参加しても、その辺はどういうふうに考えているのか説明を求めました。","respondent":"久保田区議会事務局長","answer":"区の対策本部と区議会の対策本部との情報の連携等をどうやって図ろうかということを確認するための訓練が、まず１つです。区の防災課等とも連携をしながら、協議しながら、進めていきたいと考えています。","id":"exchange-003"},{"speaker":"石田（し）委員","kind":"確認","question":"局長から説明があったので、それをやるのかなとも思うのだけれども、これはあくまで安否確認のメールだけとなっているのです。なので、何を議員がこの訓練でやるべきなのかというのは明確にしてほしいというのがあって質問をしたので、そこだけ最後に教えていただけますか。","respondent":"久保田区議会事務局長","answer":"前回は、区内一斉防災訓練は昨年の１２月上旬に行いました。午前中に１回本部を開いて、本部訓練は午後からやられたほうがいいのではと考え、こういう形でご提案をさせていただいたです。","id":"exchange-004"},{"speaker":"あくつ委員","kind":"確認","question":"防災服に関しては、逆に防災服を着ていったら浮いてしまう可能性があるので、それだけは議論の前提として。議論して、着ていくというのもありだと思うのですけれども、一応確認です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"石田（秀）委員","kind":"意見","question":"その地域の人間なわけです。いいと思うのだけれども、わざわざ「私たち、議員です」と災害のときに腕章をつけていく必要はないと私は思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"石田（し）委員","kind":"意見","question":"その辺をどうするかというのは、どうしていこうかみたいなことを話すなら、しっかり今の時点である程度持っておいたほうがいいのかなと。そこだけでもある程度決めておかないと、やる意味があるのかなと思ってしまったので、ぜひそこはとの意見を述べました。","respondent":"渡部委員長","answer":"それはご自由に送っていただくという形で、ただ、最低限各会派１人は出してくださいということの取り決めでいかがでしょうか。〔「安否は全員送るというのだから」と呼ぶ者あり〕","id":"exchange-007"}]},{"id":"topic-03","title":"議長会等の報告","agenda":"議長会等の報告","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"今の法務局のところの話なのだけれども、あそこは基本的には、完全に仕分けされているのですか。一回、法務局の中みたいなところを通るのではなくて。","respondent":"久保田区議会事務局長","answer":"右側のほうに行ってしまいますと、法務局の中に入ってしまいます。昔でいうメール室があったところを通っていきますので、法務局とは分かれていますので、大丈夫です。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"あそこは入ってはいけないと私は思っていたのですけれども、特別にその期間だけ大丈夫ということでいいのか尋ねました。","respondent":"久保田区議会事務局長","answer":"入っても構いませんし、今回はエレベーターが使えない状態になっていますから、ご利用は問題ありません。経理課にも確認しています。","id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/460499?Template=document&Id=5306#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":14571,"voices":59}},{"id":"h30-20181205-10","meetingId":"h30-cm12","date":"2018年12月5日","dateIso":"2018-12-05","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時４１分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/460499?Template=document&Id=5308#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2018-01-01&TermEnd=2018-12-31"}],"sourceMeta":{"pages":0,"characters":4271,"voices":18}}]);
